INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用了不该用的东西，或者用得太多。", "primary_collocate": null, "pronunciation": "làng fèi", "ipa": "laŋ˥˩ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "别浪费水，用完请关水龙头。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了很多衣服，但是从来不穿，太浪费钱了。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃不完的饭不要倒掉，不然就浪费了。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想浪费时间在手机游戏上。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开着灯睡觉，浪费了很多电。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么好的菜扔掉了，太浪费了。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了省钱，妈妈从不浪费一点食物。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他浪费过很多机会，现在很后悔。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间没人，空调开着，真浪费电。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能浪费粮食，因为很多人吃不饱。", "target_word": "浪费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "浪费了", "label": "体标"}, {"form": "浪费过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把钱、时间、东西用得不该用或太多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪费", "is_correct": true, "explanation": "“浪费”表示用了不该用的东西或用得太多，与后文“用完请关水龙头”的节水意思相合。"}, {"text": "使用", "is_correct": false, "explanation": "语义：“别使用水”是禁止用水，与后文“用完请关水龙头”的意思矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多接生活、待遇、快乐，不说“享受水”。"}, {"text": "停止", "is_correct": false, "explanation": "搭配：“停止”多接工作、活动、计划，不说“停止水”，停水要说“停水”。"}], "explanations": {"浪费": "“浪费”表示用了不该用的东西或用得太多，与后文“用完请关水龙头”的节水意思相合。", "使用": "语义：“别使用水”是禁止用水，与后文“用完请关水龙头”的意思矛盾。", "享受": "搭配：“享受”多接生活、待遇、快乐，不说“享受水”。", "停止": "搭配：“停止”多接工作、活动、计划，不说“停止水”，停水要说“停水”。"}, "sentence_index": 0, "correct_answer": "浪费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要浪费每一分钟。", "explanation": "这里应该用〈珍惜〉。浪费指白白用掉，与“珍惜”意思相反，要说珍惜每一分钟。"}, {"text": "这场大雨让农民浪费了很多庄稼。", "explanation": "这里应该用〈损失〉。浪费指用得不该用或太多，庄稼因灾害而失去，应说损失。"}, {"text": "他很节约，每一分钱都浪费在必要的地方。", "explanation": "这里应该用〈用〉。浪费指用了不该用的东西，与“很节约”矛盾，应说用在必要的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪费", "is_correct": true, "explanation": "“浪费”表示不该用而用掉，与“为了省钱”的节俭动机相符。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：“从不珍惜”表示不重视，与“为了省钱”的动机相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”接场所或展览，不说“参观一点食物”。"}, {"text": "发明", "is_correct": false, "explanation": "搭配：“发明”接新事物或新方法，不能用“一点”来计量食物。"}], "explanations": {"浪费": "“浪费”表示不该用而用掉，与“为了省钱”的节俭动机相符。", "珍惜": "语义：“从不珍惜”表示不重视，与“为了省钱”的动机相矛盾。", "参观": "搭配：“参观”接场所或展览，不说“参观一点食物”。", "发明": "搭配：“发明”接新事物或新方法，不能用“一点”来计量食物。"}, "sentence_index": 6, "correct_answer": "浪费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们应该充分浪费这些资源。", "explanation": "这里应该用〈利用〉。浪费含贬义，指白白用掉；“充分”搭配的是“利用”，与“浪费”搭配矛盾。"}, {"text": "他在车站浪费了一个钱包。", "explanation": "这里应该用〈丢失〉。钱包被遗失并非用掉，不属于浪费，应说丢失。"}, {"text": "请合理浪费水资源。", "explanation": "这里应该用〈使用〉。“合理”与“浪费”意思相反，用水应说使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天浪费了掉两个小时。", "corrected_sentence": "我昨天浪费掉了两个小时。", "error_description": "结果补语位置错误：“掉”应紧跟动词“浪费”作补语，应说“浪费掉了”，不能说“浪费了掉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天我们浪费着很多粮食。", "corrected_sentence": "昨天我们浪费了很多粮食。", "error_description": "动态助词用错：“昨天”指过去已经发生的一次性行为，完成时应用“了”，不能用“着”。应为“浪费了很多粮食”，不能说“浪费着很多粮食”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
