INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "好多人在一起玩或吃饭。", "primary_collocate": null, "pronunciation": "jù huì", "ipa": "tɕy˥˩ xuei˥˩", "syllable_count": 2, "sentences": [{"text": "周末我们有一个朋友聚会。", "target_word": "聚会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "明天晚上的聚会在我家。", "target_word": "聚会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你参加今天的同学聚会吗？", "target_word": "聚会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次聚会很热闹，大家都玩得很开心。", "target_word": "聚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都组织一次聚会。", "target_word": "聚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日聚会上，我们吃了很多蛋糕。", "target_word": "聚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天没去公司聚会，因为我太累了。", "target_word": "聚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聚会的时候，大家一边吃饭一边聊天。", "target_word": "聚会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的聚会几点开始？", "target_word": "聚会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老同学的聚会让我很高兴。", "target_word": "聚会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "同学聚会", "label": "复合"}, {"form": "生日聚会", "label": "复合"}, {"form": "聚會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多人聚在一起玩或吃饭的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22352, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会议", "is_correct": false, "explanation": "语义：“会议”指为讨论事务而召开的正式集会，与“朋友”和“周末”的休闲语境不符。"}, {"text": "聚会", "is_correct": true, "explanation": "朋友聚在一起玩或吃饭的活动，正好填入“周末我们有一个朋友___”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是测验，安排朋友去考试与休闲语境不合。"}, {"text": "工作", "is_correct": false, "explanation": "搭配：“朋友工作”不能作为可以“有”的活动，与“周末”的休闲安排也不协调。"}], "explanations": {"会议": "语义：“会议”指为讨论事务而召开的正式集会，与“朋友”和“周末”的休闲语境不符。", "聚会": "朋友聚在一起玩或吃饭的活动，正好填入“周末我们有一个朋友___”。", "考试": "语义：“考试”是测验，安排朋友去考试与休闲语境不合。", "工作": "搭配：“朋友工作”不能作为可以“有”的活动，与“周末”的休闲安排也不协调。"}, "sentence_index": 0, "correct_answer": "聚会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在广场上举行聚会，要求增加工资。", "explanation": "这里应该用〈集会〉。聚会指朋友或同学间轻松的社交活动，有组织、带诉求的公开集会要用集会。"}, {"text": "球队的队员们在操场上聚会，练习传球。", "explanation": "这里应该用〈训练〉。聚会指朋友或同学间轻松的社交活动，有计划的体育训练要用训练。"}, {"text": "两国领导人昨天在首都聚会，讨论贸易问题。", "explanation": "这里应该用〈会谈〉。聚会指朋友或同学间轻松的社交活动，正式的外交或商务磋商要用会谈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22352, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "聚会", "is_correct": true, "explanation": "公司里大家聚在一起的社交活动，正好填入“我昨天没去公司___”。"}, {"text": "手术", "is_correct": false, "explanation": "语义：“手术”是医疗行为，与“没去公司”后面的活动安排不符。"}, {"text": "生日", "is_correct": false, "explanation": "搭配：“生日”指个人的生日，不能说“没去公司生日”。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“去地铁”不指参加活动，“公司地铁”也不成立。"}], "explanations": {"聚会": "公司里大家聚在一起的社交活动，正好填入“我昨天没去公司___”。", "手术": "语义：“手术”是医疗行为，与“没去公司”后面的活动安排不符。", "生日": "搭配：“生日”指个人的生日，不能说“没去公司生日”。", "地铁": "语义：“去地铁”不指参加活动，“公司地铁”也不成立。"}, "sentence_index": 6, "correct_answer": "聚会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位教授今天在大礼堂聚会，讲人工智能的发展。", "explanation": "这里应该用〈讲座〉。聚会指朋友间轻松的社交活动，学术报告、讲课要用讲座。"}, {"text": "很多游客在广场上聚会，等待表演开始。", "explanation": "这里应该用〈聚集〉。聚会指朋友间的社交活动，陌生人在广场等待表演应说聚集。"}, {"text": "公司每周都会召开一次聚会，讨论工作进度。", "explanation": "这里应该用〈会议〉。聚会是朋友间的社交活动，讨论工作进度应说会议，且“召开”多用于会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们上周末办了一只聚会。", "corrected_sentence": "我们上周末办了一次聚会。", "error_description": "量词错误：“聚会”应用“次”或“场”计量，“只”用于动物等，应改为“办了一次聚会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前参加着很多次聚会。", "corrected_sentence": "我以前参加过很多次聚会。", "error_description": "体标错误：表示以前有过的经历应用“过”，“着”表示动作进行或状态持续，应说“参加过很多次聚会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
