INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "提前想好的做法。", "primary_collocate": null, "pronunciation": "jì huà", "ipa": "tɕi˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "我们的旅行计划已经定好了。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个很大的计划。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个学期的学习计划是什么？", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司制定了明年的新计划。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，周末的计划改了。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把计划写在本子上。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的计划是先工作两年再读书。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划很好，但是需要很多钱。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对暑假有什么计划？", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按照计划完成了所有工作。", "target_word": "计划", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "计划书", "label": "复合"}], "register": "中性", "sense_fingerprint": "事先想好的安排和步骤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22360, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "计划", "is_correct": true, "explanation": "计划：事先想好的安排和步骤，是这里的目标词。"}, {"text": "字画", "is_correct": false, "explanation": "zì 与 jì 声母不同，字画指书法和绘画作品。"}, {"text": "气话", "is_correct": false, "explanation": "qì 与 jì 声母不同，意思是生气时说的话。"}, {"text": "戏话", "is_correct": false, "explanation": "xì 与 jì 声母不同，意思是开玩笑的话。"}], "explanations": {"计划": "计划：事先想好的安排和步骤，是这里的目标词。", "字画": "zì 与 jì 声母不同，字画指书法和绘画作品。", "气话": "qì 与 jì 声母不同，意思是生气时说的话。", "戏话": "xì 与 jì 声母不同，意思是开玩笑的话。"}, "sentence_index": null, "correct_answer": "计划"}, "level_3": {"options": [{"text": "计划", "is_correct": true, "explanation": "“定好”的可以是计划，旅行计划能够定好，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能提前“定好”，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是情绪，不是可以提前“定好”的安排。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学习任务，与旅行无关，不能说“旅行作业定好了”。"}], "explanations": {"计划": "“定好”的可以是计划，旅行计划能够定好，符合句意。", "天气": "语义：天气是自然现象，不能提前“定好”，句意不通。", "心情": "语义：心情是情绪，不是可以提前“定好”的安排。", "作业": "语义：作业是学习任务，与旅行无关，不能说“旅行作业定好了”。"}, "sentence_index": 0, "correct_answer": "计划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤的计划很高，小心烫。", "explanation": "这里应该用〈温度〉。计划指事先安排要做的事，不用来说汤的冷热，应说“温度很高”。"}, {"text": "我的计划比他高三厘米。", "explanation": "这里应该用〈身高〉。计划指事先安排要做的事，不能用来比较高矮，应说“身高”。"}, {"text": "他的计划很大，一个人就能搬起这个箱子。", "explanation": "这里应该用〈力气〉。计划指事先安排要做的事，不指人的体力，应说“力气很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "计划", "is_correct": true, "explanation": "“我的计划是……”表示打算要做的事，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是打算或安排，不能说“我的颜色是先工作两年再读书”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指性格和情绪，不是做事的安排，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“是”后面要接表示打算的名词，体重不能用来表示打算。"}], "explanations": {"计划": "“我的计划是……”表示打算要做的事，符合句意。", "颜色": "语义：颜色不是打算或安排，不能说“我的颜色是先工作两年再读书”。", "脾气": "语义：脾气指性格和情绪，不是做事的安排，句意不通。", "体重": "搭配：“是”后面要接表示打算的名词，体重不能用来表示打算。"}, "sentence_index": 6, "correct_answer": "计划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他计划这件事是小偷干的，我不相信。", "explanation": "这里应该用〈推测〉。计划指事先安排要做的事，不用来对已经发生的事做判断，应说“推测”。"}, {"text": "我计划明天会下雨。", "explanation": "这里应该用〈估计〉。计划是安排行动，不能用来对天气做推测。"}, {"text": "根据数据，我们计划出了结果。", "explanation": "这里应该用〈推算〉。推算指根据已知条件推出结果，计划指事先安排，不能说“计划出结果”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想出了一只好计划。", "corrected_sentence": "他想出了一个好计划。", "error_description": "错误形式：“一只好计划”；正确形式：“一个好计划”。“只”用于动物，计划应该用“个”来计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家对这个计划们都很满意。", "corrected_sentence": "大家对这个计划都很满意。", "error_description": "错误形式：“计划们”；正确形式：“计划”。“们”只加在指人的名词后面，计划不是人，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
