INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22362, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同地方的人，想法和做法不一样。", "primary_collocate": null, "pronunciation": "wén huà chā yì", "ipa": "wən˧˥ xwa˥˩ ʈʂʰa˥ i˥˩", "syllable_count": 4, "sentences": [{"text": "中国和日本有很多文化差异。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出国以后，我发现了文化差异。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化差异会影响人们的想法。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们因为文化差异常常误会对方。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语也要了解文化差异。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "员工来自不同国家，文化差异很大。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要尊重彼此的文化差异。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饮食习惯的不同是一种文化差异。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给我讲了中西方的文化差异。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化差异让旅行变得很有意思。", "target_word": "文化差异", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种文化差异", "label": "量词"}], "register": "中性", "sense_fingerprint": "不同地方的人想法做法不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '245aa18a-045a-46cc-b4fa-b7de9581fe19') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文化差异", "is_correct": true, "explanation": "正确：「中国和日本有很多文化差异」中，「文化差异」指两国人想法和做法的不同。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳只有一个，不能用「很多」修饰。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮只有一个，不能用「很多」修饰。"}, {"text": "大陆", "is_correct": false, "explanation": "搭配：「很多」一般不修饰「大陆」，中国和日本之间不说「很多大陆」。"}], "explanations": {"文化差异": "正确：「中国和日本有很多文化差异」中，「文化差异」指两国人想法和做法的不同。", "太阳": "语义：太阳只有一个，不能用「很多」修饰。", "月亮": "语义：月亮只有一个，不能用「很多」修饰。", "大陆": "搭配：「很多」一般不修饰「大陆」，中国和日本之间不说「很多大陆」。"}, "sentence_index": 0, "correct_answer": "文化差异"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕的文化差异很甜。", "explanation": "语义：「文化差异」指不同地方的人想法和做法不同，不能用来形容蛋糕的味道。"}, {"text": "她的文化差异很开朗。", "explanation": "这里应该用〈性格〉。「文化差异」指不同地方的人想法和做法不同，不能用来描述人的性格。"}, {"text": "我们在美国，文化差异是十二个小时。", "explanation": "这里应该用〈时差〉。「文化差异」指想法和做法的不同，不指时间上的差别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文化差异", "is_correct": true, "explanation": "正确：「我们要尊重彼此的文化差异」中，「文化差异」是可以被尊重的事物。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被尊重，「尊重彼此的天气」说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是可以被尊重的东西。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：「尊重」的对象是人或人的想法、习惯，「石头」与之不搭配。"}], "explanations": {"文化差异": "正确：「我们要尊重彼此的文化差异」中，「文化差异」是可以被尊重的事物。", "天气": "语义：天气不能被尊重，「尊重彼此的天气」说不通。", "冰箱": "语义：冰箱不是可以被尊重的东西。", "石头": "搭配：「尊重」的对象是人或人的想法、习惯，「石头」与之不搭配。"}, "sentence_index": 6, "correct_answer": "文化差异"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一个文化差异，很有名。", "explanation": "语义：「文化差异」是抽象概念，不能指人。"}, {"text": "我们周末去文化差异旅游。", "explanation": "语义：「文化差异」不是地点，不能说「去」。"}, {"text": "这杯咖啡的文化差异很浓。", "explanation": "这里应该用〈香味〉。「文化差异」指不同地方的人想法和做法不同，不能用来形容咖啡的香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国之间有很多明显地文化差异。", "corrected_sentence": "两国之间有很多明显的文化差异。", "error_description": "的/地误用：错误形式为「地」，正确形式为「的」，「明显」修饰名词「文化差异」要用「的」，「地」用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书讲的是中西方的一只文化差异。", "corrected_sentence": "这本书讲的是中西方的文化差异。", "error_description": "量词错误：「只」用于动物，不能修饰抽象的「文化差异」。应改用「种」，即「一种文化差异」，或去掉量词直接说「文化差异」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2e68fea7-3f48-4414-8e82-b156083ca382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
