INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示“不管什么时候”的意思。", "primary_collocate": null, "pronunciation": "suí shí", "ipa": "swei˧˥ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "有事你可以随时找我。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们随时可以出发。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店随时都有人。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你累了就随时告诉我。", "target_word": "随时", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说，有问题可以随时打电话。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气不好，比赛随时可能取消。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，我们随时可以问她问题。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他带着手机，随时能收到消息。", "target_word": "随时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店晚上也开门，你随时可以来买。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水在杯子里，你渴了随时可以喝。", "target_word": "随时", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "随时随地", "label": "固定组合"}, {"form": "隨時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "不管什么时候都可以或都有可能（副词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cba03f51-3fa7-4f07-875e-36a08896edd3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "随时", "is_correct": true, "explanation": "正确。“随时”表示什么时候都可以找我，与“有事”相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”多与否定词连用，不能说“可以从来找我”。"}, {"text": "按时", "is_correct": false, "explanation": "语义：“按时”指在约定的时间，不表示任何时候都可以找我。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“有事你可以……找我”的随时可找不符。"}], "explanations": {"随时": "正确。“随时”表示什么时候都可以找我，与“有事”相符。", "从来": "搭配：“从来”多与否定词连用，不能说“可以从来找我”。", "按时": "语义：“按时”指在约定的时间，不表示任何时候都可以找我。", "偶尔": "语义：“偶尔”表示不经常，与“有事你可以……找我”的随时可找不符。"}, "sentence_index": 0, "correct_answer": "随时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我随时告诉你了。", "explanation": "这里应该用〈已经〉。随时表示任何时候都可以，不能用于已经完成的动作。"}, {"text": "他被问住了，随时无法回答。", "explanation": "这里应该用〈当场〉。随时表示任何时候都可以，不表示当场立刻做出反应。"}, {"text": "他每天七点随时起床。", "explanation": "这里应该用〈按时〉。随时表示任何时候，不能与“七点”这样固定的钟点同时出现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "随时", "is_correct": true, "explanation": "正确。“随时”表示任何时候都可以问，与“老师说”的允许相符。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然、没有好处，与老师允许提问的语境不符。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示不得已而为之，与老师允许提问的语境相矛盾。"}, {"text": "早已", "is_correct": false, "explanation": "搭配：“早已”多与已经完成的动作连用，不与“可以问”搭配。"}], "explanations": {"随时": "正确。“随时”表示任何时候都可以问，与“老师说”的允许相符。", "白白": "语义：“白白”表示徒然、没有好处，与老师允许提问的语境不符。", "只好": "语义：“只好”表示不得已而为之，与老师允许提问的语境相矛盾。", "早已": "搭配：“早已”多与已经完成的动作连用，不与“可以问”搭配。"}, "sentence_index": 6, "correct_answer": "随时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他随时工作了十个小时。", "explanation": "这里应该用〈连续〉。随时表示任何时候都可以，不表示持续不断地做某件事。"}, {"text": "他随时考了一百分。", "explanation": "这里应该用〈居然〉。随时表示任何时候都可以，不表示出乎意料地取得某种结果。"}, {"text": "我随时去过北京。", "explanation": "这里应该用〈曾经〉。随时表示任何时候都可能，不能用来表示过去有过的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们随时能都出门。", "corrected_sentence": "我们随时都能出门。", "error_description": "错误形式：“随时能都出门”，副词“都”没有紧跟“随时”。正确形式：“随时都能出门”，“都”应紧跟“随时”，放在助动词“能”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有问题你可以随时着打电话。", "corrected_sentence": "有问题你可以随时打电话。", "error_description": "错误形式：“随时着打电话”。“随时”是副词，后面不能加“着”。正确形式：“随时打电话”，副词“随时”直接放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '605e84e4-620d-4b13-9a06-fab69e3270a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
