INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22366, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示时间或顺序在前的意思。", "primary_collocate": null, "pronunciation": "xiān", "ipa": "ɕjɛn˥", "syllable_count": 1, "sentences": [{"text": "你先吃饭，我再去买菜。", "target_word": "先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先去商店，然后回家。", "target_word": "先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先洗手，再吃东西。", "target_word": "先", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他先到了，我后到。", "target_word": "先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你先说，我听着。", "target_word": "先", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我先想一想。", "target_word": "先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先做作业，再玩手机。", "target_word": "先", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你们先走吧，我马上来。", "target_word": "先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师先写名字，然后写日期。", "target_word": "先", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，我们先回家吧。", "target_word": "先", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "先后", "label": "复合"}, {"form": "事先", "label": "复合"}], "register": "中性", "sense_fingerprint": "副词，表示动作在时间或顺序上排在前面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "先", "is_correct": true, "explanation": "正确：“先”读作 xiān，表示动作在时间或顺序上排在前面。"}, {"text": "香", "is_correct": false, "explanation": "xiāng（第一声）与 xiān（第一声）韵母不同（-ang 与 -an），意思是香。"}, {"text": "线", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是线。"}, {"text": "闲", "is_correct": false, "explanation": "xián（第二声）与 xiān（第一声）声调不同，意思是空闲。"}, {"text": "心", "is_correct": false, "explanation": "xīn（第一声）与 xiān 韵母不同（-in 与 -ian），意思是心。"}, {"text": "星", "is_correct": false, "explanation": "xīng（第一声）与 xiān 韵母不同（-ing 与 -ian），意思是星星。"}], "explanations": {"先": "正确：“先”读作 xiān，表示动作在时间或顺序上排在前面。", "香": "xiāng（第一声）与 xiān（第一声）韵母不同（-ang 与 -an），意思是香。", "线": "xiàn（第四声）与 xiān（第一声）声调不同，意思是线。", "闲": "xián（第二声）与 xiān（第一声）声调不同，意思是空闲。", "心": "xīn（第一声）与 xiān 韵母不同（-in 与 -ian），意思是心。", "星": "xīng（第一声）与 xiān 韵母不同（-ing 与 -ian），意思是星星。"}, "sentence_index": null, "correct_answer": "先"}, "level_3": {"options": [{"text": "先", "is_correct": true, "explanation": "正确：“先”表示动作在前，和后面的“再”组成先后顺序。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示两件事一起做，与后面“再”所表示的先后顺序矛盾。"}, {"text": "最后", "is_correct": false, "explanation": "语义：“最后”表示放在末尾，后面不能再接“再去买菜”。"}, {"text": "又", "is_correct": false, "explanation": "搭配：“又”表示再次发生，要和已经发生过的动作搭配，这里是第一次吃饭，不能用“又”。"}], "explanations": {"先": "正确：“先”表示动作在前，和后面的“再”组成先后顺序。", "同时": "语义：“同时”表示两件事一起做，与后面“再”所表示的先后顺序矛盾。", "最后": "语义：“最后”表示放在末尾，后面不能再接“再去买菜”。", "又": "搭配：“又”表示再次发生，要和已经发生过的动作搭配，这里是第一次吃饭，不能用“又”。"}, "sentence_index": 0, "correct_answer": "先"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天先见。", "explanation": "这里应该用〈再〉。“先”表示顺序在前，约定以后见面要说“明天再见”，应用〈再〉。"}, {"text": "我们先同时出发。", "explanation": "这里应该用〈一起〉。“先”表示顺序在前，与“同时”（同一时间）互相矛盾；表示一起出发要用〈一起〉。"}, {"text": "我先最后离开了房间。", "explanation": "这里应该删去〈先〉，说“我最后离开了房间”。“先”表示顺序在前，与“最后”（排在末尾）矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22366, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "先", "is_correct": true, "explanation": "正确：“先”读作 xiān，表示动作在时间或顺序上排在前面。"}, {"text": "相", "is_correct": false, "explanation": "xiāng（第一声）与 xiān（第一声）韵母不同（-ang 与 -an），意思是互相。"}, {"text": "县", "is_correct": false, "explanation": "xiàn（第四声）与 xiān（第一声）声调不同，意思是县。"}, {"text": "贤", "is_correct": false, "explanation": "xián（第二声）与 xiān（第一声）声调不同，意思是贤良。"}, {"text": "新", "is_correct": false, "explanation": "xīn（第一声）与 xiān 韵母不同（-in 与 -ian），意思是新。"}, {"text": "兴", "is_correct": false, "explanation": "xīng（第一声）与 xiān 韵母不同（-ing 与 -ian），意思是兴起。"}, {"text": "千", "is_correct": false, "explanation": "qiān（第一声）与 xiān 声母不同（q 与 x），意思是一千。"}], "explanations": {"先": "正确：“先”读作 xiān，表示动作在时间或顺序上排在前面。", "相": "xiāng（第一声）与 xiān（第一声）韵母不同（-ang 与 -an），意思是互相。", "县": "xiàn（第四声）与 xiān（第一声）声调不同，意思是县。", "贤": "xián（第二声）与 xiān（第一声）声调不同，意思是贤良。", "新": "xīn（第一声）与 xiān 韵母不同（-in 与 -ian），意思是新。", "兴": "xīng（第一声）与 xiān 韵母不同（-ing 与 -ian），意思是兴起。", "千": "qiān（第一声）与 xiān 声母不同（q 与 x），意思是一千。"}, "sentence_index": null, "correct_answer": "先"}, "level_3": {"options": [{"text": "先", "is_correct": true, "explanation": "正确：“先”表示动作在前，和后面的“再”组成先后顺序。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”通常与否定词搭配，这里说的是肯定的做法，不能用“根本”。"}, {"text": "竟", "is_correct": false, "explanation": "语域：“竟”是书面语，常表示出乎意料，这句话只是说明先后顺序，口语里不这么用。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示两件事一起做，与后面“再”所表示的先后顺序矛盾。"}], "explanations": {"先": "正确：“先”表示动作在前，和后面的“再”组成先后顺序。", "根本": "搭配：“根本”通常与否定词搭配，这里说的是肯定的做法，不能用“根本”。", "竟": "语域：“竟”是书面语，常表示出乎意料，这句话只是说明先后顺序，口语里不这么用。", "同时": "语义：“同时”表示两件事一起做，与后面“再”所表示的先后顺序矛盾。"}, "sentence_index": 6, "correct_answer": "先"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只有学好汉语先能找到工作。", "explanation": "这里应该用〈才〉。“只有……才……”是固定的条件句式，“先”不能用在这里，应说“只有学好汉语才能找到工作”。"}, {"text": "今天太晚了，你明天先来吧。", "explanation": "这里应该用〈再〉。把事情推到以后做要用“再”，应说“明天再来吧”。"}, {"text": "这次没考好，下次先努力吧。", "explanation": "这里应该用〈再〉。说以后重新做某事要用“再”，应说“下次再努力吧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
