INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西不一样的地方。", "primary_collocate": null, "pronunciation": "chā bié", "ipa": "ʈʂʰa˥ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这两个苹果有什么差别？", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和弟弟的差别很明显。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机和电脑的差别是大小。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两双鞋的差别只是颜色。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到这两张画的差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书的差别不太大。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你看一看，左右两张表格有什么差别？", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种水果的差别在味道上。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车和旧车的差别很大。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服和那件衣服几乎没有差别。", "target_word": "差别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "差別", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个具体东西相比时看得出的不同之处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd985621-6079-4c4e-9728-3b0bc36e20cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差别", "is_correct": true, "explanation": "正确。句中问的是两个苹果之间看得出的不同之处，“差别”与句意相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：苹果没有年龄上的比较问题，“这两个苹果有什么年龄”不符合常识。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的身体高度，不能用来形容苹果。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：苹果没有脾气，“这两个苹果有什么脾气”与句意无关。"}], "explanations": {"差别": "正确。句中问的是两个苹果之间看得出的不同之处，“差别”与句意相符。", "年龄": "语义：苹果没有年龄上的比较问题，“这两个苹果有什么年龄”不符合常识。", "身高": "体貌：身高指人或动物的身体高度，不能用来形容苹果。", "脾气": "语义：苹果没有脾气，“这两个苹果有什么脾气”与句意无关。"}, "sentence_index": 0, "correct_answer": "差别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个差别长两米，足够用了。", "explanation": "这里应该用〈绳子〉。差别是不同之处，不是有长度的东西，说“长两米”只能用于绳子这类实物。"}, {"text": "他的差别很好，能看清远处的字。", "explanation": "这里应该用〈视力〉。“好”用于视力、成绩等，差别是不同之处，不能说“差别很好”。"}, {"text": "我把那个差别放进了书包。", "explanation": "这里应该用〈东西〉。差别是抽象的不同之处，不是实物，装进书包的要说“东西”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差别", "is_correct": true, "explanation": "正确。句中请人看两张表格有什么不同之处，“差别”与句意相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：表格没有心情，“两张表格有什么心情”不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人或动物的体型，不能用来说表格。"}, {"text": "性格", "is_correct": false, "explanation": "语义：表格没有性格，与句意无关。"}], "explanations": {"差别": "正确。句中请人看两张表格有什么不同之处，“差别”与句意相符。", "心情": "语义：表格没有心情，“两张表格有什么心情”不通。", "身材": "体貌：身材指人或动物的体型，不能用来说表格。", "性格": "语义：表格没有性格，与句意无关。"}, "sentence_index": 6, "correct_answer": "差别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个差别的温度有三十度。", "explanation": "这里应该用〈水温〉。差别是不同之处，没有温度，不能说“有三十度”。"}, {"text": "我买了一个差别，很甜。", "explanation": "这里应该用〈西瓜〉。差别是抽象的不同之处，不能买，更不能说甜。"}, {"text": "这个差别很好吃，我还想再吃一个。", "explanation": "这里应该用〈苹果〉。差别是抽象的不同之处，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个苹果有一场差别。", "corrected_sentence": "这两个苹果有一点差别。", "error_description": "量词错误：“差别”要用量词“点”或“种”，“场”用于比赛、雨、事件等，不能修饰“差别”。正确说法是“一点差别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两个杯子的差别大很。", "corrected_sentence": "这两个杯子的差别很大。", "error_description": "状语位置错误：副词“很”要放在形容词“大”的前面，不能说“大很”。正确说法是“差别很大”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
