INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22372, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用来说出一个东西或人的名字。", "primary_collocate": null, "pronunciation": "jiào zuò", "ipa": "tɕjɑʊ˥˩ tsuɔ˥˩", "syllable_count": 2, "sentences": [{"text": "这种黄色的水果叫做香蕉。", "target_word": "叫做", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中国的首都叫做北京。", "target_word": "叫做", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把这种花叫做玫瑰。", "target_word": "叫做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会飞的交通工具叫做飞机。", "target_word": "叫做", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你知道这种鱼叫做什么吗？", "target_word": "叫做", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们住的这个城市叫做上海。", "target_word": "叫做", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用来写字的东西叫做笔。", "target_word": "叫做", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈的妈妈叫做外婆。", "target_word": "叫做", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这样的天气叫做晴天。", "target_word": "叫做", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，这个字叫做“山”。", "target_word": "叫做", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "叫作", "label": "异形"}], "register": "中性", "sense_fingerprint": "称呼、命名：把某物或某人称为某名", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b61e398c-20aa-46ca-9d37-d0eb222c07e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22372, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叫做", "is_correct": true, "explanation": "正确：“叫做”读作 jiào zuò，用来说出事物或人的名字。"}, {"text": "叫错", "is_correct": false, "explanation": "cuò（第四声）与 zuò（第四声）声母不同（c 与 z），意思是叫错。"}, {"text": "要做", "is_correct": false, "explanation": "yào（第四声）与 jiào 声母不同（y 与 j），意思是想要做。"}, {"text": "就做", "is_correct": false, "explanation": "jiù（第四声）与 jiào 韵母不同（-iu 与 -ao），意思是马上做。"}], "explanations": {"叫做": "正确：“叫做”读作 jiào zuò，用来说出事物或人的名字。", "叫错": "cuò（第四声）与 zuò（第四声）声母不同（c 与 z），意思是叫错。", "要做": "yào（第四声）与 jiào 声母不同（y 与 j），意思是想要做。", "就做": "jiù（第四声）与 jiào 韵母不同（-iu 与 -ao），意思是马上做。"}, "sentence_index": null, "correct_answer": "叫做"}, "level_3": {"options": [{"text": "叫做", "is_correct": true, "explanation": "正确：“叫做”用来说出事物的名字，这里说这种水果的名字是香蕉。"}, {"text": "吃", "is_correct": false, "explanation": "语义：水果不会“吃”香蕉，句子说的是这种水果的名字。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：水果不能“喜欢”，这里要说明的是它的名字。"}, {"text": "卖", "is_correct": false, "explanation": "配价：“卖”需要人作主语，水果不能“卖”香蕉。"}], "explanations": {"叫做": "正确：“叫做”用来说出事物的名字，这里说这种水果的名字是香蕉。", "吃": "语义：水果不会“吃”香蕉，句子说的是这种水果的名字。", "喜欢": "语义：水果不能“喜欢”，这里要说明的是它的名字。", "卖": "配价：“卖”需要人作主语，水果不能“卖”香蕉。"}, "sentence_index": 0, "correct_answer": "叫做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈叫做孩子吃饭。", "explanation": "这里应该用〈叫〉。“叫做”表示说出事物的名称，不能表示让别人做事；让人做事要用〈叫〉。"}, {"text": "他叫做我的哥哥。", "explanation": "这里应该用〈是〉。“叫做”表示把人或事物称为某名，说身份关系要用〈是〉。"}, {"text": "我叫做一份炒饭。", "explanation": "这里应该用〈点〉。“叫做”表示命名，不能用来说点菜；点一份炒饭要用〈点〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叫做", "is_correct": true, "explanation": "正确：“叫做”用来说出事物的名字，这里说这种东西的名字是笔。"}, {"text": "变成", "is_correct": false, "explanation": "语义：“变成”表示变化，这句话说的是名称，不是变化。"}, {"text": "吃", "is_correct": false, "explanation": "语义：东西不会“吃”笔，这句话说的是笔的名称。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”要求宾语是字或文章，不能以“笔”作宾语。"}], "explanations": {"叫做": "正确：“叫做”用来说出事物的名字，这里说这种东西的名字是笔。", "变成": "语义：“变成”表示变化，这句话说的是名称，不是变化。", "吃": "语义：东西不会“吃”笔，这句话说的是笔的名称。", "写": "配价：“写”要求宾语是字或文章，不能以“笔”作宾语。"}, "sentence_index": 6, "correct_answer": "叫做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在远处叫做我的名字。", "explanation": "这里应该用〈喊〉。“叫做”表示命名，不能表示大声呼叫；远处叫人要用〈喊〉。"}, {"text": "水叫做了冰。", "explanation": "这里应该用〈变成〉。“叫做”表示命名，不能表示变化；表示变化要用〈变成〉。"}, {"text": "我叫做了一辆出租车。", "explanation": "这里应该用〈打〉。“叫做”表示命名，不能用来说叫车；叫一辆出租车要用〈打〉（打车）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只小鸟叫做是麻雀。", "corrected_sentence": "这只小鸟叫做麻雀。", "error_description": "“叫做”后面不能再加“是”，两个谓语重复，应说“这只小鸟叫做麻雀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种圆圆的东西叫做了足球。", "corrected_sentence": "这种圆圆的东西叫做足球。", "error_description": "“叫做”是表示命名的动词，后面不能加“了”，应说“叫做足球”，不能说“叫做了足球”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f7e96fc-422d-4c56-b2ef-e495fb7e46fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
