INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有些事情不明白或者有困难。", "primary_collocate": null, "pronunciation": "wèn tí", "ipa": "wən˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "我的电脑出了问题，打不开了。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太难，我想不出办法。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你有问题，可以问老师。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的身体没有问题，请放心。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的学习问题让妈妈很担心。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不是问题，关键是时间。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起想办法，一定能解决问题。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车有问题，今天不能开。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，我对这个句子有一个问题。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太热会烫手，这是小问题，不用怕。", "target_word": "问题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个问题", "label": "量词"}, {"form": "一些问题", "label": "量词"}, {"form": "问题少年", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：需要解决的困难或不明白的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "问题", "is_correct": true, "explanation": "问题：指电脑出的毛病或故障，与“打不开了”的语境相符。"}, {"text": "答案", "is_correct": false, "explanation": "语义：“答案”是问题的解答，不是电脑的故障，句意不通。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”指可笑的事，电脑打不开不是笑话。"}, {"text": "办法", "is_correct": false, "explanation": "语义：“办法”是解决问题的方法，电脑打不开的毛病不是办法，句意不通。"}], "explanations": {"问题": "问题：指电脑出的毛病或故障，与“打不开了”的语境相符。", "答案": "语义：“答案”是问题的解答，不是电脑的故障，句意不通。", "笑话": "语义：“笑话”指可笑的事，电脑打不开不是笑话。", "办法": "语义：“办法”是解决问题的方法，电脑打不开的毛病不是办法，句意不通。"}, "sentence_index": 0, "correct_answer": "问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是给我添问题。", "explanation": "这里应该用〈麻烦〉。“添”后接的是“麻烦”，不说“添问题”。"}, {"text": "我有一个问题想送给您。", "explanation": "这里应该用〈礼物〉。“问题”指有待解答的疑难，不能送给别人，送人的东西应说礼物。"}, {"text": "他的问题是三十岁。", "explanation": "这里应该用〈年龄〉。“问题”指疑难或毛病，不指岁数，说岁数要用年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "问题", "is_correct": true, "explanation": "问题：指需要解决的困难，与“一定能解决”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是需要解决的困难，“解决颜色”句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是需要解决的困难，不能说“解决天气”。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“解决”的对象是困难或问题，“解决眼镜”不通。"}], "explanations": {"问题": "问题：指需要解决的困难，与“一定能解决”相符。", "颜色": "语义：“颜色”不是需要解决的困难，“解决颜色”句意不通。", "天气": "语义：“天气”不是需要解决的困难，不能说“解决天气”。", "眼镜": "搭配：“解决”的对象是困难或问题，“解决眼镜”不通。"}, "sentence_index": 6, "correct_answer": "问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一个问题。", "explanation": "这里应该用〈饼干〉。“问题”指疑难，不能买，买的东西要说饼干。"}, {"text": "这个人的问题很好听。", "explanation": "这里应该用〈声音〉。“问题”指疑难，不能形容好听，形容声音才用好听。"}, {"text": "今天的问题很蓝。", "explanation": "这里应该用〈天空〉。“问题”没有颜色，形容蓝色的应是天空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们需要尽快解决了问题。", "corrected_sentence": "我们需要尽快解决问题。", "error_description": "“需要”表示尚未发生的需求，后面的动作还没有完成，“解决”后不加“了”。应说“我们需要尽快解决问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个很难问题。", "corrected_sentence": "这是一个很难的问题。", "error_description": "“很难”修饰“问题”，中间要用“的”连接，应说“很难的问题”，不能说“很难问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是程度很高，比如“很”。", "primary_collocate": null, "pronunciation": "fēi cháng", "ipa": "fei˥ ʈʂʰaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个菜非常好吃。", "target_word": "非常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天天气非常好。", "target_word": "非常", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我昨天非常累，所以早早就睡了。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的冬天非常冷，要多穿衣服。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书非常有意思，我看了三遍。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听到这个消息，我非常高兴。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话的声音非常小，后面的同学听不见。", "target_word": "非常", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的人非常多，我们等了一个小时。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑得非常快，一下子就赢了比赛。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你的帮助，我非常感谢。", "target_word": "非常", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "程度副词，表示程度极高，用在形容词或心理动词前", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6062633-d150-4b42-8c9e-91408b62d40d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正在", "is_correct": false, "explanation": "语法：「正在」表示动作进行，不能直接修饰形容词「好吃」。"}, {"text": "非常", "is_correct": true, "explanation": "正确：「非常」表示程度很高，修饰形容词「好吃」。"}, {"text": "了", "is_correct": false, "explanation": "语法：「了」是助词，不能放在「这个菜」和「好吃」之间。"}, {"text": "着", "is_correct": false, "explanation": "语法：「着」是助词，不能放在「这个菜」和「好吃」之间。"}], "explanations": {"正在": "语法：「正在」表示动作进行，不能直接修饰形容词「好吃」。", "非常": "正确：「非常」表示程度很高，修饰形容词「好吃」。", "了": "语法：「了」是助词，不能放在「这个菜」和「好吃」之间。", "着": "语法：「着」是助词，不能放在「这个菜」和「好吃」之间。"}, "sentence_index": 0, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常吃饭，一顿能吃三碗。", "explanation": "这里应该用〈很能〉。「非常」修饰形容词，表示程度，不能修饰「吃饭」这样的动作来表示吃得多；要说「很能吃」。"}, {"text": "他非常地忘了作业，老师很生气。", "explanation": "这里不这么用：「非常」表示程度，只修饰形容词和部分心理动词，不能修饰「忘」这样的动作；这里不是表示程度很高。"}, {"text": "他非常上学，每天都不迟到。", "explanation": "这里应该用〈每天〉。「非常」表示程度，不表示频率，「上学」这样的动作不能用「非常」修饰；要说「每天上学」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不", "is_correct": false, "explanation": "语义：「不小」与后面的「听不见」矛盾，声音不小，后排就听得见。"}, {"text": "非常", "is_correct": true, "explanation": "正确：「非常」表示程度很高，与「后面的同学听不见」的原因相符。"}, {"text": "的", "is_correct": false, "explanation": "语法：「的」是结构助词，「声音的小」不成立，不能放在「声音」和「小」之间表示程度。"}, {"text": "在", "is_correct": false, "explanation": "语法：「在」不能直接放在「声音」和「小」之间，「在小」不成立。"}], "explanations": {"不": "语义：「不小」与后面的「听不见」矛盾，声音不小，后排就听得见。", "非常": "正确：「非常」表示程度很高，与「后面的同学听不见」的原因相符。", "的": "语法：「的」是结构助词，「声音的小」不成立，不能放在「声音」和「小」之间表示程度。", "在": "语法：「在」不能直接放在「声音」和「小」之间，「在小」不成立。"}, "sentence_index": 6, "correct_answer": "非常"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他非常在学校里学习，成绩很好。", "explanation": "这里不这么用：「非常」是程度副词，不能修饰「在学校里学习」这样的动作和地点；表示地点要用「在……」，程度要用「非常」修饰形容词。"}, {"text": "今天的作业比昨天非常多，我写到很晚。", "explanation": "这里不这么用：比较句中不能用「非常」，它表示绝对的程度；比较时要用「更」，如「比昨天更多」。"}, {"text": "这把椅子非常木头。", "explanation": "「木头」表示材料，没有程度的差别，不能用「非常」修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路的风景非常美，我们非常走了很久。", "corrected_sentence": "这条路的风景非常美，我们走了很久。", "error_description": "错误：「我们非常走了很久」；正确：「我们走了很久」。「非常」是程度副词，只修饰形容词，不能放在「走」这样的动作动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的菜很非常便宜，学生都爱来。", "corrected_sentence": "这家店的菜非常便宜，学生都爱来。", "error_description": "错误：「很非常便宜」；正确：「非常便宜」。「很」和「非常」都表示程度，同一个形容词前面只用一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d7bb3b7-e085-46e5-b1a5-a7408cc8f010') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22380, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
