INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22384, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22384, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在规定的时间做事情。", "primary_collocate": null, "pronunciation": "àn shí", "ipa": "an˥˩ ʂɻ̩˧˥", "syllable_count": 2, "sentences": [{"text": "他今天按时到了学校。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要按时回家，别太晚。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我按时起床，没有迟到。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们按时进了教室。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王每天按时上班。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家按时到会议室。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，药要按时吃。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们按时坐上了飞机。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有按时来，所以我们先开始了。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们按时做完了作业。", "target_word": "按时", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "按時", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，在规定的时间点做某件事，不迟到、不拖延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd985621-6079-4c4e-9728-3b0bc36e20cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反复", "is_correct": false, "explanation": "语义：“反复”说多次重来，与“到了学校”这样的一次性动作不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”修饰不定期重复的动作，不能用于“今天”这一次到校。"}, {"text": "按时", "is_correct": true, "explanation": "按时：依照规定的时间到校，与“今天”的说法搭配自然。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”说持续不断，与“到了学校”这个时间点相矛盾。"}], "explanations": {"反复": "语义：“反复”说多次重来，与“到了学校”这样的一次性动作不符。", "偶尔": "搭配：“偶尔”修饰不定期重复的动作，不能用于“今天”这一次到校。", "按时": "按时：依照规定的时间到校，与“今天”的说法搭配自然。", "一直": "语义：“一直”说持续不断，与“到了学校”这个时间点相矛盾。"}, "sentence_index": 0, "correct_answer": "按时"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场雨按时下了一整天。", "explanation": "这里应该用〈连续〉。按时指依照规定的时间做事，雨下多久是自然变化，没有规定的时间，不能用按时。"}, {"text": "他按时生病了，只好请了假。", "explanation": "这里应该用〈突然〉。按时指依照规定的时间做事，生病是突发的，没有时间表，不能用按时。"}, {"text": "我的英语水平按时提高了。", "explanation": "这里应该用〈逐步〉。按时指依照时间表做事，水平提高是渐进的过程，没有规定的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乱", "is_correct": false, "explanation": "语义：“乱”说没有章法地胡来，与医生的吩咐正好相反。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”说暗中进行，与医生要求依规定服药的语境不符。"}, {"text": "再三", "is_correct": false, "explanation": "搭配：“再三”多修饰劝告、请求，不修饰“吃药”这样的日常动作。"}, {"text": "按时", "is_correct": true, "explanation": "按时：依照规定的时间服药，符合医生的吩咐。"}], "explanations": {"乱": "语义：“乱”说没有章法地胡来，与医生的吩咐正好相反。", "偷偷": "语义：“偷偷”说暗中进行，与医生要求依规定服药的语境不符。", "再三": "搭配：“再三”多修饰劝告、请求，不修饰“吃药”这样的日常动作。", "按时": "按时：依照规定的时间服药，符合医生的吩咐。"}, "sentence_index": 6, "correct_answer": "按时"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们按时走散了，找了很久。", "explanation": "这里应该用〈意外〉。按时指依照规定的时间做事，走散是意外发生的，没有时间表，不能用按时。"}, {"text": "她按时想起了往事。", "explanation": "这里应该用〈忽然〉。按时指依照规定的时间做事，“想起往事”是不受控制的心理活动，不能依时间表发生。"}, {"text": "这个孩子按时哭得很伤心。", "explanation": "这里应该用〈忽然〉。按时指依照规定的时间做事，“哭得很伤心”是情绪反应，不能依时间表发生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议的按时结束了。", "corrected_sentence": "会议按时结束了。", "error_description": "错误：副词“按时”前不能加“的”，它只能直接作状语。正确说法是“会议按时结束了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他了按时吃饭，胃疼了。", "corrected_sentence": "他没按时吃饭，胃疼了。", "error_description": "错误：否定词“没”被换成了“了”。否定“按时吃饭”要用“没”，说“没按时吃饭”表示没有按时吃饭；“了”是完成标记，不能放在主语后、“按时”前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
