INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里有某种感觉。", "primary_collocate": null, "pronunciation": "gǎn dào", "ipa": "kan˨˩˦ tau˥˩", "syllable_count": 2, "sentences": [{"text": "听到这个消息，我感到很高兴。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次坐飞机，感到有点儿紧张。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走了一天路，我感到很累。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的工作感到满意。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说我进步了，我感到非常开心。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人在国外，他常常感到孤单。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子们笑，妈妈感到很幸福。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门就感到屋里很热。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试以前，很多人都会感到害怕。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个结果感到很吃惊。", "target_word": "感到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "感到了", "label": "体标（了）"}, {"form": "感到过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "动词，心里产生高兴、紧张、累等感觉，后面常接形容词或心理状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0c1a906-ea1f-4e51-bb2e-ae63d5c674b5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感到", "is_correct": true, "explanation": "“感到”后接形容词“很高兴”，表示心里产生的感受，句意通顺。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”指看到某物，不能表示心里的感受，与“很高兴”不搭。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与句中表示心情的“很高兴”无关。"}, {"text": "发生", "is_correct": false, "explanation": "配价：“发生”是不及物动词，不能直接接形容词“很高兴”表示感受。"}], "explanations": {"感到": "“感到”后接形容词“很高兴”，表示心里产生的感受，句意通顺。", "看见": "语义：“看见”指看到某物，不能表示心里的感受，与“很高兴”不搭。", "吃": "语义：“吃”指进食，与句中表示心情的“很高兴”无关。", "发生": "配价：“发生”是不及物动词，不能直接接形容词“很高兴”表示感受。"}, "sentence_index": 0, "correct_answer": "感到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我感到了你寄来的信。", "explanation": "这里应该用〈收到〉。“感到”表示心里的感觉，不能用来表示接收信件，应说“收到”。"}, {"text": "我每天感到学生的作业。", "explanation": "这里应该用〈批改〉。“感到”表示心里的感觉，不能用来表示批阅作业，应说“批改”。"}, {"text": "他感到了一个数学公式。", "explanation": "这里应该用〈背〉。“感到”表示心里的感受，不能接公式表示记忆，应说“背”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感到", "is_correct": true, "explanation": "“感到”后接形容词“很幸福”，表示心里的感受，句意通顺。"}, {"text": "听见", "is_correct": false, "explanation": "语义：“听见”表示听到声音，与“很幸福”这种心情不搭。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖”是交易行为，用来表示心情，句意不通。"}, {"text": "打开", "is_correct": false, "explanation": "配价：“打开”是及物动词，后面要接宾语，不能直接接“很幸福”。"}], "explanations": {"感到": "“感到”后接形容词“很幸福”，表示心里的感受，句意通顺。", "听见": "语义：“听见”表示听到声音，与“很幸福”这种心情不搭。", "卖": "语义：“卖”是交易行为，用来表示心情，句意不通。", "打开": "配价：“打开”是及物动词，后面要接宾语，不能直接接“很幸福”。"}, "sentence_index": 6, "correct_answer": "感到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我感到了一杯咖啡。", "explanation": "这里应该用〈喝〉。“感到”表示心里的感觉，不能接饮品表示饮用，应说“喝”。"}, {"text": "老师感到了每个学生的名字。", "explanation": "这里应该用〈记住〉。“感到”表示心里的感受，不能接名字表示记忆，应说“记住”。"}, {"text": "我感到了窗外的那片云。", "explanation": "这里应该用〈看〉。“感到”表示心里的感觉，不能接景物表示看见，应说“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "看到比赛结果，我感到得很失望。", "corrected_sentence": "看到比赛结果，我感到很失望。", "error_description": "多出“得”：“感到”后直接接形容词作谓语，不能加“得”；应说“我感到很失望”，不能说“我感到得很失望”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走进教室，我就感到得空气很闷。", "corrected_sentence": "走进教室，我就感到空气很闷。", "error_description": "多出“得”：“感到”后直接接宾语，不能加“得”；应说“感到空气很闷”，不能说“感到得空气很闷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f826db5-3f14-4a58-ac08-7e9afdfa78e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃力", "is_correct": true, "explanation": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。"}, {"text": "干净", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“脏”相对。"}, {"text": "明亮", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“昏暗”相对。"}, {"text": "仔细", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“马虎”相对。"}], "correct_answer": "吃力", "explanations": {"吃力": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。", "干净": "与“轻松”无反义关系，它与“脏”相对。", "明亮": "与“轻松”无反义关系，它与“昏暗”相对。", "仔细": "与“轻松”无反义关系，它与“马虎”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "吃力", "is_correct": true, "explanation": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。"}, {"text": "复杂", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“简单”相对。"}, {"text": "认真", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“敷衍”相对。"}, {"text": "安静", "is_correct": false, "explanation": "与“轻松”无反义关系，它与“吵闹”相对。"}], "correct_answer": "吃力", "explanations": {"吃力": "与“轻松”构成反义：吃力指做事费劲，与“不费力”相对。", "复杂": "与“轻松”无反义关系，它与“简单”相对。", "认真": "与“轻松”无反义关系，它与“敷衍”相对。", "安静": "与“轻松”无反义关系，它与“吵闹”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事情不费力，心里不紧张。", "primary_collocate": null, "pronunciation": "qīng sōng", "ipa": "tɕʰiŋ˥ sʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这道题很简单，他轻松地做完了。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她轻松地提起了那个大箱子。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，我们轻松赢了对手。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏很容易，小孩子也能轻松学会。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了这个新软件，我们可以轻松完成工作。", "target_word": "轻松", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这次考试很轻松，不用担心。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他跑得很快，轻松拿到了第一名。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她走上台，轻松地说了几句话。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题不难，你可以轻松回答。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天锻炼，所以爬山也很轻松。", "target_word": "轻松", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "轻轻松松", "label": "重叠"}, {"form": "轻松愉快", "label": "复合"}, {"form": "輕鬆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做事轻易、不费力气，态度从容不紧张", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a710815b-c492-4cee-80cf-d7c9671808e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "轻松", "is_correct": true, "explanation": "正确：“他轻松地做完了”表示做事不费力，符合“这道题很简单”的语境。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“巨大地做完”不成立，“巨大”不能修饰“做”。"}, {"text": "浑浊", "is_correct": false, "explanation": "语义：“浑浊”说水或空气不清，与做题的语境无关。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”说颜色或光线，与“做完了”不相干。"}], "explanations": {"轻松": "正确：“他轻松地做完了”表示做事不费力，符合“这道题很简单”的语境。", "巨大": "搭配：“巨大地做完”不成立，“巨大”不能修饰“做”。", "浑浊": "语义：“浑浊”说水或空气不清，与做题的语境无关。", "漆黑": "语义：“漆黑”说颜色或光线，与“做完了”不相干。"}, "sentence_index": 0, "correct_answer": "轻松"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞很轻松，放进包里也不占地方。", "explanation": "这里应该用〈轻巧〉。轻巧形容物体轻便小巧，“轻松”指做事不费力，不形容伞的重量。"}, {"text": "他做人很认真，从不轻松许诺。", "explanation": "这里应该用〈轻易〉。“轻易许诺”指随便答应，“轻松许诺”不成立。"}, {"text": "他只受了轻松的伤，休息几天就好了。", "explanation": "这里应该用〈轻微〉。轻微形容伤势轻，“轻松”不修饰“伤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "轻松", "is_correct": true, "explanation": "正确：“轻松拿到”表示不费力地拿到，与“跑得很快”的语境一致。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”与“拿到了第一名”的结果相矛盾，句子不通。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”指失去，与“拿到了第一名”相矛盾，句子不通。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”修饰“拿到”不自然，且与“跑得很快”直接矛盾。"}], "explanations": {"轻松": "正确：“轻松拿到”表示不费力地拿到，与“跑得很快”的语境一致。", "放弃": "语义：“放弃”与“拿到了第一名”的结果相矛盾，句子不通。", "丢失": "语义：“丢失”指失去，与“拿到了第一名”相矛盾，句子不通。", "慢": "搭配：“慢”修饰“拿到”不自然，且与“跑得很快”直接矛盾。"}, "sentence_index": 6, "correct_answer": "轻松"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小猫的身子很轻松，像一团棉花。", "explanation": "这里应该用〈轻盈〉。轻盈形容身体动作轻巧灵活，“轻松”指做事不费力，不用来形容身子。"}, {"text": "老师讲话的声音很轻松，像在哄孩子。", "explanation": "这里应该用〈轻柔〉。轻柔形容声音温和，不能用“轻松”描写声音。"}, {"text": "这碗粥的口味很轻松，清清淡淡的。", "explanation": "这里应该用〈清淡〉。清淡形容口味，不能用“轻松”形容口味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次复习后，他轻松得完成了所有作业。", "corrected_sentence": "这次复习后，他轻松地完成了所有作业。", "error_description": "错误：“轻松”修饰动词时应用“地”，不能用“得”。应说“轻松地完成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她每天跑步，所以跑长途也比轻松。", "corrected_sentence": "她每天跑步，所以跑长途也很轻松。", "error_description": "错误：“很”被换成了“比”。“比”表示比较，需要比较的对象，“比轻松”不成立。此处应用程度副词“很”，说“也很轻松”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
