INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22394, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示更进一步，强调后面说的更厉害。", "primary_collocate": null, "pronunciation": "shèn zhì", "ipa": "ʂən˥˩ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他太忙了，甚至没有时间吃饭。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里很冷，甚至会下雪。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥不会做饭，甚至不会煮鸡蛋。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一整天不说话，甚至不看我一眼。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多孩子，甚至大人，都喜欢这个游戏。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他病得很重，甚至不能下床。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有时晚上不睡觉，甚至两天不睡。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不认识我，甚至忘了自己的名字。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟爱玩儿，甚至上课也想着玩。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很便宜，甚至比超市还便宜。", "target_word": "甚至", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "递进强调，后面的情况更突出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甚至", "is_correct": true, "explanation": "表示更进一步：忙到连吃饭的时间都没有，符合“甚至”强调后面情况更突出。"}, {"text": "为了", "is_correct": false, "explanation": "语法：“为了”要接目的，“为了没有时间吃饭”不成立，句子无法成立。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作正在进行，与“没有时间”这种状态不搭。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词，不能修饰“没有时间”这样的动宾结构。"}], "explanations": {"甚至": "表示更进一步：忙到连吃饭的时间都没有，符合“甚至”强调后面情况更突出。", "为了": "语法：“为了”要接目的，“为了没有时间吃饭”不成立，句子无法成立。", "正在": "体貌：“正在”表示动作正在进行，与“没有时间”这种状态不搭。", "很": "搭配：“很”修饰形容词，不能修饰“没有时间”这样的动宾结构。"}, "sentence_index": 0, "correct_answer": "甚至"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他甚至明天会来。", "explanation": "这里应该用〈也许〉。甚至表示更进一步，强调更突出的情况，不能表示推测；说“他也许明天会来”要用“也许”。"}, {"text": "甚至下雨，比赛就取消了。", "explanation": "这里应该用〈因为〉。甚至表示更进一步，不表示原因；说明原因要用“因为”，如“因为下雨，比赛就取消了”。"}, {"text": "天下雨了，甚至我们回家了。", "explanation": "这里应该用〈所以〉。甚至表示更进一步，不表示结果；前面说了原因，后面的结果要用“所以”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甚至", "is_correct": true, "explanation": "表示更进一步：有时晚上不睡觉已经很突出，连续两天不睡程度更深，符合“甚至”。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不断，与“有时”表示间歇的说法互相矛盾。"}, {"text": "尚且", "is_correct": false, "explanation": "语域：“尚且”是书面语，通常要和“何况”配合使用，这种口语句子里不这样用。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示经常、一贯，与“有时”冲突。"}], "explanations": {"甚至": "表示更进一步：有时晚上不睡觉已经很突出，连续两天不睡程度更深，符合“甚至”。", "一直": "语义：“一直”表示持续不断，与“有时”表示间歇的说法互相矛盾。", "尚且": "语域：“尚且”是书面语，通常要和“何况”配合使用，这种口语句子里不这样用。", "总是": "语义：“总是”表示经常、一贯，与“有时”冲突。"}, "sentence_index": 6, "correct_answer": "甚至"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市很大，甚至很安静。", "explanation": "这里应该用〈但是〉。“甚至”表示递进，不能表示转折；“很安静”与“很大”之间是对比，不是更进一步。"}, {"text": "这本书很薄，甚至很有意思。", "explanation": "这里应该用〈不过〉。“甚至”不能用来表示转折，这里前后是让步关系，应说“不过”。"}, {"text": "他吃完饭，甚至出去了。", "explanation": "这里应该用〈然后〉。甚至表示更进一步，不表示先后顺序；先吃饭再出去，要用“然后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很喜欢唱歌，甚至了在路上也唱。", "corrected_sentence": "她很喜欢唱歌，甚至在路上也唱。", "error_description": "错误：“了”放在副词“甚至”后面。“甚至”后面不能加“了”，应删去。正确：“她很喜欢唱歌，甚至在路上也唱。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很累，甚至了不想说话。", "corrected_sentence": "他很累，甚至不想说话。", "error_description": "错误：“了”放在副词“甚至”和动词之间。“了”不能放在这里，应删去。正确：“他很累，甚至不想说话。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "看轻", "is_correct": true, "explanation": "与“看重”构成反义：看轻指认为某人或某事不重要。"}, {"text": "发现", "is_correct": false, "explanation": "与“看重”无反义关系，它指找到或察觉某事物。"}, {"text": "尊敬", "is_correct": false, "explanation": "与“看重”无反义关系，二者都是正面态度。"}, {"text": "推荐", "is_correct": false, "explanation": "与“看重”无反义关系，它指介绍并举荐某人或某物。"}], "correct_answer": "看轻", "explanations": {"看轻": "与“看重”构成反义：看轻指认为某人或某事不重要。", "发现": "与“看重”无反义关系，它指找到或察觉某事物。", "尊敬": "与“看重”无反义关系，二者都是正面态度。", "推荐": "与“看重”无反义关系，它指介绍并举荐某人或某物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻视", "is_correct": true, "explanation": "与“看重”构成反义：轻视指认为不重要、不当回事。"}, {"text": "欣赏", "is_correct": false, "explanation": "与“看重”无反义关系，二者都是正面评价。"}, {"text": "注意", "is_correct": false, "explanation": "与“看重”无反义关系，它表示留心、关注。"}, {"text": "照顾", "is_correct": false, "explanation": "与“看重”无反义关系，它表示照料、关照。"}], "correct_answer": "轻视", "explanations": {"轻视": "与“看重”构成反义：轻视指认为不重要、不当回事。", "欣赏": "与“看重”无反义关系，二者都是正面评价。", "注意": "与“看重”无反义关系，它表示留心、关注。", "照顾": "与“看重”无反义关系，它表示照料、关照。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "觉得一个人或东西很重要。", "primary_collocate": null, "pronunciation": "kàn zhòng", "ipa": "kʰan˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师很看重这个学生，常常帮助他。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最看重的是我们的友谊。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很看重自己的名声。", "target_word": "看重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理看重小李，想让他当组长。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶看重这张老照片，从不让人碰。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都看重他，因为他做事很可靠。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人看重自己的自由。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们公司很看重客户的意见。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球队看重这位新来的队员。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "校长看重她的才华，让她上台发言。", "target_word": "看重", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "看重了", "label": "体标"}, {"form": "看重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "认为某个人或某样东西很重要、很有价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a710815b-c492-4cee-80cf-d7c9671808e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看重", "is_correct": true, "explanation": "正确：“老师很看重这个学生，常常帮助他”，“看重”表示认为学生重要，与“帮助他”相呼应。"}, {"text": "嫌弃", "is_correct": false, "explanation": "语义：“嫌弃”表示不喜欢，与“常常帮助他”的语境相矛盾。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：“厌恶”表示极度讨厌，与“常常帮助他”的语境完全相反。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”指欺压，与“常常帮助他”完全相反。"}], "explanations": {"看重": "正确：“老师很看重这个学生，常常帮助他”，“看重”表示认为学生重要，与“帮助他”相呼应。", "嫌弃": "语义：“嫌弃”表示不喜欢，与“常常帮助他”的语境相矛盾。", "厌恶": "语义：“厌恶”表示极度讨厌，与“常常帮助他”的语境完全相反。", "欺负": "语义：“欺负”指欺压，与“常常帮助他”完全相反。"}, "sentence_index": 0, "correct_answer": "看重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们站在山顶，远远地看重了那片湖。", "explanation": "这里应该用〈眺望〉。眺望指向远处看风景，看重指认为人或事重要，不表示看景。"}, {"text": "周末我去医院看重生病的朋友。", "explanation": "这里应该用〈看望〉。看望指探望；看重不表示去探望。"}, {"text": "我抬头看重了天上的飞机。", "explanation": "这里应该用〈看见〉。看见指视觉上看到眼前的景物；看重不表示看到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看重", "is_correct": true, "explanation": "正确：“年轻人看重自己的自由”表示认为自由很重要。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”不能与“自由”搭配。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”指拆掉建筑，不能用于“自由”。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指涂墙，与“年轻人”的语境无关。"}], "explanations": {"看重": "正确：“年轻人看重自己的自由”表示认为自由很重要。", "测量": "搭配：“测量”不能与“自由”搭配。", "拆除": "搭配：“拆除”指拆掉建筑，不能用于“自由”。", "粉刷": "语义：“粉刷”指涂墙，与“年轻人”的语境无关。"}, "sentence_index": 6, "correct_answer": "看重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我感冒了，下午要去医院看重。", "explanation": "这里应该用〈看病〉。看病指找医生治病；看重指认为重要，不表示去看医生。"}, {"text": "我留在家里看重院子，不让别人进来。", "explanation": "这里应该用〈看家〉。看家指守护家里；看重不表示守护。"}, {"text": "姐姐负责看重弟弟，每天带他去上学。", "explanation": "这里应该用〈看管〉。看管指照看孩子；看重指认为重要，不表示照看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈很看重了我的健康，总让我早点睡。", "corrected_sentence": "妈妈很看重我的健康，总让我早点睡。", "error_description": "错误：“看重”表示一种持续的态度，前面有“很”时后面不能加“了”。应说“很看重我的健康”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年轻人比看重自己的自由。", "corrected_sentence": "年轻人很看重自己的自由。", "error_description": "错误：“很”被换成了“比”。“比”表示比较，需要比较的对象，“比看重”不成立。此处应用程度副词“很”，说“很看重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
