INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非常认真地按照规则去做，不随便改变。", "primary_collocate": null, "pronunciation": "yán gé zūn shǒu", "ipa": "jɛn˧˥ kɤ˧˥ tsuən˥ ʂoʊ˨˩˦", "syllable_count": 4, "sentences": [{"text": "做实验时，要严格遵守老师的步骤。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店严格遵守营业时间，从不提前关门。", "target_word": "严格遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他严格遵守医嘱，每天按时吃药。", "target_word": "严格遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要严格遵守食品安全的规定。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她严格遵守作息时间，十点就睡。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "队员们严格遵守训练计划。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过马路时，大家都严格遵守红绿灯。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作为司机，他严格遵守交通法规。", "target_word": "严格遵守", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这种药，请严格遵守说明书上的方法。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板严格遵守与客人的约定，从不改变。", "target_word": "严格遵守", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "严格遵守了", "label": "体标"}, {"form": "嚴格遵守", "label": "繁体"}], "register": "书面", "sense_fingerprint": "非常认真地依照规则或约定去做，不随意改动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a710815b-c492-4cee-80cf-d7c9671808e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严格遵守", "is_correct": true, "explanation": "符合语境：“要”后接的是按步骤去做，与实验的目的一致。"}, {"text": "违背", "is_correct": false, "explanation": "语义：“违背”与“要”的要求相反，不能用在要求别人去做的句子里。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”的对象是人或言行，不说嘲笑步骤。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：步骤是要执行的，“要拒绝步骤”与实验的要求矛盾。"}], "explanations": {"严格遵守": "符合语境：“要”后接的是按步骤去做，与实验的目的一致。", "违背": "语义：“违背”与“要”的要求相反，不能用在要求别人去做的句子里。", "嘲笑": "搭配：“嘲笑”的对象是人或言行，不说嘲笑步骤。", "拒绝": "语义：步骤是要执行的，“要拒绝步骤”与实验的要求矛盾。"}, "sentence_index": 0, "correct_answer": "严格遵守"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨房主管严格遵守员工戴手套。", "explanation": "这里应该用〈严格要求〉。遵守是自己照规定做，对别人提出标准要说严格要求。"}, {"text": "卫生局严格遵守餐馆的卫生。", "explanation": "这里应该用〈监督〉。遵守针对的是规定，对餐馆卫生进行管理要说严格监督。"}, {"text": "工厂严格遵守食品的质量。", "explanation": "这里应该用〈检测〉。遵守用于规定、要求，质量要靠检测来判断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严格遵守", "is_correct": true, "explanation": "符合语境：过马路要按红绿灯行走，“严格遵守”与此相符。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多用于风景、作品，不说欣赏红绿灯。"}, {"text": "逗", "is_correct": false, "explanation": "搭配：“逗”的对象是人或动物，不能说逗红绿灯。"}, {"text": "驱赶", "is_correct": false, "explanation": "语义：“驱赶”的对象是人或动物，红绿灯不能被驱赶。"}], "explanations": {"严格遵守": "符合语境：过马路要按红绿灯行走，“严格遵守”与此相符。", "欣赏": "搭配：“欣赏”多用于风景、作品，不说欣赏红绿灯。", "逗": "搭配：“逗”的对象是人或动物，不能说逗红绿灯。", "驱赶": "语义：“驱赶”的对象是人或动物，红绿灯不能被驱赶。"}, "sentence_index": 6, "correct_answer": "严格遵守"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "质检员严格遵守产品的质量。", "explanation": "这里应该用〈检查〉。遵守用于规定、要求，检查产品质量要说严格检查。"}, {"text": "经理严格遵守每一笔开支。", "explanation": "这里应该用〈审批〉。遵守针对规定，开支要经过审批，不能说遵守开支。"}, {"text": "警察严格遵守证人的安全。", "explanation": "这里应该用〈保护〉。遵守用于规定，证人的安全要说严格保护。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人了严格遵守了一套操作规程。", "corrected_sentence": "工人严格遵守了一套操作规程。", "error_description": "多余的“了”：“了”不能放在状语“严格”之前，应删去，说“工人严格遵守了一套操作规程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在严格遵守了合同的条款。", "corrected_sentence": "他严格遵守了合同的条款。", "error_description": "时态冲突：“正在”表示动作进行中，与表示完成的“了”不能同用，应删去“正在”，说“严格遵守了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
