INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22404, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人一起坐下来，讲事情、做决定。", "primary_collocate": null, "pronunciation": "huì yì", "ipa": "xweɪ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "我们明天上午有一个会议。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理今天要参加三个会议。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议从九点开始，十一点结束。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议讨论了新的计划。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上，大家都说了自己的想法。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，会议改到了下周。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个会议太长了，大家都累了。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请家长来参加会议。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议决定下个月去上海。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把会议的时间写在本子上了。", "target_word": "会议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "次", "label": "量词"}, {"form": "會議", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多人聚在一起商量事情、做决定的活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会议", "is_correct": true, "explanation": "与“明天上午”的时间相合，“有一个”后接一场可以安排的活动。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”与“明天上午”的时间冲突，不能同时成立。"}, {"text": "早餐", "is_correct": false, "explanation": "搭配：“早餐”一般说“吃一顿早餐”，不能说“有一个早餐”，量词不配。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是疾病，不能作为可以安排的事件，与“有一个”的说法不合。"}], "explanations": {"会议": "与“明天上午”的时间相合，“有一个”后接一场可以安排的活动。", "夜晚": "语义：“夜晚”与“明天上午”的时间冲突，不能同时成立。", "早餐": "搭配：“早餐”一般说“吃一顿早餐”，不能说“有一个早餐”，量词不配。", "感冒": "语义：“感冒”是疾病，不能作为可以安排的事件，与“有一个”的说法不合。"}, "sentence_index": 0, "correct_answer": "会议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们周末开了一个会议，大家又唱又跳。", "explanation": "这里应该用〈晚会〉。会议是为讨论事情、做决定而召开的集会，又唱又跳是晚会的内容。"}, {"text": "他是公司的会议。", "explanation": "这里应该用〈会计〉。会议指集会，表示人的职业要说“会计”，不能说“会议”。"}, {"text": "他是这个俱乐部的会议。", "explanation": "这里应该用〈会员〉。会议是集会，表示成员身份要说“会员”，不能说“会议”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会议", "is_correct": true, "explanation": "“会议”可以持续很长时间，符合“太长了，大家都累了”的描述。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：“蛋糕”不能被说成“太长”，句子无法成立。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”是日期，不能说“太长了”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“太长”形容时间或长度，“声音”一般说“太大”或“太响”。"}], "explanations": {"会议": "“会议”可以持续很长时间，符合“太长了，大家都累了”的描述。", "蛋糕": "语义：“蛋糕”不能被说成“太长”，句子无法成立。", "生日": "语义：“生日”是日期，不能说“太长了”。", "声音": "搭配：“太长”形容时间或长度，“声音”一般说“太大”或“太响”。"}, "sentence_index": 6, "correct_answer": "会议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们今天玩了一个会议。", "explanation": "这里应该用〈游戏〉。玩的是游戏，会议是讨论事情的活动，不能说“玩”。"}, {"text": "我们班赢了会议。", "explanation": "这里应该用〈比赛〉。“赢”的对象是比赛，会议不能被赢。"}, {"text": "这次会议我考得很好。", "explanation": "这里应该用〈考试〉。“考得很好”说的是考试，会议不是可以考的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只会议由经理负责。", "corrected_sentence": "这个会议由经理负责。", "error_description": "错误：量词“只”。正确：“个”。“只”用于动物或成对物品中的一个，会议前面应用“个”或“次”，应为“这个会议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每个次会议都有记录。", "corrected_sentence": "每次会议都有记录。", "error_description": "错误：重复量词“个次”。正确：“每次”。“每”后面已经带了量词“次”，不能再加“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
