INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22406, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想一个事情，觉得它是真的。", "primary_collocate": null, "pronunciation": "rèn wéi", "ipa": "ɻən˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他认为那个消息是真的。", "target_word": "认为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我认为今天是星期五。", "target_word": "认为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩认为月亮在跟着他走。", "target_word": "认为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直认为朋友不会骗她。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我认为他已经回家了。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥认为这件事是我做的。", "target_word": "认为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们过去认为地球是平的。", "target_word": "认为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你认为他说的是真话吗？", "target_word": "认为", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们都认为那个人没有说谎。", "target_word": "认为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶认为吃药就会好。", "target_word": "认为", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "心里觉得某件事是真的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a710815b-c492-4cee-80cf-d7c9671808e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "认为", "is_correct": true, "explanation": "认为：表示他心里认定那个消息是真的，与句意一致。"}, {"text": "承担", "is_correct": false, "explanation": "搭配：“承担”的宾语是责任、任务，不能接“那个消息是真的”这样的判断。"}, {"text": "责备", "is_correct": false, "explanation": "配价：“责备”后接的是被责备的人，不能直接带“那个消息是真的”作宾语。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”表示对他人的恩惠心存谢意，与对消息真假的判断无关。"}], "explanations": {"认为": "认为：表示他心里认定那个消息是真的，与句意一致。", "承担": "搭配：“承担”的宾语是责任、任务，不能接“那个消息是真的”这样的判断。", "责备": "配价：“责备”后接的是被责备的人，不能直接带“那个消息是真的”作宾语。", "感激": "语义：“感激”表示对他人的恩惠心存谢意，与对消息真假的判断无关。"}, "sentence_index": 0, "correct_answer": "认为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认为很高兴。", "explanation": "这里应该用〈感到〉。感到表示心里的感受，认为表示对事情的看法，不能用来说自己的情绪。"}, {"text": "他把我认为朋友。", "explanation": "这里应该用〈当作〉。“把……当作……”表示把某人视为某种身份，“认为”不能直接接在“把我”后面表示视为朋友。"}, {"text": "他认为一份新工作。", "explanation": "这里应该用〈找到〉。找到表示获得某物，认为表示看法，不能用来说获得工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认为", "is_correct": true, "explanation": "认为：表示人们过去对“地球是平的”形成看法，符合句意。"}, {"text": "称赞", "is_correct": false, "explanation": "语义：“称赞”表示夸奖，不能用来表示对一个事实的看法，句子读起来不通。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”表示赞美，不能用于“地球是平的”这样的陈述。"}, {"text": "担任", "is_correct": false, "explanation": "搭配：“担任”的宾语是职务、角色，不能接“地球是平的”这样的陈述。"}], "explanations": {"认为": "认为：表示人们过去对“地球是平的”形成看法，符合句意。", "称赞": "语义：“称赞”表示夸奖，不能用来表示对一个事实的看法，句子读起来不通。", "歌颂": "语义：“歌颂”表示赞美，不能用于“地球是平的”这样的陈述。", "担任": "搭配：“担任”的宾语是职务、角色，不能接“地球是平的”这样的陈述。"}, "sentence_index": 6, "correct_answer": "认为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我认为很冷，想穿外套。", "explanation": "这里应该用〈觉得〉。觉得可以表示身体的感受，认为表示对事情的看法，不能用来说自己身体上的感觉。"}, {"text": "我认为他的消息。", "explanation": "这里应该用〈打听〉。打听指询问和探问消息，认为表示看法，不能用来说获得消息。"}, {"text": "学生们认为校规。", "explanation": "这里应该用〈遵守〉。遵守指依照规定行事，认为表示看法，不能说“认为校规”来表示遵从。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我认为了这件事不简单。", "corrected_sentence": "我认为这件事不简单。", "error_description": "错误在于“认为”后多加了“了”。“认为”是表示看法的动词，不带“了”表示完成，正确说法是“我认为这件事不简单。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不认为了他说的是真话。", "corrected_sentence": "我不认为他说的是真话。", "error_description": "错误在于“认为”后多加了“了”。“认为”是表示看法的动词，不能带“了”表示完成；正确说法是“我不认为他说的是真话。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9351fea-d7c1-4ccf-aca2-0b83234c9c4a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
