INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22410, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示很少或一点点。", "primary_collocate": null, "pronunciation": "shāo wēi", "ipa": "ʂɑʊ̯˥ weɪ̯˥", "syllable_count": 2, "sentences": [{"text": "你稍微等一下，我马上就来。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请稍微坐一会儿，经理很快回来。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做汤的时候，稍微放一点盐就行。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你稍微休息一下，再接着写作业吧。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我学汉语没多久，只能稍微说几句。", "target_word": "稍微", "complexity_tier": "T3", "furigana": "wǒ xué hànyǔ méi duō jiǔ, zhǐ néng shāo wēi shuō jǐ jù.", "sentence_source": "generated"}, {"text": "这个字你稍微写大一点，老师才看得清。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你稍微让一让，我要过去。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前稍微收拾一下房间吧。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他稍微看了一眼就知道答案了。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水太烫了，稍微凉一会儿再喝。", "target_word": "稍微", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，用在动词前，表示动作时间短或数量少，如“稍微等一下”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a253744-136e-4587-a572-1ffd876a460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稍微", "is_correct": true, "explanation": "稍微：表示动作时间短，与“等一下”“马上就来”的短时语境相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已完成，与“等一下”的未来动作不合。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不断，与表示短时的“一下”不搭配。"}, {"text": "特别", "is_correct": false, "explanation": "语义：“特别”表示程度高，不能用来说明等待的时间短。"}], "explanations": {"稍微": "稍微：表示动作时间短，与“等一下”“马上就来”的短时语境相符。", "已经": "语义：“已经”表示动作已完成，与“等一下”的未来动作不合。", "一直": "搭配：“一直”表示持续不断，与表示短时的“一下”不搭配。", "特别": "语义：“特别”表示程度高，不能用来说明等待的时间短。"}, "sentence_index": 0, "correct_answer": "稍微"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他稍微买了一百本书。", "explanation": "这里应该用〈一共〉。“稍微”只表示数量少或一点点，不能修饰“一百本”这样的大数量。"}, {"text": "他稍微等了一整天。", "explanation": "这里应该用〈足足〉。“稍微”只表示时间短，与“一整天”的长时间相矛盾。"}, {"text": "我稍微说了很多遍。", "explanation": "这里应该用〈反复〉。“稍微”只表示一点点，不能表示多次重复。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稍微", "is_correct": true, "explanation": "稍微：表示动作幅度或时间小，与“让一让”的轻微请求相符。"}, {"text": "完全", "is_correct": false, "explanation": "语义：“完全”表示整体或彻底，与“让一让”的小幅度动作相冲突。"}, {"text": "狠狠", "is_correct": false, "explanation": "语域：“狠狠”口气粗暴，与礼貌的“请你”不合。"}, {"text": "始终", "is_correct": false, "explanation": "搭配：“始终”表示持续不变，与短时的“让一让”不搭配。"}], "explanations": {"稍微": "稍微：表示动作幅度或时间小，与“让一让”的轻微请求相符。", "完全": "语义：“完全”表示整体或彻底，与“让一让”的小幅度动作相冲突。", "狠狠": "语域：“狠狠”口气粗暴，与礼貌的“请你”不合。", "始终": "搭配：“始终”表示持续不变，与短时的“让一让”不搭配。"}, "sentence_index": 6, "correct_answer": "稍微"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的成绩稍微提高了一大截。", "explanation": "这里应该用〈显著〉。“稍微”只表示一点点，不能表示大幅度的明显变化。"}, {"text": "这件事稍微造成了严重的损失。", "explanation": "这里应该用〈竟然〉。“稍微”只表示一点点，不能修饰“严重的损失”。"}, {"text": "他稍微忘掉了所有的事情。", "explanation": "这里应该用〈彻底〉。“稍微”只表示一点点，与“所有”的全部含义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你稍微的等一会儿，我去拿钥匙。", "corrected_sentence": "你稍微等一会儿，我去拿钥匙。", "error_description": "错误：“稍微”后面多加了“的”。“稍微”是副词，直接修饰动词“等”，中间不能加“的”。正确说法是“你稍微等一会儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "汤太热了，你很稍微晾一会儿再喝。", "corrected_sentence": "汤太热了，你稍微晾一会儿再喝。", "error_description": "错误：“稍微”前多加了“很”。“稍微”已表示程度或时间少，与表示程度高的“很”叠用，语义矛盾。正确说法是“你稍微晾一会儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
