INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不同国家的人互相来往、一起做事。", "primary_collocate": null, "pronunciation": "guó jì jiāo wǎng", "ipa": "kwo˧˥ tɕi˥˩ tɕjɑʊ̯˥ wɑŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "国际交往时，我们要先了解对方的习惯。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做国际交往的工作，要会说几种语言。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们通过夏令营开始了国际交往。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际交往中，送礼物也要看对方的文化。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多参加国际交往，可以认识很多朋友。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际交往不只是开会，也包括一起吃饭。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校办了活动，让学生多一些国际交往。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就有很多国际交往的机会。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市因为旅游业发达，国际交往很频繁。", "target_word": "国际交往", "complexity_tier": "T3", "furigana": "guó jì jiāo wǎng", "sentence_source": "generated"}, {"text": "他靠国际交往认识了很多外国朋友。", "target_word": "国际交往", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國際交往", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词，不同国家的人之间的来往和合作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a253744-136e-4587-a572-1ffd876a460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际交往", "is_correct": true, "explanation": "国际交往指不同国家的人之间的来往，与句中“国际交往时”相符。"}, {"text": "国际地震", "is_correct": false, "explanation": "语义：地震是自然灾害，与“了解对方的习惯”无关。"}, {"text": "国际压力", "is_correct": false, "explanation": "搭配：“国际压力”不是可以进行交往的场合，不能说“国际压力时”。"}, {"text": "国际新闻", "is_correct": false, "explanation": "语义：新闻是报道，不能指人与人交往的场合，不能说“国际新闻时，了解对方的习惯”。"}], "explanations": {"国际交往": "国际交往指不同国家的人之间的来往，与句中“国际交往时”相符。", "国际地震": "语义：地震是自然灾害，与“了解对方的习惯”无关。", "国际压力": "搭配：“国际压力”不是可以进行交往的场合，不能说“国际压力时”。", "国际新闻": "语义：新闻是报道，不能指人与人交往的场合，不能说“国际新闻时，了解对方的习惯”。"}, "sentence_index": 0, "correct_answer": "国际交往"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和同事都是本地人，他的国际交往很好，大家经常一起吃饭。", "explanation": "这里应该用〈人际关系〉。国际交往指不同国家的人之间的往来，同事都是本地人时，相处要说人际关系。"}, {"text": "我们小区的国际交往很频繁，邻居都是老街坊，大家经常互相帮忙。", "explanation": "这里应该用〈邻里往来〉。国际交往指不同国家的人之间的往来，同一小区的老街坊之间的来往要说邻里往来。"}, {"text": "两家本地公司之间的国际交往越来越多。", "explanation": "这里应该用〈商业往来〉。国际交往指国家之间的往来，两家本地公司之间的业务联系要说商业往来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际交往", "is_correct": true, "explanation": "国际交往指不同国家的人之间的来往，句中“让学生多一些”正指交往活动。"}, {"text": "国际噪音", "is_correct": false, "explanation": "语义：噪音不是可以让学生“多一些”的交流对象，句意不通。"}, {"text": "国际闪电", "is_correct": false, "explanation": "搭配：“多一些”不宜与闪电这类自然现象搭配。"}, {"text": "国际疾病", "is_correct": false, "explanation": "语义：疾病不能让学生“多一些”，与“办活动”的语境不符。"}], "explanations": {"国际交往": "国际交往指不同国家的人之间的来往，句中“让学生多一些”正指交往活动。", "国际噪音": "语义：噪音不是可以让学生“多一些”的交流对象，句意不通。", "国际闪电": "搭配：“多一些”不宜与闪电这类自然现象搭配。", "国际疾病": "语义：疾病不能让学生“多一些”，与“办活动”的语境不符。"}, "sentence_index": 6, "correct_answer": "国际交往"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和老同学都是本地人，我们的国际交往很深，十年没有断过。", "explanation": "这里应该用〈友情〉。国际交往指不同国家的人之间的往来，两个本地人之间的交情要说友情。"}, {"text": "这座山村的村民都是本地人，村民之间的国际交往很频繁，大家经常一起种地。", "explanation": "这里应该用〈来往〉。国际交往指不同国家的人之间的往来，同村本地村民之间要说“来往”。"}, {"text": "这家饭店的客人都是附近居民，每天的国际交往很多，大家常在这里聊天。", "explanation": "这里应该用〈客流〉。国际交往指不同国家的人之间的往来，附近居民在饭店里的进进出出要说客流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有过几只国际交往，每次都学到不少东西。", "corrected_sentence": "他有过几次国际交往，每次都学到不少东西。", "error_description": "量词错误：“国际交往”以“次”计量，“只”不能用于交往活动。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班这学期安排了一只国际交往，大家都很期待。", "corrected_sentence": "我们班这学期安排了一次国际交往，大家都很期待。", "error_description": "量词错误：“国际交往”以“次”计量，应说“一次国际交往”，“只”不能用于交往活动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
