INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "想一想，说一个东西是对的还是错的。", "primary_collocate": null, "pronunciation": "pàn duàn", "ipa": "pʰan˥˩ twan˥˩", "syllable_count": 2, "sentences": [{"text": "你来判断，这个答案对不对？", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会判断这朵花有没有毒。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你判断一下，这句话是真是假。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两种解法我一时无法判断哪种是对的。", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能判断这段话的内容是对的还是错的吗？", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想了想，判断这道题的答案是错的。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶闻一闻，就能判断鱼新不新。", "target_word": "判断", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们要学会判断什么是对，什么是错。", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只看一眼，我没法判断这个东西好不好。", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家判断这个故事是不是真的。", "target_word": "判断", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "判断了", "label": "体标"}, {"form": "判断力", "label": "复合"}], "register": "中性", "sense_fingerprint": "想一想后说东西是对是错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a253744-136e-4587-a572-1ffd876a460f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "判断", "is_correct": true, "explanation": "判断指想一想后说对错，句中“这个答案对不对”正是要判断的内容。"}, {"text": "洗", "is_correct": false, "explanation": "语义：洗是清除脏东西，与判断答案对错无关。"}, {"text": "搬", "is_correct": false, "explanation": "语义：搬是移动物体，与判断答案不符。"}, {"text": "寄", "is_correct": false, "explanation": "搭配：“寄”针对信件或包裹，不能用于“答案对不对”。"}], "explanations": {"判断": "判断指想一想后说对错，句中“这个答案对不对”正是要判断的内容。", "洗": "语义：洗是清除脏东西，与判断答案对错无关。", "搬": "语义：搬是移动物体，与判断答案不符。", "寄": "搭配：“寄”针对信件或包裹，不能用于“答案对不对”。"}, "sentence_index": 0, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上判断一次牙。", "explanation": "这里应该用〈刷〉。判断是想一想说对错，清洁牙齿要说刷牙。"}, {"text": "妈妈判断了一条鱼。", "explanation": "这里应该用〈挑〉。判断是对对错的认识，挑选东西要说挑。"}, {"text": "下课后，老师判断了黑板上的字。", "explanation": "这里应该用〈擦〉。判断是想一想说对错，把黑板上的字弄掉要说擦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "判断", "is_correct": true, "explanation": "判断指想一想说对错，“闻一闻就能……鱼新不新”正是对鱼的新鲜度作出认识。"}, {"text": "煎", "is_correct": false, "explanation": "语义：煎是用油加热做饭，与判断鱼新不新无关。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是丢弃，不是对事物作出认识。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”后面不能接“鱼新不新”这类结构，句子不通。"}], "explanations": {"判断": "判断指想一想说对错，“闻一闻就能……鱼新不新”正是对鱼的新鲜度作出认识。", "煎": "语义：煎是用油加热做饭，与判断鱼新不新无关。", "扔": "语义：扔是丢弃，不是对事物作出认识。", "拍": "搭配：“拍”后面不能接“鱼新不新”这类结构，句子不通。"}, "sentence_index": 6, "correct_answer": "判断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶给孩子们判断了一个故事。", "explanation": "这里应该用〈讲〉。判断是对对错作出认识，给孩子们讲故事要说讲。"}, {"text": "这位歌手判断了一首歌。", "explanation": "这里应该用〈唱〉。判断是对事情作出认识，演唱歌曲要说唱。"}, {"text": "他判断了一下花园里的小路。", "explanation": "这里应该用〈修〉。判断是对对错作出认识，修整小路要说修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一眼就判断着这个方案是错的。", "corrected_sentence": "他一眼就判断出这个方案是错的。", "error_description": "体标错误：“着”表示持续，与表示瞬间得出结论的“一眼就”冲突；应用结果补语“出”，说“判断出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我判断了错这道题的答案。", "corrected_sentence": "我判断错了这道题的答案。", "error_description": "补语错误：结果补语“错”应紧跟动词，说“判断错了”，不能说“判断了错”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ca7159c-b545-4568-be27-c2422646b196') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
