INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22418, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "很快就要做，不用等很久。", "primary_collocate": null, "pronunciation": "mǎ shàng", "ipa": "ma˨˩ ʂaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你先坐一下，饭马上就好。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我马上到，你在门口等我。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“大家马上回教室。”", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到电话响，他马上跑过去了。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影马上开始了，我们快进去吧。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看完这本书，马上还给你。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天马上要黑了，我们回家吧。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一回到家，马上换了衣服。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请等一下，经理马上来。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨马上就要下了，快把伞拿上。", "target_word": "马上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "馬上", "label": "繁体"}], "register": "口语", "sense_fingerprint": "副词，表示动作很快就要发生，不用等很久", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22418, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示持续不变，与“就好”的即将完成相冲突。"}, {"text": "马上", "is_correct": true, "explanation": "正确：“马上”表示很快，符合句意。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与“饭就好”的即将完成相冲突。"}, {"text": "特别", "is_correct": false, "explanation": "搭配：“特别”修饰程度，不能用在“饭……就好”这一结构中。"}], "explanations": {"永远": "语义：“永远”表示持续不变，与“就好”的即将完成相冲突。", "马上": "正确：“马上”表示很快，符合句意。", "偶尔": "语义：“偶尔”表示有时，与“饭就好”的即将完成相冲突。", "特别": "搭配：“特别”修饰程度，不能用在“饭……就好”这一结构中。"}, "sentence_index": 0, "correct_answer": "马上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他小时候马上住在上海。", "explanation": "这里应该用〈曾经〉。马上表示很快就要发生，不能表示过去的经历。"}, {"text": "他晚上马上看电视。", "explanation": "这里应该用〈常常〉。马上表示很快就要发生，不能表示经常发生的习惯。"}, {"text": "我马上去过北京。", "explanation": "这里应该用〈曾经〉。马上表示很快要发生的动作，不能表示过去的经历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“天要黑了”的变化相冲突。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”指一直如此，与即将发生的变化相冲突。"}, {"text": "马上", "is_correct": true, "explanation": "正确：“马上”表示很快发生，符合句意。"}, {"text": "千万", "is_correct": false, "explanation": "搭配：“千万”多用于叮嘱或禁止，不能修饰“要黑了”这种自然变化。"}], "explanations": {"从不": "语义：“从不”表示从来没有，与“天要黑了”的变化相冲突。", "始终": "语义：“始终”指一直如此，与即将发生的变化相冲突。", "马上": "正确：“马上”表示很快发生，符合句意。", "千万": "搭配：“千万”多用于叮嘱或禁止，不能修饰“要黑了”这种自然变化。"}, "sentence_index": 6, "correct_answer": "马上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份友谊会马上存在。", "explanation": "这里应该用〈永远〉。马上只表示很快发生，不能表示长久存在的状态。"}, {"text": "地球马上是圆的。", "explanation": "这里应该用〈本来〉。马上表示很快就会出现的变化，地球本来就是圆的，不能用马上。"}, {"text": "他马上依然年轻。", "explanation": "这里应该用〈一直〉。马上表示很快出现的变化，不能表示状态长期保持不变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会议马上的开始，请大家坐好。", "corrected_sentence": "会议马上开始，请大家坐好。", "error_description": "结构错误：副词“马上”后不能直接加“的”修饰动词短语，应去掉“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "火车马上的进站，请站在黄线后面。", "corrected_sentence": "火车马上进站，请站在黄线后面。", "error_description": "结构错误：“马上”是副词，不能像形容词那样后接“的”，应去掉“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
