INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "专业指一个人专门学习或从事的学科或领域。", "primary_collocate": null, "pronunciation": "zhuān yè", "ipa": "ʈʂwan˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "我的专业是历史。", "target_word": "专业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你学什么专业？", "target_word": "专业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她选了一个很难的专业。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥的专业是电脑，他每天都写程序。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对这个专业很有兴趣。", "target_word": "专业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "上大学以前，我还不知道要选什么专业。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的专业不一样，可是我们是好朋友。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他毕业后做的工作和专业没有关系。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟想换一个专业，爸爸不同意。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的专业是音乐，所以唱歌唱得很好。", "target_word": "专业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "專業", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "专业·名词·专门学习或从事的领域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd295e12-7231-4a6a-a8ef-075f24fccda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "专业：指所学的学科，“我的专业是历史”说明学的是历史。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指身体的高度，不能与“是历史”搭配，句子说不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指个人的脾气特点，不能是一门学科。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“是历史”搭配，句子说不通。"}], "explanations": {"专业": "专业：指所学的学科，“我的专业是历史”说明学的是历史。", "身高": "语义：“身高”指身体的高度，不能与“是历史”搭配，句子说不通。", "性格": "语义：“性格”指个人的脾气特点，不能是一门学科。", "颜色": "搭配：“颜色”不能与“是历史”搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的专业是医生，每天都看病人。", "explanation": "这里应该用〈职业〉。“专业”指所学的方向，不能指工作身份。"}, {"text": "这孩子的专业很好，每顿都吃两碗饭。", "explanation": "这里应该用〈食欲〉。“专业”指所学的学科或所做的事，不能用来说吃饭的胃口。"}, {"text": "这个菜的专业很好，我每天都吃。", "explanation": "这里应该用〈味道〉。“专业”指所学或所做的领域，不能用来形容菜的口感。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专业", "is_correct": true, "explanation": "专业：指所学的学科，“我们的专业不一样”说明所学的方向不同。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是副词，不能放在“我们的”后面作主语。"}, {"text": "漂亮", "is_correct": false, "explanation": "语法：“漂亮”是形容词，“我们的漂亮不一样”不通。"}, {"text": "一起", "is_correct": false, "explanation": "语法：“一起”是副词，不能作名词用在“我们的”后面。"}], "explanations": {"专业": "专业：指所学的学科，“我们的专业不一样”说明所学的方向不同。", "非常": "语法：“非常”是副词，不能放在“我们的”后面作主语。", "漂亮": "语法：“漂亮”是形容词，“我们的漂亮不一样”不通。", "一起": "语法：“一起”是副词，不能作名词用在“我们的”后面。"}, "sentence_index": 6, "correct_answer": "专业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在金融专业工作，每天很忙。", "explanation": "这里应该用〈行业〉。“专业”指所学的学科，不能指工作的领域或单位。"}, {"text": "他的专业很高，有一米八。", "explanation": "这里应该用〈个子〉。“专业”指所学的学科，不能说人的高矮。"}, {"text": "她的专业很高兴，老师让她回家。", "explanation": "这里应该用〈心情〉。“专业”指所学的学科，不能用来形容人的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我个专业，我很喜欢它。", "corrected_sentence": "这是我的专业，我很喜欢它。", "error_description": "“我的”表示所属，应写成“我的专业”；“我个专业”误用量词“个”，量词不能直接放在代词和名词之间表示所属。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹地专业是英语，她很喜欢。", "corrected_sentence": "我妹妹的专业是英语，她很喜欢。", "error_description": "“的”误写为“地”：“的”修饰名词“专业”，应写成“我妹妹的专业”；“地”用于修饰动词或形容词，“妹妹地专业”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8447778d-b004-49a8-af3a-5f79a288da48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "synonym", "options": [{"text": "独特", "is_correct": true, "explanation": "“独特”表示独有的、跟别的不一样，与“特别的气质”中的“特别”意思相近。"}, {"text": "普通", "is_correct": false, "explanation": "“普通”表示平常、一般，意思和“特别”相反，不是近义词。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”表示没有声音、不吵闹，与“特别”的意思无关。"}, {"text": "便宜", "is_correct": false, "explanation": "“便宜”表示价钱低，与“特别”的意思无关。"}], "correct_answer": "独特", "explanations": {"独特": "“独特”表示独有的、跟别的不一样，与“特别的气质”中的“特别”意思相近。", "普通": "“普通”表示平常、一般，意思和“特别”相反，不是近义词。", "安静": "“安静”表示没有声音、不吵闹，与“特别”的意思无关。", "便宜": "“便宜”表示价钱低，与“特别”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "快乐", "is_correct": false, "explanation": "“快乐”表示高兴，与“特别”的意思无关，不是反义词。"}, {"text": "普通", "is_correct": true, "explanation": "“普通”表示平常、一般、不突出，与“跟别的不一样”的“特别”意思相反。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”表示没有脏东西，与“特别”的意思无关，不是反义词。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”表示做事严肃、不马虎，与“特别”的意思无关，不是反义词。"}], "correct_answer": "普通", "explanations": {"快乐": "“快乐”表示高兴，与“特别”的意思无关，不是反义词。", "普通": "“普通”表示平常、一般、不突出，与“跟别的不一样”的“特别”意思相反。", "干净": "“干净”表示没有脏东西，与“特别”的意思无关，不是反义词。", "认真": "“认真”表示做事严肃、不马虎，与“特别”的意思无关，不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "跟别的不一样，很突出。", "primary_collocate": null, "pronunciation": "tè bié", "ipa": "tʰɤ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这是一个特别的日子。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè shì yí gè tè bié de rì zi", "sentence_source": "generated"}, {"text": "这家店的菜很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè jiā diàn de cài hěn tè bié", "sentence_source": "generated"}, {"text": "他的想法很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā de xiǎng fǎ hěn tè bié", "sentence_source": "generated"}, {"text": "他有一种特别的气质。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā yǒu yì zhǒng tè bié de qì zhì", "sentence_source": "generated"}, {"text": "这个设计很特别，大家都没见过。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè gè shè jì hěn tè bié dà jiā dōu méi jiàn guo", "sentence_source": "generated"}, {"text": "她的笑容很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā de xiào róng hěn tè bié", "sentence_source": "generated"}, {"text": "这座城市的建筑很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè zuò chéng shì de jiàn zhù hěn tè bié", "sentence_source": "generated"}, {"text": "这个小镇有一个特别的习俗。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè gè xiǎo zhèn yǒu yí gè tè bié de xí sú", "sentence_source": "generated"}, {"text": "他选择的职业很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "tā xuǎn zé de zhí yè hěn tè bié", "sentence_source": "generated"}, {"text": "这只猫的叫声很特别。", "target_word": "特别", "complexity_tier": "T3", "furigana": "zhè zhī māo de jiào shēng hěn tè bié", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词，表示跟别的不一样、很突出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d952261-361f-4475-b6c1-65e9db11d94e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，不能用来形容日子。"}, {"text": "坚硬", "is_correct": false, "explanation": "语义：“坚硬”形容物体质地硬，不能用来形容日子。"}, {"text": "特别", "is_correct": true, "explanation": "“特别”表示跟别的不一样、很突出，与“一个特别的日子”相符。"}, {"text": "大方", "is_correct": false, "explanation": "搭配：“大方”形容人的举止、待人的态度，不能用来形容日子。"}], "explanations": {"咸": "语义：“咸”形容味道，不能用来形容日子。", "坚硬": "语义：“坚硬”形容物体质地硬，不能用来形容日子。", "特别": "“特别”表示跟别的不一样、很突出，与“一个特别的日子”相符。", "大方": "搭配：“大方”形容人的举止、待人的态度，不能用来形容日子。"}, "sentence_index": 0, "correct_answer": "特别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我特别从北京赶来看你。", "explanation": "这里的“特别”是“特地、专门”的意思，表示为某事特意去做，不是“跟别的不一样、很突出”的意思。"}, {"text": "我最喜欢夏天，特别是七月。", "explanation": "这里的“特别是”是“尤其”的意思，用来强调范围，不是“跟别的不一样、很突出”的意思。"}, {"text": "这间房是特别为客人准备的。", "explanation": "这里的“特别”表示“专门为……”，强调用途，不是“很突出、跟别的不一样”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水、眼睛等，不能用来形容建筑。"}, {"text": "甜美", "is_correct": false, "explanation": "语义：“甜美”形容味道、笑容或声音，不能用来形容建筑。"}, {"text": "轻快", "is_correct": false, "explanation": "搭配：“轻快”形容步伐、节奏，不用于描写建筑。"}, {"text": "特别", "is_correct": true, "explanation": "“特别”表示跟别的不一样、很突出，与“建筑很特别”相符。"}], "explanations": {"清澈": "搭配：“清澈”形容水、眼睛等，不能用来形容建筑。", "甜美": "语义：“甜美”形容味道、笑容或声音，不能用来形容建筑。", "轻快": "搭配：“轻快”形容步伐、节奏，不用于描写建筑。", "特别": "“特别”表示跟别的不一样、很突出，与“建筑很特别”相符。"}, "sentence_index": 6, "correct_answer": "特别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅的菜很有特别，很多人慕名而来。", "explanation": "这里应该用〈特色〉。“有特色”是固定说法；“特别”是形容词或副词，不能作名词，说“有特别”不通。"}, {"text": "这种花的特别很明显，叶子又大又厚。", "explanation": "这里应该用〈特征〉。“特别”不能作名词，说明事物显著的特点要用“特征”。"}, {"text": "这部电影的特别很逼真，让人印象深刻。", "explanation": "这里应该用〈特效〉。“特效”是名词，“特别”不能作名词使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他送的礼物有特别。", "corrected_sentence": "他送的礼物很特别。", "error_description": "错误：“特别”是形容词，不能跟动词“有”连用，说“有特别”不通；应用程度副词“很”修饰形容词，说“很特别”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇有很多特别是节日，外地人都想来看看。", "corrected_sentence": "这个小镇有很多特别的节日，外地人都想来看看。", "error_description": "错误：“特别是”是固定的连词，表示“尤其”，不能直接修饰名词“节日”，应说“特别的节日”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e43ab20-e93c-472d-8971-52aaf3267d0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22424, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "勤快", "is_correct": true, "explanation": "勤快与懒是反义词，指肯劳动、爱做事。"}, {"text": "健康", "is_correct": false, "explanation": "与懒不构成反义关系，健康指身体状况良好。"}, {"text": "聪明", "is_correct": false, "explanation": "与懒不构成反义关系，聪明指智力高。"}, {"text": "安静", "is_correct": false, "explanation": "与懒不构成反义关系，安静指没有声音或不吵闹。"}], "correct_answer": "勤快", "explanations": {"勤快": "勤快与懒是反义词，指肯劳动、爱做事。", "健康": "与懒不构成反义关系，健康指身体状况良好。", "聪明": "与懒不构成反义关系，聪明指智力高。", "安静": "与懒不构成反义关系，安静指没有声音或不吵闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
