INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22424, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不想做事。", "primary_collocate": null, "pronunciation": "lǎn", "ipa": "lan˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天我有点懒，不想做饭。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天冷的时候，人就容易变懒。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我特别懒，一整天都躺在沙发上。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天我懒，哪儿也不想去。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天很懒，连电话都不想接。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃饱了就觉得懒，只想睡觉。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "假期里我越来越懒，每天十点才起床。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我懒，不想自己洗衣服，所以去洗衣店。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气一热，大家都懒起来了。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她这几天很懒，什么事都不想做。", "target_word": "懒", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "懒人", "label": "复合"}, {"form": "变懒", "label": "复合"}], "register": "口语", "sense_fingerprint": "一时不想动、不想做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eb8ad67b-239f-4a6f-82cc-ce442b51a334') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22424, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒 lǎn：一时不想动、不想做事，即本条义项。"}, {"text": "蓝", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是蓝色。"}, {"text": "拦", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是阻拦。"}, {"text": "烂", "is_correct": false, "explanation": "làn（第四声）与 lǎn（第三声）声调不同，意思是腐烂。"}, {"text": "朗", "is_correct": false, "explanation": "lǎng 与 lǎn 韵母不同（ang 与 an），意思是明朗。"}], "explanations": {"懒": "懒 lǎn：一时不想动、不想做事，即本条义项。", "蓝": "lán（第二声）与 lǎn（第三声）声调不同，意思是蓝色。", "拦": "lán（第二声）与 lǎn（第三声）声调不同，意思是阻拦。", "烂": "làn（第四声）与 lǎn（第三声）声调不同，意思是腐烂。", "朗": "lǎng 与 lǎn 韵母不同（ang 与 an），意思是明朗。"}, "sentence_index": null, "correct_answer": "懒"}, "level_3": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒指一时不想动。句意是今天有点不想动，所以不想做饭，只有“懒”符合。"}, {"text": "勤快", "is_correct": false, "explanation": "语义：“有点勤快，不想做饭”前后矛盾。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”指待人或做事积极，与“不想做饭”相冲突。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”描写身高，与不想做饭无关。"}], "explanations": {"懒": "懒指一时不想动。句意是今天有点不想动，所以不想做饭，只有“懒”符合。", "勤快": "语义：“有点勤快，不想做饭”前后矛盾。", "热情": "语义：“热情”指待人或做事积极，与“不想做饭”相冲突。", "高": "体貌：“高”描写身高，与不想做饭无关。"}, "sentence_index": 0, "correct_answer": "懒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的成绩很懒，每次都考不及格。", "explanation": "这里应该用〈不理想〉。懒形容人不想做事，不能用来评价成绩。"}, {"text": "他听了这话很懒，脸都红了。", "explanation": "这里应该用〈生气〉。懒指不愿动，不能用来描述情绪的激动。"}, {"text": "这本词典很懒，我怎么也查不到生词。", "explanation": "这里应该用〈不全〉。懒只形容人，不用来说词典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22424, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒 lǎn：一时不想动、不想做事，即本条义项。"}, {"text": "栏", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是栏杆。"}, {"text": "篮", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是篮子。"}, {"text": "兰", "is_correct": false, "explanation": "lán（第二声）与 lǎn（第三声）声调不同，意思是兰花。"}], "explanations": {"懒": "懒 lǎn：一时不想动、不想做事，即本条义项。", "栏": "lán（第二声）与 lǎn（第三声）声调不同，意思是栏杆。", "篮": "lán（第二声）与 lǎn（第三声）声调不同，意思是篮子。", "兰": "lán（第二声）与 lǎn（第三声）声调不同，意思是兰花。"}, "sentence_index": null, "correct_answer": "懒"}, "level_3": {"options": [{"text": "懒", "is_correct": true, "explanation": "懒指一时不想动。句意是假期里越来越不想动，所以每天十点才起床，只有“懒”符合。"}, {"text": "勤快", "is_correct": false, "explanation": "语义：“越来越勤快”与“每天十点才起床”相冲突。"}, {"text": "早", "is_correct": false, "explanation": "语义：“越来越早”与“每天十点才起床”相矛盾。"}, {"text": "勤奋", "is_correct": false, "explanation": "语义：“越来越勤奋”与“每天十点才起床”相矛盾。"}], "explanations": {"懒": "懒指一时不想动。句意是假期里越来越不想动，所以每天十点才起床，只有“懒”符合。", "勤快": "语义：“越来越勤快”与“每天十点才起床”相冲突。", "早": "语义：“越来越早”与“每天十点才起床”相矛盾。", "勤奋": "语义：“越来越勤奋”与“每天十点才起床”相矛盾。"}, "sentence_index": 6, "correct_answer": "懒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被误会后很懒，急得直跺脚。", "explanation": "这里应该用〈着急〉。懒指不想动，不用来描述焦急的心情。"}, {"text": "这家店的生意很懒，门口没什么人。", "explanation": "这里应该用〈冷清〉。懒只形容人或动物，不用来说生意的状况。"}, {"text": "听到这个消息，他很懒地跳了起来。", "explanation": "这里应该用〈激动〉。懒指不愿动，与“跳起来”的激动状态矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最近懒变了，不想出门。", "corrected_sentence": "我最近变懒了，不想出门。", "error_description": "“变”与“懒”的语序错了。应说“变懒”，“懒变”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我小时候懒很，后来才改了。", "corrected_sentence": "我小时候很懒，后来才改了。", "error_description": "程度副词“很”应放在形容词“懒”之前，“懒很”语序错误，应为“很懒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3448ed1d-9f75-4fae-beb3-c278fb39073e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
