INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22426, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人说话，互相明白对方的意思。", "primary_collocate": null, "pronunciation": "gōu tōng", "ipa": "kɤu̯˥ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我和老板每天都沟通工作。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母要多和孩子沟通。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沟通了很久，问题解决了。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有问题就要及时沟通。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太会和同事沟通，常常产生误会。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理想先跟客户沟通一下价格。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用电话沟通，比发邮件快。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人只有沟通，才能互相明白。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和家长沟通了学生的学习情况。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间多沟通，关系会更好。", "target_word": "沟通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沟通了", "label": "体标"}, {"form": "沟通过", "label": "体标"}, {"form": "沟通能力", "label": "复合"}, {"form": "沟通方式", "label": "复合"}], "register": "中性", "sense_fingerprint": "人与人交流想法，使双方互相理解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“吃工作”说不通，与句中的交流语境不符。"}, {"text": "沟通", "is_correct": true, "explanation": "正确。沟通指双方交流想法、互相理解，与“每天都和老板交流工作”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，“唱工作”不成立，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，后面不能直接带宾语“工作”。"}], "explanations": {"吃": "语义：“吃”的对象是食物，“吃工作”说不通，与句中的交流语境不符。", "沟通": "正确。沟通指双方交流想法、互相理解，与“每天都和老板交流工作”的语境相符。", "唱": "语义：“唱”的对象是歌曲，“唱工作”不成立，句子不通。", "睡": "配价：“睡”是不及物动词，后面不能直接带宾语“工作”。"}, "sentence_index": 0, "correct_answer": "沟通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在店里沟通了三件衣服，最后买了一件。", "explanation": "这里应该用〈挑选〉。沟通指双方交流想法，不能用来表示从几件东西中选出一件。"}, {"text": "我用手机沟通了一张照片。", "explanation": "这里应该用〈发送〉。沟通指双方交流想法，不能用来表示把照片传给别人。"}, {"text": "我们沟通了名片。", "explanation": "这里应该用〈交换〉。沟通是交流想法，不能用来表示互换名片这类实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间或卫生，不能用“电话”作工具，“用电话打扫”不成立。"}, {"text": "沟通", "is_correct": true, "explanation": "正确。电话用于交流，“沟通”指双方交流，与“比发邮件快”的比较相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“用电话”没有工具关系，句子说不通。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”不能靠电话来完成，与“比发邮件快”的语境不合。"}], "explanations": {"打扫": "搭配：“打扫”的对象是房间或卫生，不能用“电话”作工具，“用电话打扫”不成立。", "沟通": "正确。电话用于交流，“沟通”指双方交流，与“比发邮件快”的比较相符。", "睡觉": "语义：“睡觉”与“用电话”没有工具关系，句子说不通。", "吃饭": "语义：“吃饭”不能靠电话来完成，与“比发邮件快”的语境不合。"}, "sentence_index": 6, "correct_answer": "沟通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司把货沟通给了客户。", "explanation": "这里应该用〈交付〉。沟通是双方交流想法，不能用来表示把货物交给对方。"}, {"text": "我把这封信沟通给了妈妈。", "explanation": "这里应该用〈寄〉。沟通说的是交流意见，不能用来表示把信件寄出。"}, {"text": "请把文件沟通给经理。", "explanation": "这里应该用〈转交〉。沟通的对象是想法，不是文件，不能说把文件“沟通”给别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天同事沟通了一个小时。", "corrected_sentence": "我昨天跟同事沟通了一个小时。", "error_description": "错误：“沟通”前漏掉了介词“跟”。沟通的对象要用“跟”或“和”引出，应说“跟同事沟通”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们跟领导沟通很得好。", "corrected_sentence": "我们跟领导沟通得很好。", "error_description": "错误：程度副词“很”放错了位置，不能放在补语标记“得”的前面。应说“沟通得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22428, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更差", "is_correct": true, "explanation": "反义：「差」与「好」相对，「更差」表示比原来或别的更不好，与「更好」意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "「漂亮」形容外貌好看，与「更好」的优劣比较不构成反义关系。"}, {"text": "便宜", "is_correct": false, "explanation": "「便宜」指价格低，与「更好」没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "「清楚」指明白、不模糊，与「更好」不是反义词。"}], "correct_answer": "更差", "explanations": {"更差": "反义：「差」与「好」相对，「更差」表示比原来或别的更不好，与「更好」意思相反。", "漂亮": "「漂亮」形容外貌好看，与「更好」的优劣比较不构成反义关系。", "便宜": "「便宜」指价格低，与「更好」没有反义关系。", "清楚": "「清楚」指明白、不模糊，与「更好」不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22428, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "更坏", "is_correct": true, "explanation": "反义：「坏」与「好」相对，「更坏」表示比原来更不好，与「更好」意思相反。"}, {"text": "难看", "is_correct": false, "explanation": "「难看」形容外貌不美，与「更好」不构成反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "「高兴」指心情愉快，与「更好」没有反义关系。"}, {"text": "普通", "is_correct": false, "explanation": "「普通」指平常、一般，与「更好」不是反义词。"}], "correct_answer": "更坏", "explanations": {"更坏": "反义：「坏」与「好」相对，「更坏」表示比原来更不好，与「更好」意思相反。", "难看": "「难看」形容外貌不美，与「更好」不构成反义关系。", "高兴": "「高兴」指心情愉快，与「更好」没有反义关系。", "普通": "「普通」指平常、一般，与「更好」不是反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22428, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "比原来还要好。", "primary_collocate": null, "pronunciation": "gèng hǎo", "ipa": "kɤŋ˥˩ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个办法比那个办法更好。", "target_word": "更好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的天气比昨天更好。", "target_word": "更好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我希望明年的工作会更好。", "target_word": "更好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语比去年更好了。", "target_word": "更好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一起努力，生活会变得更好。", "target_word": "更好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的想法很好，但他的想法更好。", "target_word": "更好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想找一个更好的工作。", "target_word": "更好", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明考了九十分，小红考得更好。", "target_word": "更好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子很大，但那个房子的位置更好。", "target_word": "更好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多练习，你的发音会更好。", "target_word": "更好", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "更好的", "label": "的字结构"}, {"form": "更好地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "比原来或比别的还要好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更好", "is_correct": true, "explanation": "正确：「更好」表示比较之下质量更高，与「比那个办法」相合。"}, {"text": "更大", "is_correct": false, "explanation": "搭配：「办法」说的是好坏和效果，不能用「大」来比较。"}, {"text": "更甜", "is_correct": false, "explanation": "搭配：「甜」只形容食物或味道，不能形容办法。"}, {"text": "更生气", "is_correct": false, "explanation": "语义：「生气」是人的情绪，办法不会生气。"}], "explanations": {"更好": "正确：「更好」表示比较之下质量更高，与「比那个办法」相合。", "更大": "搭配：「办法」说的是好坏和效果，不能用「大」来比较。", "更甜": "搭配：「甜」只形容食物或味道，不能形容办法。", "更生气": "语义：「生气」是人的情绪，办法不会生气。"}, "sentence_index": 0, "correct_answer": "更好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里的人数比去年更好了。", "explanation": "这里应该用〈更多〉。「更好」说的是质量，人数的变化要用多少来比较。"}, {"text": "今天的雨比昨天更好了。", "explanation": "这里应该用〈更大〉。「更好」说的是质量高低，雨量的多少要用「更大」。"}, {"text": "他的身高比去年更好了。", "explanation": "这里应该用〈更高〉。「更好」说的是质量，身高的变化要用高矮来比较。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更好", "is_correct": true, "explanation": "正确：「更好」修饰「工作」，表示质量更高的工作，句子通顺。"}, {"text": "更胖", "is_correct": false, "explanation": "语义：「胖」指人或动物的体形，工作没有体形。"}, {"text": "更湿", "is_correct": false, "explanation": "语义：「湿」指物体含有水分，工作不会被弄湿。"}, {"text": "更漂亮", "is_correct": false, "explanation": "搭配：「漂亮」形容外貌，一般不用来形容工作。"}], "explanations": {"更好": "正确：「更好」修饰「工作」，表示质量更高的工作，句子通顺。", "更胖": "语义：「胖」指人或动物的体形，工作没有体形。", "更湿": "语义：「湿」指物体含有水分，工作不会被弄湿。", "更漂亮": "搭配：「漂亮」形容外貌，一般不用来形容工作。"}, "sentence_index": 6, "correct_answer": "更好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的时长比原来更好了。", "explanation": "这里应该用〈更长〉。「更好」说的是质量高低，时间的长短要用「更长」。"}, {"text": "他的个子比弟弟更好。", "explanation": "这里应该用〈更高〉。「更好」说的是质量高低，个子的高矮要用「更高」。"}, {"text": "这桶水的重量比那桶更好了。", "explanation": "这里应该用〈更重〉。「更好」说的是质量高低，重量要用「更重」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种方法比以前更更好。", "corrected_sentence": "这种方法比以前更好。", "error_description": "错误：「更更好」重复了「更」；正确：「更好」，表示比较只用一个「更」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年的计划比去年更好地。", "corrected_sentence": "今年的计划比去年更好。", "error_description": "错误：「更好地」多加了「地」，「地」是状语标记，「更好」作谓语时不带「地」；正确：「比去年更好」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
