INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22430, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "知道某人或某事的情况，有所认识。", "primary_collocate": null, "pronunciation": "liǎo jiě", "ipa": "ljɑʊ˨˩˦ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我不太了解这个城市。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来中国以前，我对中国不了解。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想了解你的学习情况。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们认识很久，我很了解他。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你了解这件事吗？", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机以前，先了解一下价格。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "通过这本书，我了解了很多历史。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很了解中国菜。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想多了解一些你的家人。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母了解孩子的想法。", "target_word": "了解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不了解", "label": "否定"}, {"form": "了解了", "label": "体标"}, {"form": "了解过", "label": "体标"}], "register": "中性", "sense_fingerprint": "清楚地知道某人或某事的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55f2e96c-13a5-42cd-ab9f-f21f3b3466c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：「修理」指修复器物，不能用来说“不太修理这个城市”"}, {"text": "了解", "is_correct": true, "explanation": "正确。了解指知道某事的情况，与“不太”搭配，说明对城市不熟悉"}, {"text": "建设", "is_correct": false, "explanation": "语义：「建设」是动手建造，“我”不太建设城市说不通"}, {"text": "占领", "is_correct": false, "explanation": "语义：「占领」指用武力控制，与“不太”和城市的语境不符"}], "explanations": {"修理": "搭配：「修理」指修复器物，不能用来说“不太修理这个城市”", "了解": "正确。了解指知道某事的情况，与“不太”搭配，说明对城市不熟悉", "建设": "语义：「建设」是动手建造，“我”不太建设城市说不通", "占领": "语义：「占领」指用武力控制，与“不太”和城市的语境不符"}, "sentence_index": 0, "correct_answer": "了解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在街上了解了老同学，直到他先打招呼我才想起来。", "explanation": "这里应该用〈认出〉。了解指对人或情况的认识，不用来表示辨认出某人"}, {"text": "我在操场上了解了他的背影，就走过去打招呼。", "explanation": "这里应该用〈看见〉。了解指对人或情况的认识，不用来表示视觉上的看到"}, {"text": "我在桌子下面了解了一支笔。", "explanation": "这里应该用〈发现〉。了解用于人或情况，不用于找到一件东西"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忘记", "is_correct": false, "explanation": "语义：「忘记」与“通过这本书”的语境相矛盾，书应该让人获得知识"}, {"text": "了解", "is_correct": true, "explanation": "正确。了解指知道历史的情况，与“通过这本书”的语境相符"}, {"text": "创造", "is_correct": false, "explanation": "语义：「创造」指做出新的事物，与“通过这本书”获得知识的语境不符"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：「摧毁」指毁坏，与“通过这本书”获得知识的语境相矛盾"}], "explanations": {"忘记": "语义：「忘记」与“通过这本书”的语境相矛盾，书应该让人获得知识", "了解": "正确。了解指知道历史的情况，与“通过这本书”的语境相符", "创造": "语义：「创造」指做出新的事物，与“通过这本书”获得知识的语境不符", "摧毁": "语义：「摧毁」指毁坏，与“通过这本书”获得知识的语境相矛盾"}, "sentence_index": 6, "correct_answer": "了解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在门外了解了哭声。", "explanation": "这里应该用〈听到〉。了解指对情况的认识，不用来表示耳朵听见声音"}, {"text": "厨房里了解了饭香。", "explanation": "这里应该用〈闻到〉。了解不用来表示通过气味感知事物"}, {"text": "他在河边了解了一条鱼，把它拉了上来。", "explanation": "这里应该用〈钓到〉。了解指对情况的认识，不用来表示捕到东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这个行业了解很清楚。", "corrected_sentence": "他对这个行业了解得很清楚。", "error_description": "“了解很清楚”缺少补语标记“得”，应为“了解得很清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没了解了这个新产品。", "corrected_sentence": "我还没了解过这个新产品。", "error_description": "“没”后的经历体应用“过”，不能用“了”。应为“还没了解过这个新产品”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
