INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生活就是每天做的事情。", "primary_collocate": null, "pronunciation": "shēng huó", "ipa": "ʂəŋ˥ xuo˧˥", "syllable_count": 2, "sentences": [{"text": "早上跑步、晚上看书是我每天的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的生活很简单：上班、吃饭、睡觉。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天做饭、洗衣服就是妈妈的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你每天的生活是什么样的？", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每天的生活都写在日记里。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的生活就是上课和做作业。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来到新城市，我每天的生活有了变化。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们每天的生活很有意思。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我们说说你一天的生活。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退休后，奶奶每天的生活很有规律。", "target_word": "生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日常生活", "label": "复合"}], "register": "中性", "sense_fingerprint": "每天做的事情，日常的作息和安排", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7aa7a4f-1236-4805-b7d4-46fc3a94a1f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：指每天的日常作息和做的事情，与“跑步、看书”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人每天做的事情，“每天的天气”与“跑步、看书”不能并列。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指长相，不是每天做的事情，与跑步、看书这类活动不能并列。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话是通讯工具，不是每天做的事情，句子说的是日常活动。"}], "explanations": {"生活": "正确：指每天的日常作息和做的事情，与“跑步、看书”的语境相符。", "天气": "语义：天气不是人每天做的事情，“每天的天气”与“跑步、看书”不能并列。", "外貌": "语义：外貌指长相，不是每天做的事情，与跑步、看书这类活动不能并列。", "电话": "语义：电话是通讯工具，不是每天做的事情，句子说的是日常活动。"}, "sentence_index": 0, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的生活很好。", "explanation": "这里应用〈生意〉。“生活”指人过日子，不指店铺的经营状况，店铺经营得好应说〈生意〉。"}, {"text": "这台旧冰箱的生活已经很长了。", "explanation": "这里应用〈寿命〉。“生活”指人的日常过日子，不指物品的使用年限，应说〈寿命〉。"}, {"text": "这个月我的生活比上个月多了三千块。", "explanation": "这里应用〈收入〉。“生活”不表示金钱收入，收入的增减应说〈收入〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生活", "is_correct": true, "explanation": "正确：指日常的生活状况，与“来到新城市，有了变化”的语境相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不会每天变化，“每天的年龄”与句意矛盾。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是受教育的经历记录，不会随每天的变化而改变。"}, {"text": "星座", "is_correct": false, "explanation": "语义：星座是出生时就确定的，不会随时间变化，与“来到新城市”后的变化不合。"}], "explanations": {"生活": "正确：指日常的生活状况，与“来到新城市，有了变化”的语境相符。", "年龄": "语义：年龄不会每天变化，“每天的年龄”与句意矛盾。", "学历": "语义：学历是受教育的经历记录，不会随每天的变化而改变。", "星座": "语义：星座是出生时就确定的，不会随时间变化，与“来到新城市”后的变化不合。"}, "sentence_index": 6, "correct_answer": "生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶每天的生活很好吃。", "explanation": "这里应用〈饭菜〉。“生活”不指饭菜，说味道好应用〈饭菜〉。"}, {"text": "奶奶每天早上都生活一杯牛奶。", "explanation": "这里应用〈喝〉。“生活”是名词，不能作动词，喝牛奶应说“喝一杯牛奶”。"}, {"text": "奶奶每天在公园生活两个小时。", "explanation": "这里应用〈锻炼〉。“生活”是过日子，不能表示在某地做某事一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他过着一根平静的生活。", "corrected_sentence": "他过着一种平静的生活。", "error_description": "量词错误：“生活”不能用“根”，“根”用于细长的东西。正确形式：一种平静的生活。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的生活过很幸福。", "corrected_sentence": "我们的生活过得很幸福。", "error_description": "补语错误：“过”与补语“很幸福”之间应加“得”。正确形式：过得很幸福。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72b556dc-4de1-4437-9d4d-8866d5e6c6d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22436, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22436, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22436, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大家在一起，不吵架，互相帮助。", "primary_collocate": null, "pronunciation": "hé xié", "ipa": "xɤ˧˥ ɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "他们一家人生活得很和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的关系很和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的邻居相处得很和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望班里的气氛更和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻吵架很少，家里很和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要有一个和谐的家。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司里大家互相帮助，相处得很和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和谐的环境让人心情很好。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国的关系一直很和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家不吵架，班里的气氛十分和谐。", "target_word": "和谐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不和谐", "label": "否定"}, {"form": "和谐地", "label": "状语形式"}, {"form": "和谐社会", "label": "复合"}], "register": "中性", "sense_fingerprint": "和谐：人与人相处融洽，关系好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和谐", "is_correct": true, "explanation": "和谐指关系融洽，符合「他们一家人生活得很和谐」。"}, {"text": "笔直", "is_correct": false, "explanation": "语义：「笔直」形容形状，不能用来形容生活的状态。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」形容外形，不能说「生活得很高大」。"}, {"text": "尖锐", "is_correct": false, "explanation": "搭配：「尖锐」形容言辞或棱角，「生活得很尖锐」搭配不当。"}], "explanations": {"和谐": "和谐指关系融洽，符合「他们一家人生活得很和谐」。", "笔直": "语义：「笔直」形容形状，不能用来形容生活的状态。", "高大": "体貌：「高大」形容外形，不能说「生活得很高大」。", "尖锐": "搭配：「尖锐」形容言辞或棱角，「生活得很尖锐」搭配不当。"}, "sentence_index": 0, "correct_answer": "和谐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画的价格很和谐。", "explanation": "这里应该用〈合理〉。和谐指事物之间协调、融洽，不用来评价价格高低。"}, {"text": "这次比赛的成绩很和谐。", "explanation": "这里应该用〈优秀〉。和谐指各方协调、融洽，不用来评价成绩的好坏。"}, {"text": "他们一家人吵得很和谐。", "explanation": "这里应该用〈热闹〉。和谐指大家相处融洽、没有矛盾，不能用来形容喧闹的场面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和谐", "is_correct": true, "explanation": "和谐指相处融洽，符合「相处得很和谐」。"}, {"text": "亮晶晶", "is_correct": false, "explanation": "体貌：「亮晶晶」形容光线和外观，不能形容相处的状态。"}, {"text": "方正", "is_correct": false, "explanation": "体貌：「方正」形容形状，不能用来形容相处。"}, {"text": "沉甸甸", "is_correct": false, "explanation": "语义：「沉甸甸」形容分量，相处的状态不能有重量。"}], "explanations": {"和谐": "和谐指相处融洽，符合「相处得很和谐」。", "亮晶晶": "体貌：「亮晶晶」形容光线和外观，不能形容相处的状态。", "方正": "体貌：「方正」形容形状，不能用来形容相处。", "沉甸甸": "语义：「沉甸甸」形容分量，相处的状态不能有重量。"}, "sentence_index": 6, "correct_answer": "和谐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很和谐。", "explanation": "这里应该用〈舒服〉。和谐指人与人相处融洽，不用来形容椅子坐着是否舒服。"}, {"text": "他跑得很和谐。", "explanation": "这里应该用〈快〉。和谐不用来形容跑步的快慢，应该说「跑得很快」。"}, {"text": "火车开得很和谐。", "explanation": "这里应该用〈平稳〉。和谐不用于描述车辆的行驶状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个人的关系没和谐。", "corrected_sentence": "这两个人的关系不和谐。", "error_description": "错误形式是「没和谐」，正确形式是「不和谐」。形容词前的否定要用「不」，不用「没」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的班级非常很和谐。", "corrected_sentence": "我们的班级很和谐。", "error_description": "错误：“很”与“非常”重复修饰“和谐”，两个程度副词不能连用。正确：只用“很和谐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
