INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22438, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "意思是和别的一样。", "primary_collocate": null, "pronunciation": "tóng yàng", "ipa": "tʰʊŋ˧˥ jaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "你喜欢这首歌，我同样喜欢。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很努力，他的朋友同样很努力。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人需要休息，孩子同样需要休息。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对你重要，对我同样重要。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王考了第一名，小李同样考得很好。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们同样来自北京，所以常常见面。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中文很难，英文同样不容易。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想早点回家，大家同样想早点回家。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红茶好喝，绿茶同样好喝。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想去，我同样很想去，可是没有时间。", "target_word": "同样", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词，表示和前面说的情况一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 4 words above tier T1 (max 2): 红茶 (Zipf 3.37), 好喝 (Zipf 3.59), 绿茶 (Zipf 3.43), 好喝 (Zipf 3.59)']::text[], '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "却", "is_correct": false, "explanation": "语义：“却”表示转折，句中前后并没有相反的情况，用“却”句意不通。"}, {"text": "同样", "is_correct": true, "explanation": "同样表示“也一样”，说明我和你一样喜欢这首歌。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，句中并没有令人意外的情况。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示立即发生，句意变成“立刻喜欢”，与“我也一样喜欢”不符。"}], "explanations": {"却": "语义：“却”表示转折，句中前后并没有相反的情况，用“却”句意不通。", "同样": "同样表示“也一样”，说明我和你一样喜欢这首歌。", "竟然": "语义：“竟然”表示出乎意料，句中并没有令人意外的情况。", "马上": "语义：“马上”表示立即发生，句意变成“立刻喜欢”，与“我也一样喜欢”不符。"}, "sentence_index": 0, "correct_answer": "同样"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他比我高，我们同样高。", "explanation": "这里应该用〈不一样〉。“同样”表示相同，而前一句说他比我高，这里应说“我们的身高不一样”。"}, {"text": "我喜欢苹果，他同样讨厌苹果。", "explanation": "这里应该用〈反而〉。“同样”表示态度相同，这里前后态度相反，应说“他反而讨厌苹果”。"}, {"text": "小明考了九十分，小红同样考了六十分。", "explanation": "这里应该用〈只〉。“同样”表示数量相等，而九十分与六十分不等，应说“小红只考了六十分”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "刚", "is_correct": false, "explanation": "搭配：“刚”表示时间刚过，不能修饰“不容易”这类性质。"}, {"text": "同样", "is_correct": true, "explanation": "同样表示“和前面一样”，说明英文也和中文一样不容易。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：“立刻”表示马上发生，与“不容易”这种性质不搭配。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示庆幸，句中并没有值得庆幸的情况。"}], "explanations": {"刚": "搭配：“刚”表示时间刚过，不能修饰“不容易”这类性质。", "同样": "同样表示“和前面一样”，说明英文也和中文一样不容易。", "立刻": "搭配：“立刻”表示马上发生，与“不容易”这种性质不搭配。", "幸亏": "语义：“幸亏”表示庆幸，句中并没有值得庆幸的情况。"}, "sentence_index": 6, "correct_answer": "同样"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛他拿了冠军，我同样拿了亚军。", "explanation": "这里应该用〈只〉。“同样”表示相同，而冠军与亚军名次不同，应说“我只拿了亚军”。"}, {"text": "我已经吃过了，他同样还没吃。", "explanation": "这里应该用〈倒〉。“同样”表示相同，而前一句说我已经吃过，这里应说“他倒还没吃”，表示与前面相反的情况。"}, {"text": "我的弟弟很高，我同样很矮。", "explanation": "这里应该用〈却〉。“同样”表示相同，而“弟弟很高”与“我很矮”相反，应说“我却很矮”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们同样的喜欢这部电影。", "corrected_sentence": "我们同样喜欢这部电影。", "error_description": "错误形式：“我们同样的喜欢这部电影”；正确形式：“我们同样喜欢这部电影”。“同样”作状语修饰动词时不带“的”，“同样的”只用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们很同样喜欢那个老师。", "corrected_sentence": "孩子们同样喜欢那个老师。", "error_description": "错误形式：“很同样喜欢那个老师”；正确形式：“同样喜欢那个老师”。“同样”是副词，前面不能加程度副词“很”，应直接修饰动词“喜欢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
