INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22442, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22442, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就是只有这个，没有别的。", "primary_collocate": null, "pronunciation": "jǐn jǐn", "ipa": "tɕin˨˩˦ tɕin˨˩˦", "syllable_count": 2, "sentences": [{"text": "他仅仅花了十分钟就做完了。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这仅仅是一个小问题。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我仅仅想休息一下。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里仅仅有三个学生。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仅仅一天，他就学会了这首歌。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他仅仅说了一句话，就走了。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功不是仅仅靠运气。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我仅仅见过他一次。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格仅仅是原因之一。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店仅仅卖茶。", "target_word": "仅仅", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不仅仅", "label": "复合"}], "register": "书面", "sense_fingerprint": "表示范围小、数量少，只有这些", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55f2e96c-13a5-42cd-ab9f-f21f3b3466c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22442, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仅仅", "is_correct": true, "explanation": "「仅仅」表示只花了十分钟，范围小，符合句意。"}, {"text": "正在", "is_correct": false, "explanation": "语义：「正在」表示动作进行中，与「花了十分钟就做完了」的已完成义矛盾。"}, {"text": "一直", "is_correct": false, "explanation": "语义：「一直」表示持续不断，与「十分钟内做完」的短时完成矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：「从来」多与否定或习惯连用，不能修饰已完成的具体动作。"}], "explanations": {"仅仅": "「仅仅」表示只花了十分钟，范围小，符合句意。", "正在": "语义：「正在」表示动作进行中，与「花了十分钟就做完了」的已完成义矛盾。", "一直": "语义：「一直」表示持续不断，与「十分钟内做完」的短时完成矛盾。", "从来": "搭配：「从来」多与否定或习惯连用，不能修饰已完成的具体动作。"}, "sentence_index": 0, "correct_answer": "仅仅"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仅仅会说英语，还会说法语。", "explanation": "这里应该用〈不仅〉。「仅仅」表示只有这些，与后面的「还」表示递进相矛盾。"}, {"text": "这本书很便宜，仅仅质量不太好。", "explanation": "这里表示转折，应该用〈只是〉。「仅仅」是副词，只限定范围，不能表示转折。"}, {"text": "这家餐厅仅仅菜好吃，而且环境也很好。", "explanation": "这里应该用〈不但〉。「仅仅」表示只有，与后面「而且环境也很好」的递进相冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22442, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仅仅", "is_correct": true, "explanation": "「仅仅」表示只靠运气，限定范围，符合「不是……靠运气」的语境。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」表示时间上不久以前，与「成功靠运气」这一普遍判断不符。"}, {"text": "更加", "is_correct": false, "explanation": "语义：「更加」需要比较对象，句中没有比较，不成立。"}, {"text": "正在", "is_correct": false, "explanation": "语义：「正在」表示动作进行中，「成功不是正在靠运气」说不通。"}], "explanations": {"仅仅": "「仅仅」表示只靠运气，限定范围，符合「不是……靠运气」的语境。", "刚刚": "语义：「刚刚」表示时间上不久以前，与「成功靠运气」这一普遍判断不符。", "更加": "语义：「更加」需要比较对象，句中没有比较，不成立。", "正在": "语义：「正在」表示动作进行中，「成功不是正在靠运气」说不通。"}, "sentence_index": 6, "correct_answer": "仅仅"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事仅仅连老师都不知道。", "explanation": "这里表示「甚至」的强调，应该用〈甚至〉。「仅仅」只限定范围，不能表示强调。"}, {"text": "这家店的员工仅仅都会茶道。", "explanation": "这里表示全部，应该用〈全〉。「仅仅」表示只有，与「都」的全部含义矛盾。"}, {"text": "我们十点仅仅出发。", "explanation": "这里表示时间晚，应该用〈才〉。「仅仅」只限定范围，不能表示「直到」的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22442, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我很仅仅带了一本书去学校。", "corrected_sentence": "我仅仅带了一本书去学校。", "error_description": "错误：「仅仅」是限定范围的副词，不能被程度副词「很」修饰，应去掉「很」。正确：「我仅仅带了一本书去学校。」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22442, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不仅仅吃了两口饭，就放下了筷子。", "corrected_sentence": "他仅仅吃了两口饭，就放下了筷子。", "error_description": "错误：「不仅仅」表示「不只」，与表示「只有」的「仅仅」意思相反。正确：这里表示只吃了两口，应去掉「不」，用「仅仅」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c0a3317-29a3-4d7b-8860-b76cda9be07f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
