INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22444, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22444, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示可能，但不肯定。", "primary_collocate": null, "pronunciation": "yě xǔ", "ipa": "jɛ˨˩ ɕy˨˩", "syllable_count": 2, "sentences": [{"text": "天阴了，也许一会儿会下雨。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没接电话，也许在开会。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "也许明天我就有时间了。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你也许不认识他，但他认识你。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事也许没有你想的那么难。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我也许会去，现在还不能肯定。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天没来，也许生病了。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "也许你说得对，我再想想。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，他也许要晚到一会儿。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店今天也许不开门。", "target_word": "也许", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "也許", "label": "繁体"}], "register": "中性", "sense_fingerprint": "副词，表示推测，可能是这样但不能肯定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22444, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示始终如此，与“一会儿”这种短时间冲突，句意不通。"}, {"text": "也许", "is_correct": true, "explanation": "也许表示推测，可能但不肯定，与“天阴了”这一迹象相符。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已经发生，与“一会儿会下雨”的将来情况冲突。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示不久前发生，与“一会儿会下雨”的将来情况冲突。"}], "explanations": {"永远": "语义：“永远”表示始终如此，与“一会儿”这种短时间冲突，句意不通。", "也许": "也许表示推测，可能但不肯定，与“天阴了”这一迹象相符。", "已经": "语义：“已经”表示已经发生，与“一会儿会下雨”的将来情况冲突。", "刚刚": "语义：“刚刚”表示不久前发生，与“一会儿会下雨”的将来情况冲突。"}, "sentence_index": 0, "correct_answer": "也许"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我亲眼看见他走进了教室，他也许已经到了。", "explanation": "这里应该用〈一定〉。说话人亲眼看见他已经进了教室，事实确定，应说“他一定已经到了”；“也许”表示不确定，与语境矛盾。"}, {"text": "我已经买好了明天去北京的火车票，我也许明天去北京。", "explanation": "这里应该用〈肯定〉。火车票已经买好，行程已定，应说“我肯定明天去北京”；“也许”表示不确定，与语境矛盾。"}, {"text": "我刚数过，教室里也许有三十个人。", "explanation": "这里应该用〈正好〉。说话人刚数过人数，结果确定，应说“教室里正好有三十个人”；“也许”表示推测，与已数清的结果矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22444, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示很少发生，与“今天没来”这一次性的情况冲突，句意不通。"}, {"text": "也许", "is_correct": true, "explanation": "也许表示推测，可能但不肯定，与“没来”这一迹象相符，说明可能是生病了。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行中，不能修饰“没来”这种否定的动作。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰“没来”这种否定的动作，“很没来”不成立。"}], "explanations": {"偶尔": "语义：“偶尔”表示很少发生，与“今天没来”这一次性的情况冲突，句意不通。", "也许": "也许表示推测，可能但不肯定，与“没来”这一迹象相符，说明可能是生病了。", "正在": "语法：“正在”表示动作进行中，不能修饰“没来”这种否定的动作。", "很": "语法：“很”是程度副词，不能修饰“没来”这种否定的动作，“很没来”不成立。"}, "sentence_index": 6, "correct_answer": "也许"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你也许帮我拿一下书。", "explanation": "这里应该用〈务必〉。也许只表示推测，不能用于请求别人做事；请求或要求别人时应说“务必”。"}, {"text": "我向你保证，我也许明天还你钱。", "explanation": "这里应该用〈必定〉。“保证”是确定的承诺，不能用“也许”表示不确定，应说“我必定明天还你钱”。"}, {"text": "水在一百度时会沸腾，所以它也许会沸腾。", "explanation": "这里应该用〈必然〉。沸腾是已知的自然规律，结果确定，应说“它必然会沸腾”，不能用“也许”表示推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22444, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我下午很也许会去超市。", "corrected_sentence": "我下午也许会去超市。", "error_description": "错误形式：“很也许会去超市”；正确形式：“也许会去超市”。也许是副词，表示推测，前面不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22444, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天没来上班，也许的感冒了。", "corrected_sentence": "他昨天没来上班，也许感冒了。", "error_description": "错误形式：“也许的感冒了”；正确形式：“也许感冒了”。也许是副词，后面不能加“的”，应直接修饰动词“感冒”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
