INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想着好事快点儿来。", "primary_collocate": null, "pronunciation": "qī dài", "ipa": "tɕʰi˥ tai˥˩", "syllable_count": 2, "sentences": [{"text": "小朋友期待着明天去公园玩。", "target_word": "期待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我期待周末快点儿到。", "target_word": "期待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她期待收到爸爸寄来的礼物。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们都期待春天快点儿来。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他期待着考试的好成绩。", "target_word": "期待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最期待放假了。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每天晚上，孩子期待着妈妈讲故事。", "target_word": "期待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你期待过下雪吗？", "target_word": "期待", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很期待见到你。", "target_word": "期待", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大家期待已久的新书终于出来了。", "target_word": "期待", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "期待着", "label": "持续体"}, {"form": "期待过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "心里盼着好事快点儿到来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39273322-a49f-4295-81e9-e380ddef2d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "期待", "is_correct": true, "explanation": "期待着表示心里盼着明天的事快点儿到来，与句意相符。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指想起过去的事，不能用于尚未到来的“明天”。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”针对已经过去的人或事，与“明天去公园玩”这一未来的安排相冲突。"}, {"text": "整理", "is_correct": false, "explanation": "搭配：“整理”一般接物品或事务，不能与“去公园玩”这类活动搭配。"}], "explanations": {"期待": "期待着表示心里盼着明天的事快点儿到来，与句意相符。", "回忆": "语义：“回忆”指想起过去的事，不能用于尚未到来的“明天”。", "怀念": "语义：“怀念”针对已经过去的人或事，与“明天去公园玩”这一未来的安排相冲突。", "整理": "搭配：“整理”一般接物品或事务，不能与“去公园玩”这类活动搭配。"}, "sentence_index": 0, "correct_answer": "期待"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常常期待童年的快乐。", "explanation": "这里应该用〈回忆〉。期待针对将来，童年已经过去，回想往事要用“回忆”。"}, {"text": "每周末我去期待外婆。", "explanation": "这里应该用〈看望〉。期待是心里盼着好事到来，不表示去见某人；每周去探望亲人要用“看望”。"}, {"text": "他很期待地震。", "explanation": "这里应该用〈害怕〉。期待表示对好事的盼望，不能用于不希望发生的灾害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "期待", "is_correct": true, "explanation": "期待着表示孩子心里盼着妈妈讲故事，与句意相符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”接的是场所或物品，不能与“妈妈讲故事”搭配。"}, {"text": "包扎", "is_correct": false, "explanation": "搭配：“包扎”针对伤口，不能与“讲故事”搭配，句子不通。"}, {"text": "发烧", "is_correct": false, "explanation": "配价：“发烧”是不及物动词，不能带“妈妈讲故事”作宾语。"}], "explanations": {"期待": "期待着表示孩子心里盼着妈妈讲故事，与句意相符。", "打扫": "搭配：“打扫”接的是场所或物品，不能与“妈妈讲故事”搭配。", "包扎": "搭配：“包扎”针对伤口，不能与“讲故事”搭配，句子不通。", "发烧": "配价：“发烧”是不及物动词，不能带“妈妈讲故事”作宾语。"}, "sentence_index": 6, "correct_answer": "期待"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很期待没有早点儿复习。", "explanation": "这里应该用〈后悔〉。期待表示对未来好事的希望，不能用来表达对过去没有努力的懊悔。"}, {"text": "科学家期待了这种病毒。", "explanation": "这里应该用〈研究〉。期待的对象是将要发生的事，不能用于正在研究的对象。"}, {"text": "师傅期待了那台旧电视。", "explanation": "这里应该用〈修理〉。期待不能用于对具体物品的动手处理，修理旧电视要用“修理”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我期待了那场比赛快点儿开始。", "corrected_sentence": "我期待那场比赛快点儿开始。", "error_description": "“期待”后不能加“了”。“了”表示已完成的动作，而比赛还没有开始，应去掉“了”，说“我期待那场比赛快点儿开始”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她期待得等着我的回信。", "corrected_sentence": "她期待地等着我的回信。", "error_description": "错误形式：她期待得等着我的回信。正确形式：她期待地等着我的回信。“期待”修饰动词“等”时作状语，状语后要用“地”，“得”只用于补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
