INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22452, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "机器、机构、制度等开始工作并持续运转。", "primary_collocate": null, "pronunciation": "yùn zuò", "ipa": "yn˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "这台机器运作得很好。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的新系统开始运作了。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行已经运作了十年。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道电脑是怎么运作的吗？", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂停电后，机器不能运作了。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小组运作得很顺利。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的各个部门一起运作。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的管理制度在学校运作了一个月。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个设备一直在正常运作着。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想知道市场是怎么运作的。", "target_word": "运作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运作着", "label": "体标"}, {"form": "运作过", "label": "体标"}, {"form": "运作起来", "label": "复合"}], "register": "中性", "sense_fingerprint": "运作：机器、机构等开始工作并持续运转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8c9982-2261-4a26-bafc-a41b87d5771d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22452, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运作", "is_correct": true, "explanation": "正确：运作指机器或机构开始工作并持续运转，与“这台机器”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉是人或动物的动作，机器不会睡觉。"}, {"text": "微笑", "is_correct": false, "explanation": "体貌：微笑描写脸上的表情，机器没有脸，不能说“微笑得很好”。"}, {"text": "生气", "is_correct": false, "explanation": "语义：生气是人的情绪，机器不会生气。"}], "explanations": {"运作": "正确：运作指机器或机构开始工作并持续运转，与“这台机器”搭配。", "睡觉": "语义：睡觉是人或动物的动作，机器不会睡觉。", "微笑": "体貌：微笑描写脸上的表情，机器没有脸，不能说“微笑得很好”。", "生气": "语义：生气是人的情绪，机器不会生气。"}, "sentence_index": 0, "correct_answer": "运作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批货物已经运作到了北京。", "explanation": "这里应该用〈运送〉。运作指机器或机构的运行，搬运货物要用运送。"}, {"text": "我每天运作一个小时，身体很好。", "explanation": "这里应该用〈运动〉。运作只用于机器、机构等，人锻炼身体要用运动。"}, {"text": "我爷爷今年八十岁，每天还去运作。", "explanation": "这里应该用〈工作〉。运作指机器或机构的运行，人去上班要用工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22452, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运作", "is_correct": true, "explanation": "正确：运作指部门等机构开始运行、开展工作，与“各个部门”搭配。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：哭泣是人的动作，部门不会哭泣。"}, {"text": "叹气", "is_correct": false, "explanation": "语义：叹气是人的情绪动作，机构不会叹气。"}, {"text": "脸红", "is_correct": false, "explanation": "体貌：脸红描写人脸的颜色，部门没有脸，不会脸红。"}], "explanations": {"运作": "正确：运作指部门等机构开始运行、开展工作，与“各个部门”搭配。", "哭泣": "语义：哭泣是人的动作，部门不会哭泣。", "叹气": "语义：叹气是人的情绪动作，机构不会叹气。", "脸红": "体貌：脸红描写人脸的颜色，部门没有脸，不会脸红。"}, "sentence_index": 6, "correct_answer": "运作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹妹每天在家运作两个小时。", "explanation": "这里应该用〈学习〉。运作只用于机器、机构等，人读书要用学习。"}, {"text": "这条河的水运作得很快。", "explanation": "这里应该用〈流动〉。运作指机器或机构的运行，水的移动要用流动。"}, {"text": "这棵树运作得很快。", "explanation": "这里应该用〈生长〉。运作指机器或机构的运行，树木长高要用生长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22452, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套系统运作地很稳定。", "corrected_sentence": "这套系统运作得很稳定。", "error_description": "“运作”后面表示程度的补语要用“得”，写成“地”是错误的，应说“运作得很稳定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22452, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个新机制运作了很好。", "corrected_sentence": "这个新机制运作得很好。", "error_description": "“运作”与表示程度的“很好”之间要用“得”，不能用“了”，应说“运作得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '043b20c4-266d-472e-83c4-79b105ac2049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
