INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22456, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一类西方语言的总称，英语、德语、荷兰语等都属于这一类。", "primary_collocate": null, "pronunciation": "rì ěr màn yǔ", "ipa": "ʐ̩˥˩ aɚ˨˩˦ man˥˩ y˨˩˦", "syllable_count": 4, "sentences": [{"text": "英语和德语都属于日耳曼语。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "荷兰语也是一种日耳曼语。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的论文主要比较日耳曼语和罗曼语。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日耳曼语有很多共同的词。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，瑞典语是日耳曼语。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日耳曼语的历史非常长。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想研究日耳曼语的语法。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪些国家说日耳曼语吗？", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "丹麦语和挪威语都是日耳曼语。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了日耳曼语的特点。", "target_word": "日耳曼语", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "日耳曼語", "label": "繁体"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "包括英语、德语、荷兰语等的语言大类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39273322-a49f-4295-81e9-e380ddef2d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22456, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日耳曼语", "is_correct": true, "explanation": "日耳曼语指英语、德语所属的语言大类，与句意相符。"}, {"text": "动物", "is_correct": false, "explanation": "语义：英语和德语是语言，不属于“动物”这一类。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“乐器”是用来演奏的器具，与英语、德语这类语言无关。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“属于”后接的类别应与英语、德语同属语言，“工具”不能作为它们的归属。"}], "explanations": {"日耳曼语": "日耳曼语指英语、德语所属的语言大类，与句意相符。", "动物": "语义：英语和德语是语言，不属于“动物”这一类。", "乐器": "语义：“乐器”是用来演奏的器具，与英语、德语这类语言无关。", "工具": "搭配：“属于”后接的类别应与英语、德语同属语言，“工具”不能作为它们的归属。"}, "sentence_index": 0, "correct_answer": "日耳曼语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这杯日耳曼语很好喝。", "explanation": "这里应该用〈咖啡〉。日耳曼语是一类语言，不能喝；能“好喝”的是饮料，如咖啡。"}, {"text": "我们周末去日耳曼语旅行。", "explanation": "这里应该用〈欧洲〉。日耳曼语是语言，不是地方，去某地旅行要用地名。"}, {"text": "妈妈做了一锅日耳曼语。", "explanation": "这里应该用〈汤〉。“一锅”修饰可以烹饪的食物，日耳曼语是语言，不能被做成食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22456, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日耳曼语", "is_correct": true, "explanation": "日耳曼语指一类语言，作“研究”的对象，与“语法”搭配，句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是语言，说“研究天气的语法”说不通。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：“饮料”不具备语法，与“研究……的语法”的语境完全不相合。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“语法”只与语言搭配，不能说“工厂的语法”。"}], "explanations": {"日耳曼语": "日耳曼语指一类语言，作“研究”的对象，与“语法”搭配，句意相符。", "天气": "语义：“天气”不是语言，说“研究天气的语法”说不通。", "饮料": "语义：“饮料”不具备语法，与“研究……的语法”的语境完全不相合。", "工厂": "搭配：“语法”只与语言搭配，不能说“工厂的语法”。"}, "sentence_index": 6, "correct_answer": "日耳曼语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是日耳曼语人。", "explanation": "这里应该用〈德国人〉。日耳曼语指语言，不指人；说人应用“日耳曼人”等民族称谓。"}, {"text": "我每天早上做日耳曼语。", "explanation": "这里应该用〈体操〉。“做”常接体操、作业等，日耳曼语是语言，不能被“做”。"}, {"text": "他把日耳曼语放进了花瓶。", "explanation": "这里应该用〈花〉。日耳曼语是语言，不是可以放进花瓶的实物，这种场合要用“花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他研究了几只日耳曼语的历史。", "corrected_sentence": "他研究了几种日耳曼语的历史。", "error_description": "“日耳曼语”是语言，应使用量词“种”，不能用“只”。正确说法是“几种日耳曼语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我学过一种的日耳曼语。", "corrected_sentence": "我学过一种日耳曼语。", "error_description": "“一种”后不能加“的”。数量词短语直接修饰名词，应说“一种日耳曼语”，中间不能加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
