INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22458, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22458, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里想要去做某件事。", "primary_collocate": null, "pronunciation": "qīng xiàng", "ipa": "tɕʰiŋ˥ ɕiaŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我倾向于坐火车去，不想坐飞机。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大多数同学倾向于在周末去爬山。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他倾向于选便宜一点的那家酒店。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她倾向于留在家里，不想出门。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理倾向于下个月再开始这个计划。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人们倾向于早睡早起。", "target_word": "倾向", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "比起面包，孩子倾向于吃米饭。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我现在倾向于换一份新工作。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家倾向于接受第二个办法。", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你倾向于住在城里还是乡下？", "target_word": "倾向", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "傾向", "label": "繁体"}], "register": "书面", "sense_fingerprint": "心里偏向于选择或想做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d72c37e-001c-46ce-9b8e-ae187f9ffc54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22458, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "倾向", "is_correct": true, "explanation": "正确：“倾向于”表示心里偏向某种选择，符合“不想坐飞机”的语境。"}, {"text": "沉溺", "is_correct": false, "explanation": "语义：“沉溺”指过分迷恋、无法自拔，与句中平常的偏向不符。"}, {"text": "忙碌", "is_correct": false, "explanation": "语义：“忙碌”指事务繁多，句子说的是心里的偏向，不是忙于事务。"}, {"text": "致力", "is_correct": false, "explanation": "语义：“致力于”指为大事业投入全部力量，“致力于坐火车去”语义不通。"}], "explanations": {"倾向": "正确：“倾向于”表示心里偏向某种选择，符合“不想坐飞机”的语境。", "沉溺": "语义：“沉溺”指过分迷恋、无法自拔，与句中平常的偏向不符。", "忙碌": "语义：“忙碌”指事务繁多，句子说的是心里的偏向，不是忙于事务。", "致力": "语义：“致力于”指为大事业投入全部力量，“致力于坐火车去”语义不通。"}, "sentence_index": 0, "correct_answer": "倾向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他倾向于昨天就把合同签了。", "explanation": "这里应该用〈决定〉。倾向只是心里偏向某件事，合同已经签了说明事情已经定下，应用“决定”。"}, {"text": "这面墙倾向于左边，快要倒了。", "explanation": "这里应该用〈倾斜〉。倾向表示心里偏向想做某件事，墙向一边歪斜要用“倾斜”。"}, {"text": "我倾向于明天不下雨。", "explanation": "这里应该用〈希望〉。倾向表示对做某事有偏向，对天气这类无法决定的事表达愿望要用“希望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倾向", "is_correct": true, "explanation": "正确：“倾向于”表示心里偏向某种选择，“孩子倾向于吃米饭”符合语境。"}, {"text": "醉心", "is_correct": false, "explanation": "语义：“醉心”指迷恋高雅的追求，与“吃米饭”不搭。"}, {"text": "献身", "is_correct": false, "explanation": "语义：“献身”指为崇高事业奉献自己，与“吃米饭”的语境不符。"}, {"text": "矢志", "is_correct": false, "explanation": "语义：“矢志”指发誓立下远大志向，“矢志于吃米饭”语义荒谬。"}], "explanations": {"倾向": "正确：“倾向于”表示心里偏向某种选择，“孩子倾向于吃米饭”符合语境。", "醉心": "语义：“醉心”指迷恋高雅的追求，与“吃米饭”不搭。", "献身": "语义：“献身”指为崇高事业奉献自己，与“吃米饭”的语境不符。", "矢志": "语义：“矢志”指发誓立下远大志向，“矢志于吃米饭”语义荒谬。"}, "sentence_index": 6, "correct_answer": "倾向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请你倾向于安静一点，别吵了。", "explanation": "这里应该用〈要求〉。倾向只表示心里偏向想做某事，对别人下命令或提要求不能用倾向，而应说“要求”。"}, {"text": "我倾向于在十年前就结婚了。", "explanation": "这里应该用〈已经〉。倾向只表示心里偏向想做某事，已经发生的事要说“已经”，不能用倾向于。"}, {"text": "我倾向于你明天早点来。", "explanation": "这里应该用〈希望〉。倾向表示自己心里偏向做某事，想让别人做某事要说“希望”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22458, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我倾向了明天去图书馆，人少。", "corrected_sentence": "我倾向于明天去图书馆，人少。", "error_description": "错误形式是“倾向了”，正确形式是“倾向于”。“倾向”是心理动词，后面不能加体标“了”，要带“于”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22458, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家倾向于于周末聚会，这样比较方便。", "corrected_sentence": "大家倾向于周末聚会，这样比较方便。", "error_description": "错误形式是“倾向于于”，正确形式是“倾向于”。“倾向于”后面已经有“于”，不能再加一个“于”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
