INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22460, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "这个词语表示在很多人或事物中，某一个特别突出。", "primary_collocate": null, "pronunciation": "yóu qí", "ipa": "joʊ˧˥ tɕʰi˧˥", "syllable_count": 2, "sentences": [{"text": "我喜欢水果，尤其喜欢苹果。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里夏天很热，尤其是七月。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱运动，尤其爱踢足球。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都很高兴，尤其是小明。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最近很忙，尤其是这个星期。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的秋天很美，尤其是香山。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她会几种语言，法语尤其好。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国菜都好吃，尤其是四川菜。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天天气不好，尤其是昨天，下了大雨。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人需要多休息，尤其是冬天。", "target_word": "尤其", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "尤其是", "label": "复合"}], "register": "中性", "sense_fingerprint": "尤其：在同类中特别突出某一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd6750d34-8059-4248-b24c-0c46300c707b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尤其", "is_correct": true, "explanation": "正确。“尤其”表示在喜欢的东西中特别突出苹果，符合语境。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从来没有，与“喜欢水果”矛盾。"}, {"text": "幸亏", "is_correct": false, "explanation": "语义：“幸亏”表示庆幸，不能引出对苹果的喜爱。"}, {"text": "刚才", "is_correct": false, "explanation": "搭配：“刚才”多接已经发生的动作，不能修饰表示长期爱好的“喜欢”。"}], "explanations": {"尤其": "正确。“尤其”表示在喜欢的东西中特别突出苹果，符合语境。", "从不": "语义：“从不”表示从来没有，与“喜欢水果”矛盾。", "幸亏": "语义：“幸亏”表示庆幸，不能引出对苹果的喜爱。", "刚才": "搭配：“刚才”多接已经发生的动作，不能修饰表示长期爱好的“喜欢”。"}, "sentence_index": 0, "correct_answer": "尤其"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天比昨天尤其冷。", "explanation": "这里应该用〈更加〉。“尤其”表示在一类中突出某一个，不用来比较两个时间的程度。"}, {"text": "我今天尤其去了学校。", "explanation": "这里应该用〈也〉。“尤其”表示在一类中突出某一个，此句没有可突出的对象，应说“也去了学校”。"}, {"text": "我到车站时，火车尤其到了。", "explanation": "这里应该用〈恰好〉。“尤其”表示在很多中突出某一个，不表示时间上的凑巧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尤其", "is_correct": true, "explanation": "正确。“法语尤其好”表示在几种语言中特别突出法语，符合语境。"}, {"text": "一起", "is_correct": false, "explanation": "搭配：“一起”表示共同做某事，不能修饰“好”。"}, {"text": "最终", "is_correct": false, "explanation": "语义：“最终”表示最后的结果，不能说明法语在几种语言中特别突出。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，不能说明法语好的程度。"}], "explanations": {"尤其": "正确。“法语尤其好”表示在几种语言中特别突出法语，符合语境。", "一起": "搭配：“一起”表示共同做某事，不能修饰“好”。", "最终": "语义：“最终”表示最后的结果，不能说明法语在几种语言中特别突出。", "立刻": "语义：“立刻”表示马上，不能说明法语好的程度。"}, "sentence_index": 6, "correct_answer": "尤其"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下了三天雨，今天雨尤其停了。", "explanation": "这里应该用〈终于〉。“尤其”表示突出某一个，不表示经过一段时间后出现的结果。"}, {"text": "没想到他尤其赢了比赛。", "explanation": "这里应该用〈竟然〉。“尤其”表示突出某一个，不表示出乎意料。"}, {"text": "我们先去超市，尤其再去买菜。", "explanation": "这里应该用〈然后〉。“尤其”表示突出某一个，不表示先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢运动，尤其了喜欢游泳。", "corrected_sentence": "我喜欢运动，尤其喜欢游泳。", "error_description": "错误形式：“尤其了喜欢”。正确形式：“尤其喜欢”。“尤其”是副词，后面不能加“了”，要直接放在动词“喜欢”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个季节的水果都很好吃，尤其的草莓。", "corrected_sentence": "这个季节的水果都很好吃，尤其是草莓。", "error_description": "错误形式：“尤其的草莓”。正确形式：“尤其是草莓”。“的”不能接在副词“尤其”后面；引出名词时通常说“尤其是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ce29b31-42eb-49d3-813e-ee51533cc933') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
