INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22462, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把某人或某物当作另一个东西。", "primary_collocate": null, "pronunciation": "shì wéi", "ipa": "ʂɻ̩˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "我把你视为最好的朋友。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把这只猫视为家人。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把每个学生都视为自己的孩子。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把工作视为生活中最重要的事。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国人把红色视为好运的颜色。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把这次比赛视为一次学习的机会。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有请假的人，今天一律视为缺勤。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这本旧书视为宝贝，从不借人。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能把朋友视为工具。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把客人视为最重要的人。", "target_word": "视为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "被视为", "label": "被动"}], "register": "书面语", "sense_fingerprint": "把A看作、当作B，常用“把A视为B”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b0532c88-8ee2-41a8-8416-c67566056b85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22462, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "视为", "is_correct": true, "explanation": "“视为”（shì wéi）是本词，表示把某人或某物当作另一种东西。"}, {"text": "示威", "is_correct": false, "explanation": "wēi（第一声）与 wéi（第二声）声调不同，意思是公开表示不满或反对。"}, {"text": "市委", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是市一级的中国共产党委员会。"}, {"text": "侍卫", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是在身边担任保卫的人。"}], "explanations": {"视为": "“视为”（shì wéi）是本词，表示把某人或某物当作另一种东西。", "示威": "wēi（第一声）与 wéi（第二声）声调不同，意思是公开表示不满或反对。", "市委": "wěi（第三声）与 wéi（第二声）声调不同，意思是市一级的中国共产党委员会。", "侍卫": "wèi（第四声）与 wéi（第二声）声调不同，意思是在身边担任保卫的人。"}, "sentence_index": null, "correct_answer": "视为"}, "level_3": {"options": [{"text": "视为", "is_correct": true, "explanation": "“视为”表示看作，“我把你视为最好的朋友”符合语境。"}, {"text": "撕成", "is_correct": false, "explanation": "语义：“撕成”指撕碎后变成，与“最好的朋友”的意思不合。"}, {"text": "晒成", "is_correct": false, "explanation": "语义：“晒成”指经日晒后变成，用来说人成为朋友说不通。"}, {"text": "驱逐", "is_correct": false, "explanation": "配价：“驱逐”要求驱逐某人出某地，不能接“最好的朋友”作结果。"}], "explanations": {"视为": "“视为”表示看作，“我把你视为最好的朋友”符合语境。", "撕成": "语义：“撕成”指撕碎后变成，与“最好的朋友”的意思不合。", "晒成": "语义：“晒成”指经日晒后变成，用来说人成为朋友说不通。", "驱逐": "配价：“驱逐”要求驱逐某人出某地，不能接“最好的朋友”作结果。"}, "sentence_index": 0, "correct_answer": "视为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把旧报纸视为一个纸箱。", "explanation": "这里应该用〈折成〉。视为表示看作某种身份或价值，把报纸折成箱子要说折成。"}, {"text": "我们把会议时间视为下午三点。", "explanation": "这里应该用〈确定〉。视为是看作，不表示订立或决定，会议时间要说确定。"}, {"text": "我们把这堆砖头视为一座房子。", "explanation": "这里应该用〈砌成〉。视为表示看作某种身份或价值，砖头变成房子要说砌成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视为", "is_correct": true, "explanation": "“视为”表示看作，“一律视为缺勤”符合规定的语境。"}, {"text": "鼓励", "is_correct": false, "explanation": "语义：“鼓励”表示支持、促进，“一律鼓励缺勤”与规定的意思相反。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”表示赞许，用来说缺勤说不通。"}, {"text": "分配", "is_correct": false, "explanation": "搭配：“分配”接任务、工作、名额，不说“分配缺勤”。"}], "explanations": {"视为": "“视为”表示看作，“一律视为缺勤”符合规定的语境。", "鼓励": "语义：“鼓励”表示支持、促进，“一律鼓励缺勤”与规定的意思相反。", "表扬": "语义：“表扬”表示赞许，用来说缺勤说不通。", "分配": "搭配：“分配”接任务、工作、名额，不说“分配缺勤”。"}, "sentence_index": 6, "correct_answer": "视为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我已经把作业视为完了。", "explanation": "这里应该用〈做〉。视为表示看作某种身份或价值，作业完成要说“把作业做完了”。"}, {"text": "我把这笔开支视为十万元。", "explanation": "这里应该用〈计算〉。视为是看作，核算金额要说计算。"}, {"text": "他不小心把杯子视为碎了。", "explanation": "这里应该用〈打〉。视为是看作，杯子被弄碎要说“把杯子打碎了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们他视为亲人。", "corrected_sentence": "我们把他视为亲人。", "error_description": "漏掉了“把”：“视为”要用“把A视为B”的结构，应说“我们把他视为亲人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我他把视为最可靠的伙伴。", "corrected_sentence": "我把他视为最可靠的伙伴。", "error_description": "“把”与宾语的语序错误：“把”后面应直接接宾语“他”，应说“我把他视为最可靠的伙伴”，不能说“我他把视为最可靠的伙伴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd73012e9-4c21-4d34-9a52-e157adf886c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
