INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22464, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "是", "primary_collocate": null, "pronunciation": "xì", "ipa": "ɕi˥˩", "syllable_count": 1, "sentences": [{"text": "这座桥系百年前所建。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该书系王教授亲自所写。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "此画系明代作品，很珍贵。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他系本市人，今年三十岁。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份礼物系朋友所送。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经查，此事系误会一场。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本店的茶叶系自家种的。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信系老校长亲笔写的。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "该产品系中国制造。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张先生系我们公司的经理。", "target_word": "系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面语中表示判断的“是”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39273322-a49f-4295-81e9-e380ddef2d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22464, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "系", "is_correct": true, "explanation": "系（xì）：书面语中表示判断，相当于“是”，正是本题要找的词。"}, {"text": "西", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是西方、西边。"}, {"text": "喜", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是喜欢。"}, {"text": "习", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是学习、习惯。"}], "explanations": {"系": "系（xì）：书面语中表示判断，相当于“是”，正是本题要找的词。", "西": "xī（第一声）与 xì（第四声）声调不同，意思是西方、西边。", "喜": "xǐ（第三声）与 xì（第四声）声调不同，意思是喜欢。", "习": "xí（第二声）与 xì（第四声）声调不同，意思是学习、习惯。"}, "sentence_index": null, "correct_answer": "系"}, "level_3": {"options": [{"text": "系", "is_correct": true, "explanation": "系表示判断，与“百年前所建”相合，句意正确。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“桥”是物体，不能“参观”，句子不通。"}, {"text": "修", "is_correct": false, "explanation": "配价：“修”需要接修理的对象，不能接“百年前所建”作宾语。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：“拍”与“百年前所建”不搭配，无法表达建造的意思。"}], "explanations": {"系": "系表示判断，与“百年前所建”相合，句意正确。", "参观": "语义：“桥”是物体，不能“参观”，句子不通。", "修": "配价：“修”需要接修理的对象，不能接“百年前所建”作宾语。", "拍": "搭配：“拍”与“百年前所建”不搭配，无法表达建造的意思。"}, "sentence_index": 0, "correct_answer": "系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们系有很多外国学生。", "explanation": "这里的“系”指大学里的院系，是名词，与本句作判断的“系”不是同一个意思。"}, {"text": "他把钥匙系在腰上。", "explanation": "这里的“系”是系结、拴住的意思，与本句作判断的“系”不是同一个意思。"}, {"text": "这件事系着我的心。", "explanation": "这里的“系”是牵挂、连着的意思，与本句作判断的“系”不是同一个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22464, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "系", "is_correct": true, "explanation": "系（xì）：书面语中表示判断，相当于“是”，正是本题要找的词。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是座位、宴席。"}, {"text": "息", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸、消息。"}, {"text": "洗", "is_correct": false, "explanation": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。"}], "explanations": {"系": "系（xì）：书面语中表示判断，相当于“是”，正是本题要找的词。", "席": "xí（第二声）与 xì（第四声）声调不同，意思是座位、宴席。", "息": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸、消息。", "洗": "xǐ（第三声）与 xì（第四声）声调不同，意思是清洗。"}, "sentence_index": null, "correct_answer": "系"}, "level_3": {"options": [{"text": "系", "is_correct": true, "explanation": "系表示判断，与“自家种的”构成判断句，句意正确。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”指移动物体，不能用来说明茶叶的来源。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”接饮品，不能说茶叶“喝自家种的”。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”指用刀斩断，与茶叶的种植和来源无关。"}], "explanations": {"系": "系表示判断，与“自家种的”构成判断句，句意正确。", "搬": "语义：“搬”指移动物体，不能用来说明茶叶的来源。", "喝": "搭配：“喝”接饮品，不能说茶叶“喝自家种的”。", "砍": "语义：“砍”指用刀斩断，与茶叶的种植和来源无关。"}, "sentence_index": 6, "correct_answer": "系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他弯腰系好了鞋带。", "explanation": "这里的“系”是系结的意思，表示把绳子打结，与本句作判断的“系”不是同一个意思。"}, {"text": "他系了一件红衬衫。", "explanation": "这里应该用〈穿〉。“系”不能用于穿衬衫，穿衣服要用“穿”。"}, {"text": "他系了三个故事。", "explanation": "这里应该用〈讲〉。“系”不能接“故事”作宾语，讲故事要用“讲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座古城不系明朝所建。", "corrected_sentence": "这座古城系明朝所建。", "error_description": "“系”表示判断，不能直接加“不”构成否定。否定判断应用“并非”或“不是”，而不是“不系”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告系了我亲自写的。", "corrected_sentence": "这份报告系我亲自写的。", "error_description": "“系”后不能加“了”。“了”表示完成，而“系”表示判断，应去掉“了”，说“这份报告系我亲自写的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22466, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
