INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人与人之间的往来和交流。", "primary_collocate": null, "pronunciation": "shè jiāo", "ipa": "ʂɤ˥˩ tɕjaʊ˥", "syllable_count": 2, "sentences": [{"text": "他很爱社交，周末常常和朋友出去玩。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太喜欢社交，更想在家看书。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要社交，所以要多和同学玩。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社交对孩子的成长很重要。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很擅长社交，朋友特别多。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作以后，我的社交多了起来。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱社交，一到聚会就想回家。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多一点社交，心情也会好一点。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，孩子的社交要从小练习。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有社交的生活，他觉得很无聊。", "target_word": "社交", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词，人与人之间的往来和交流", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "孤独", "is_correct": false, "explanation": "语义：“孤独”与“周末常和朋友出去玩”相反，句意矛盾。"}, {"text": "社交", "is_correct": true, "explanation": "社交指人与人之间的往来，“很爱社交”表示喜欢与人交往。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“爱”不能与“体温”这类身体指标搭配。"}, {"text": "病床", "is_correct": false, "explanation": "语义：“病床”是医疗用品，不是可以“爱”的事物，与“出去玩”也不相合。"}], "explanations": {"孤独": "语义：“孤独”与“周末常和朋友出去玩”相反，句意矛盾。", "社交": "社交指人与人之间的往来，“很爱社交”表示喜欢与人交往。", "体温": "搭配：“爱”不能与“体温”这类身体指标搭配。", "病床": "语义：“病床”是医疗用品，不是可以“爱”的事物，与“出去玩”也不相合。"}, "sentence_index": 0, "correct_answer": "社交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的社交很大，有三间卧室。", "explanation": "这里应该用〈房子〉。“社交”指人际往来，不是建筑，不能说“我家的社交很大”；应说“我家的房子很大”。"}, {"text": "这条路上的社交很堵，每天都要等很久。", "explanation": "这里应该用〈交通〉。“堵”描述车流，“社交”指人际往来，不能说“社交很堵”；应说“交通很堵”。"}, {"text": "社交已经签好了，大家都很满意。", "explanation": "这里应该用〈协议〉。社交指人与人之间的往来，不是可以签订的文件；“签好”的对象应是协议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家电，不是可以“不爱”的活动，与“一到聚会就想回家”无关联。"}, {"text": "社交", "is_correct": true, "explanation": "社交指人与人之间的往来，“不爱社交”表示不喜欢与人交往，与“一到聚会就想回家”相符。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“不爱”一般不用于“天气”这类自然现象，说“不爱天气”不通。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是物品，与“聚会”和“想回家”的意思无关，句意不通。"}], "explanations": {"冰箱": "语义：“冰箱”是家电，不是可以“不爱”的活动，与“一到聚会就想回家”无关联。", "社交": "社交指人与人之间的往来，“不爱社交”表示不喜欢与人交往，与“一到聚会就想回家”相符。", "天气": "搭配：“不爱”一般不用于“天气”这类自然现象，说“不爱天气”不通。", "地毯": "语义：“地毯”是物品，与“聚会”和“想回家”的意思无关，句意不通。"}, "sentence_index": 6, "correct_answer": "社交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国家为老人提供社交保险。", "explanation": "这里应该用〈社会〉，说“社会保险”。“社交”指人际往来，不指社会保障制度。"}, {"text": "我们在会议上社交经验。", "explanation": "这里应该用〈交流〉。社交指人际往来，不表示交换想法和经验。"}, {"text": "我们是社交主义国家。", "explanation": "这里应该用〈社会〉，说“社会主义”。“社交主义”不是固定说法，与国家制度无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天参加了一把社交活动，玩得很开心。", "corrected_sentence": "我昨天参加了一次社交活动，玩得很开心。", "error_description": "错误形式：“一把社交活动”；正确形式：“一次社交活动”。活动应用量词“次”；“把”用于有柄的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很会社交朋友，所以朋友很多。", "corrected_sentence": "她很会社交，所以朋友很多。", "error_description": "错误形式：“会社交朋友”；正确形式：“会社交”或“会交朋友”。“社交”后面不能直接带宾语“朋友”，应说“交朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
