INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22474, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一整块东西切开成几块。", "primary_collocate": null, "pronunciation": "fēn gē", "ipa": "fən˥ kɤ˥", "syllable_count": 2, "sentences": [{"text": "妈妈把蛋糕分割成八块。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用刀分割那块木头。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把铁板分割成小块。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这块肉分割一下。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用线分割了这块豆腐。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师分割了整只烤鸭。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把西瓜分割成六份。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正在分割一块大石头。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把面团分割成几个小块。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用剪刀分割了这张纸。", "target_word": "分割", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分割了", "label": "体标"}, {"form": "分割着", "label": "体标"}, {"form": "分割线", "label": "复合"}], "register": "中性", "sense_fingerprint": "用刀等把一整块具体物体切成几块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39273322-a49f-4295-81e9-e380ddef2d10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22474, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分割", "is_correct": true, "explanation": "正确：“把蛋糕……成八块”描述切开的结果，只有分割符合。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：搬运只是移动位置，不会把蛋糕切成八块。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”不能带“成八块”这样的切分结果，蛋糕也不是测量的对象。"}, {"text": "浇灌", "is_correct": false, "explanation": "配价：“浇灌”要求液体或植物作宾语，蛋糕不能被浇灌。"}], "explanations": {"分割": "正确：“把蛋糕……成八块”描述切开的结果，只有分割符合。", "搬运": "语义：搬运只是移动位置，不会把蛋糕切成八块。", "测量": "搭配：“测量”不能带“成八块”这样的切分结果，蛋糕也不是测量的对象。", "浇灌": "配价：“浇灌”要求液体或植物作宾语，蛋糕不能被浇灌。"}, "sentence_index": 0, "correct_answer": "分割"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把一大桶果汁分割成六瓶。", "explanation": "这里应该用〈分装〉。分割用于切开固体，液体分装到容器中要用分装。"}, {"text": "他把旧玩具的螺丝分割了，好取出里面的零件。", "explanation": "这里应该用〈拧下〉。螺丝要拧下来，不能切成几块，分割不适用。"}, {"text": "医生分割了病人的肚子。", "explanation": "这里应该用〈剖开〉。此句是对病人腹部开刀，应说剖开；“肚子”也不是可以切成几块的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22474, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分割", "is_correct": true, "explanation": "正确：“把西瓜……成六份”描述切分的结果，与分割的意义相符。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：烘烤是加热使食物变熟，不能把西瓜分成六份。"}, {"text": "浸泡", "is_correct": false, "explanation": "搭配：“浸泡成六份”的说法不通，浸泡不会把西瓜切开。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻只改变温度和状态，不会把西瓜分成几份。"}], "explanations": {"分割": "正确：“把西瓜……成六份”描述切分的结果，与分割的意义相符。", "烘烤": "语义：烘烤是加热使食物变熟，不能把西瓜分成六份。", "浸泡": "搭配：“浸泡成六份”的说法不通，浸泡不会把西瓜切开。", "冷冻": "语义：冷冻只改变温度和状态，不会把西瓜分成几份。"}, "sentence_index": 6, "correct_answer": "分割"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用小刀分割了苹果皮。", "explanation": "这里应该用〈削〉。去掉表皮要用削，分割指把整体切成块。"}, {"text": "他不小心把花瓶分割了。", "explanation": "这里应该用〈打碎〉。花瓶摔成碎片要用打碎；分割指把整体切成几部分，不指意外摔碎。"}, {"text": "工人把铁块分割成铁水。", "explanation": "这里应该用〈熔化〉。铁块变成液体属于状态改变，不是切开，应说熔化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22474, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把饼干分割四块。", "corrected_sentence": "妈妈把饼干分割成四块。", "error_description": "错误形式：分割四块。正确形式：分割成四块。把整体切成几块时，“分割”后要用“成”引出结果，不能直接接数量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22474, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把钢管分割了成三段。", "corrected_sentence": "工人把钢管分割成了三段。", "error_description": "错误形式：分割了成三段。正确形式：分割成了三段。“了”应放在“成”之后，表示切分这一结果已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b6d35ee-cf23-4c09-8986-b23792e84959') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
