INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22476, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人说好要一起做的事。", "primary_collocate": null, "pronunciation": "qì yuē", "ipa": "tɕʰi˥˩ ɥe˥", "syllable_count": 2, "sentences": [{"text": "他们签了一份契约。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份契约有两页纸。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友订了一份契约。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "契约上写得很清楚，不能改。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人要遵守契约。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份契约明年三月到期。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他破坏了和公司的契约。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好朋友之间也要有契约。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸看了一遍契约，才在上面签字。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "契约是两个人说好的事，要写下来。", "target_word": "契约", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "契約", "label": "繁体"}, {"form": "一份契约", "label": "量词"}, {"form": "契约精神", "label": "复合"}], "register": "书面", "sense_fingerprint": "双方约定并要共同遵守的事项，常写成文字；名词义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '33c7f637-619d-49ba-80ef-a53edb7b3254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22476, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "契约", "is_correct": true, "explanation": "正确答案：契约（qì yuē），指双方约定并要共同遵守的事项。"}, {"text": "气压", "is_correct": false, "explanation": "yā（第一声）与 yuē（第一声）韵母不同（-a 与 -ue），意思是大气的压力。"}, {"text": "汽油", "is_correct": false, "explanation": "yóu（第二声）与 yuē（第一声）韵母与声调都不同，意思是汽车等燃料。"}, {"text": "器乐", "is_correct": false, "explanation": "yuè（第四声）与 yuē（第一声）声调不同，意思是乐器演奏的音乐。"}], "explanations": {"契约": "正确答案：契约（qì yuē），指双方约定并要共同遵守的事项。", "气压": "yā（第一声）与 yuē（第一声）韵母不同（-a 与 -ue），意思是大气的压力。", "汽油": "yóu（第二声）与 yuē（第一声）韵母与声调都不同，意思是汽车等燃料。", "器乐": "yuè（第四声）与 yuē（第一声）声调不同，意思是乐器演奏的音乐。"}, "sentence_index": null, "correct_answer": "契约"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“作业”是学生完成的练习，不是双方签字确认的约定，“签了一份作业”说不通。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的说明，不是双方可以签字的文件。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不是需要双方签字确认的东西，“签一份地图”说不通。"}, {"text": "契约", "is_correct": true, "explanation": "正确：“契约”是双方约定的书面文件，可以签。"}], "explanations": {"作业": "语义：“作业”是学生完成的练习，不是双方签字确认的约定，“签了一份作业”说不通。", "食谱": "语义：食谱是做菜的说明，不是双方可以签字的文件。", "地图": "语义：地图不是需要双方签字确认的东西，“签一份地图”说不通。", "契约": "正确：“契约”是双方约定的书面文件，可以签。"}, "sentence_index": 0, "correct_answer": "契约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的契约很喜欢吃甜点。", "explanation": "这里应该用〈他〉作主语。“契约”是事项或文件，不是人，不会喜欢吃东西。"}, {"text": "妈妈用契约做了一碗汤。", "explanation": "这里应该用〈鸡蛋〉之类的食材。“契约”是双方约定的事项或文件，不能用来做饭。"}, {"text": "老师布置了一份契约，明天要交。", "explanation": "这里应该用〈作业〉。“契约”指两个人说好要一起做的事，不是老师布置的作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22476, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "契约", "is_correct": true, "explanation": "正确答案：契约（qì yuē），指双方约定并要共同遵守的事项。"}, {"text": "七月", "is_correct": false, "explanation": "qī（第一声）与 qì（第四声）声调不同，yuè（第四声）与 yuē（第一声）声调也不同，意思是一年中的第七个月。"}, {"text": "企业", "is_correct": false, "explanation": "qǐ（第三声）与 qì（第四声）声调不同，yè 与 yuē 韵母与声调都不同，意思是从事经济活动的组织。"}, {"text": "器乐", "is_correct": false, "explanation": "qì 与 qì 相同，yuè（第四声）与 yuē（第一声）声调不同，意思是用乐器演奏的音乐。"}], "explanations": {"契约": "正确答案：契约（qì yuē），指双方约定并要共同遵守的事项。", "七月": "qī（第一声）与 qì（第四声）声调不同，yuè（第四声）与 yuē（第一声）声调也不同，意思是一年中的第七个月。", "企业": "qǐ（第三声）与 qì（第四声）声调不同，yè 与 yuē 韵母与声调都不同，意思是从事经济活动的组织。", "器乐": "qì 与 qì 相同，yuè（第四声）与 yuē（第一声）声调不同，意思是用乐器演奏的音乐。"}, "sentence_index": null, "correct_answer": "契约"}, "level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：“名字”不是双方之间的约定，“破坏了和公司的名字”说不通。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：“饭菜”不是双方要遵守的约定，与“破坏”搭配不通。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“破坏”不能用于“地址”，地址不会被“破坏”。"}, {"text": "契约", "is_correct": true, "explanation": "正确：“破坏契约”指违反双方的约定，与“和公司的”搭配。"}], "explanations": {"名字": "语义：“名字”不是双方之间的约定，“破坏了和公司的名字”说不通。", "饭菜": "语义：“饭菜”不是双方要遵守的约定，与“破坏”搭配不通。", "地址": "搭配：“破坏”不能用于“地址”，地址不会被“破坏”。", "契约": "正确：“破坏契约”指违反双方的约定，与“和公司的”搭配。"}, "sentence_index": 6, "correct_answer": "契约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题的契约很清楚，大家都写对了。", "explanation": "这里应该用〈答案〉。“契约”指两个人说好要一起做的事，不能用来指题目的答案。"}, {"text": "这份契约很甜，我非常喜欢。", "explanation": "这里应该用〈糖〉。“契约”是双方约定的事项或文件，没有甜的味道。"}, {"text": "我是他的契约。", "explanation": "这里应该用〈伙伴〉。契约指两个人说好要一起做的事，是事情，不能用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22476, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们签了一条契约，双方各保存一份。", "corrected_sentence": "他们签了一份契约，双方各保存一份。", "error_description": "量词错误。“契约”是文件，量词应用“份”；“条”用于细长的东西，不能用来数契约。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22476, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每人保存份一契约。", "corrected_sentence": "我们每人保存一份契约。", "error_description": "数词和量词的顺序错误。应说“一份”，不能说“份一”，数量词“一份”要放在名词前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a6e5269-46a9-40a4-82a5-5add1fa99c1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
