INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "框架是东西的架子，用来撑住它。", "primary_collocate": null, "pronunciation": "kuàng jià", "ipa": "kʰwaŋ˥˩ tɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这个房子的框架是铁做的。", "target_word": "框架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子的木头框架很结实。", "target_word": "框架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把伞的框架坏了。", "target_word": "框架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户的框架是用木头做的。", "target_word": "框架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "眼镜的框架很轻，戴着很舒服。", "target_word": "框架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人先搭好了房子的框架。", "target_word": "框架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆自行车的框架很轻。", "target_word": "框架", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "先做好框架，再把布放上去。", "target_word": "框架", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个帐篷的框架很容易搭。", "target_word": "框架", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大楼的钢铁框架已经完成了。", "target_word": "框架", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "通用", "sense_fingerprint": "名词，指房子、伞、眼镜等东西里起支撑作用的架子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22478, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不是由材料做成的，不能说“是铁做的”。"}, {"text": "框架", "is_correct": true, "explanation": "“框架”是支撑房子的骨架，可以用铁做，符合句子。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是气味，不是能用铁做成的实体，句子不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”是声响，不是实物，不能说是用铁做的。"}], "explanations": {"颜色": "搭配：“颜色”不是由材料做成的，不能说“是铁做的”。", "框架": "“框架”是支撑房子的骨架，可以用铁做，符合句子。", "味道": "语义：“味道”是气味，不是能用铁做成的实体，句子不通。", "声音": "语义：“声音”是声响，不是实物，不能说是用铁做的。"}, "sentence_index": 0, "correct_answer": "框架"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个恐龙的框架很大，博物馆里很多人来看。", "explanation": "这里应该用〈骨架〉。“框架”指房屋、伞等东西的支撑架子，动物的骨骼要用“骨架”。"}, {"text": "工地上放着一头框架，工人正在检查。", "explanation": "这里应该用〈个〉。“框架”用“个”计量，“头”多用于大型牲畜，不能用来数框架。"}, {"text": "他的框架很大，个子也高，力气也大。", "explanation": "这里应该用〈体格〉。“框架”指东西的支撑架子，形容人的身材骨骼要用“体格”，不说“框架”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22478, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“价格”可以说高低，但不能用“很轻”来形容，句子不通。"}, {"text": "框架", "is_correct": true, "explanation": "“框架”是自行车的车架，可以说轻或重，符合句子。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：“外貌”指人或事物的样子，不是重量，不能说“很轻”。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”是内心的感受，不是有重量的实物，句子读起来不通。"}], "explanations": {"价格": "搭配：“价格”可以说高低，但不能用“很轻”来形容，句子不通。", "框架": "“框架”是自行车的车架，可以说轻或重，符合句子。", "外貌": "语义：“外貌”指人或事物的样子，不是重量，不能说“很轻”。", "心情": "语义：“心情”是内心的感受，不是有重量的实物，句子读起来不通。"}, "sentence_index": 6, "correct_answer": "框架"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里用框架炒菜，很香。", "explanation": "这里应该用〈锅〉。“框架”指支撑用的架子，不能用来炒菜；炒菜要用“锅”。"}, {"text": "我渴了，用框架喝了一杯水。", "explanation": "这里应该用〈杯子〉。“框架”指支撑用的架子，不能用来喝水；喝水要用“杯子”。"}, {"text": "他每天早上用框架刷牙。", "explanation": "这里应该用〈牙刷〉。“框架”指支撑用的架子，不能用来刷牙；刷牙要用“牙刷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人搭了一台框架，准备盖屋顶。", "corrected_sentence": "工人搭了一个框架，准备盖屋顶。", "error_description": "量词错误：“框架”通常用“个”，不能用“台”（“台”多用于机器、设备、电器）。正确说法是“一个框架”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个棚子的框架们已经搭好了，明天就能盖顶。", "corrected_sentence": "这个棚子的框架已经搭好了，明天就能盖顶。", "error_description": "错误：“框架”是物体，不能加“们”表示复数，应去掉“们”，说“这个棚子的框架已经搭好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22480, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遵循", "is_correct": true, "explanation": "遵循指依照原来的方向或原则行事，与背离是反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指用脑子考虑问题，与背离不构成反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集指把东西聚拢起来，与背离不构成反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论指交换意见，与背离不构成反义关系。"}], "correct_answer": "遵循", "explanations": {"遵循": "遵循指依照原来的方向或原则行事，与背离是反义关系。", "思考": "思考指用脑子考虑问题，与背离不构成反义关系。", "收集": "收集指把东西聚拢起来，与背离不构成反义关系。", "讨论": "讨论指交换意见，与背离不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22480, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遵循", "is_correct": true, "explanation": "遵循指依照原来的方向或原则行事，与背离是反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”与“背离”没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "参加指加入某项活动，与背离不构成反义关系。"}, {"text": "收获", "is_correct": false, "explanation": "收获指得到的成果，与背离不构成反义关系。"}], "correct_answer": "遵循", "explanations": {"遵循": "遵循指依照原来的方向或原则行事，与背离是反义关系。", "散步": "无关：“散步”与“背离”没有反义关系。", "参加": "参加指加入某项活动，与背离不构成反义关系。", "收获": "收获指得到的成果，与背离不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开或违反，不再跟着原来的路走。", "primary_collocate": null, "pronunciation": "bèi lí", "ipa": "pei̯˥˩ li˧˥", "syllable_count": 2, "sentences": [{"text": "这样做背离了我们的初衷。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话完全背离了事实。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能背离自己的原则。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划已经背离了最初的目标。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人有时会背离家里的传统。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行动背离了他说过的话。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影背离了原来的故事。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做人不能背离良心。", "target_word": "背离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的服务背离了顾客的期待。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的选择背离了父母的希望。", "target_word": "背离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "背离了", "label": "体标（了）"}, {"form": "背离过", "label": "体标（过）"}], "register": "书面语", "sense_fingerprint": "背离：离开或违反原来的方向、原则、目标", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3299c7cb-711f-45ac-8e59-3053bcf7ff57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "背离", "is_correct": true, "explanation": "“背离”指离开或违反原来的方向、原则，与“背离了我们的初衷”相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：“搬”只能搬具体的东西，不能搬“初衷”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃“初衷”。"}, {"text": "装", "is_correct": false, "explanation": "语义：“装”指把东西放进容器，与“这样做……初衷”的句意不符。"}], "explanations": {"背离": "“背离”指离开或违反原来的方向、原则，与“背离了我们的初衷”相符。", "搬": "搭配：“搬”只能搬具体的东西，不能搬“初衷”。", "吃": "搭配：“吃”的对象是食物，不能说吃“初衷”。", "装": "语义：“装”指把东西放进容器，与“这样做……初衷”的句意不符。"}, "sentence_index": 0, "correct_answer": "背离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天都背离一杯牛奶。", "explanation": "这里应该用〈喝〉。“背离”指违反原则或偏离方向，不能用于牛奶。"}, {"text": "老师背离了学生的作业。", "explanation": "这里应该用〈批改〉。“背离”指违反原则或偏离方向，不能用于作业。"}, {"text": "我每天都背离旧报纸，很麻烦。", "explanation": "这里应该用〈整理〉。“背离”指违反原则或偏离方向，不能用于旧报纸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "背离", "is_correct": true, "explanation": "“背离”指违背原来的情节或事实，与“这部电影……原来的故事”相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是可以清洗的东西，不能说洗“故事”。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”用于纸张、布料等有形之物，不能撕“故事”。"}, {"text": "倒", "is_correct": false, "explanation": "语义：“倒”指把液体或东西倾出，与电影情节无关。"}], "explanations": {"背离": "“背离”指违背原来的情节或事实，与“这部电影……原来的故事”相符。", "洗": "搭配：“洗”的对象是可以清洗的东西，不能说洗“故事”。", "撕": "搭配：“撕”用于纸张、布料等有形之物，不能撕“故事”。", "倒": "语义：“倒”指把液体或东西倾出，与电影情节无关。"}, "sentence_index": 6, "correct_answer": "背离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都背离家务，很辛苦。", "explanation": "这里应该用〈承担〉。承担指接受并负责某项任务，背离指偏离原来的路线或原则，不用于家务。"}, {"text": "他每天都背离那堆脏衣服，还不去洗。", "explanation": "这里应该用〈洗〉。“背离”指违反原则或偏离方向，不能用于衣服。"}, {"text": "奶奶每天都背离院子里的花。", "explanation": "这里应该用〈照顾〉。“背离”指违反原则或偏离方向，不能用于照料花草。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他背离开了我们的约定。", "corrected_sentence": "他背离了我们的约定。", "error_description": "错误：“背离”后多了“开”，应说“背离了”。“背离”本身已含离开、违反的意思，不需要加“开”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他没有背离了朋友的信任。", "corrected_sentence": "他没有背离朋友的信任。", "error_description": "体标错误：“没有”否定已发生的动作，不与“了”同用，应说“没有背离”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
