INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22482, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "单位是量东西时用的标准，比如米量长度。", "primary_collocate": null, "pronunciation": "dān wèi", "ipa": "tan˥ weɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "米是长度的单位。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "重量的单位是公斤。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字后面没写单位。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请写上单位，比如米或者厘米。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间的单位有秒、分钟和小时。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格的单位是元。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度的单位是摄氏度。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题的答案要带单位。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，面积常用平方米做单位。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水的体积单位是升。", "target_word": "单位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个单位", "label": "量词"}, {"form": "计量单位", "label": "复合"}, {"form": "度量单位", "label": "复合"}, {"form": "單位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "计量事物时所用的标准量，如米、公斤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22482, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "单位", "is_correct": true, "explanation": "正确。单位是计量时用的标准，如米、公斤。"}, {"text": "摊位", "is_correct": false, "explanation": "tān（第一声）与 dān（第一声）声母不同（t/d），意思是摆摊的地方。"}, {"text": "三位", "is_correct": false, "explanation": "sān（第一声）与 dān（第一声）只差声母（s/d），意思是三个人（如三位客人）。"}, {"text": "单倍", "is_correct": false, "explanation": "bèi 与 wèi 声母不同（b/w），意思是单一的倍数。"}], "explanations": {"单位": "正确。单位是计量时用的标准，如米、公斤。", "摊位": "tān（第一声）与 dān（第一声）声母不同（t/d），意思是摆摊的地方。", "三位": "sān（第一声）与 dān（第一声）只差声母（s/d），意思是三个人（如三位客人）。", "单倍": "bèi 与 wèi 声母不同（b/w），意思是单一的倍数。"}, "sentence_index": null, "correct_answer": "单位"}, "level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "语义：米说的是长度单位，“长度的重量”是另一种量，句子不通。"}, {"text": "单位", "is_correct": true, "explanation": "正确。“单位”是量长度时用的标准，米是长度的单位。"}, {"text": "工具", "is_correct": false, "explanation": "语义：米是长度的计量标准，不是工具，“长度的工具”不合逻辑。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“长度的”后面要接计量标准，不能接“数字”。"}], "explanations": {"重量": "语义：米说的是长度单位，“长度的重量”是另一种量，句子不通。", "单位": "正确。“单位”是量长度时用的标准，米是长度的单位。", "工具": "语义：米是长度的计量标准，不是工具，“长度的工具”不合逻辑。", "数字": "搭配：“长度的”后面要接计量标准，不能接“数字”。"}, "sentence_index": 0, "correct_answer": "单位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告的单位是三页。", "explanation": "这里应该用〈页数〉。单位是计量标准，报告有几页要说页数，不能用“单位”。"}, {"text": "这道菜的单位很好吃。", "explanation": "这里应该用〈味道〉。单位是计量时用的标准，不能用来说菜好不好吃。"}, {"text": "这个箱子的单位很大。", "explanation": "这里应该用〈体积〉。体积说明有多大，单位只是计量的标准，没有大小之分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22482, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "单位", "is_correct": true, "explanation": "正确。单位是计量时用的标准，如升、摄氏度。"}, {"text": "段位", "is_correct": false, "explanation": "duàn（第四声）与 dān（第一声）声调不同，并多了 u 音，意思是等级、级别。"}, {"text": "淡味", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是味道清淡。"}, {"text": "蛋味", "is_correct": false, "explanation": "dàn（第四声）与 dān（第一声）声调不同，意思是鸡蛋的味道。"}], "explanations": {"单位": "正确。单位是计量时用的标准，如升、摄氏度。", "段位": "duàn（第四声）与 dān（第一声）声调不同，并多了 u 音，意思是等级、级别。", "淡味": "dàn（第四声）与 dān（第一声）声调不同，意思是味道清淡。", "蛋味": "dàn（第四声）与 dān（第一声）声调不同，意思是鸡蛋的味道。"}, "sentence_index": null, "correct_answer": "单位"}, "level_3": {"options": [{"text": "数据", "is_correct": false, "explanation": "语义：摄氏度是温度的计量标准，不是数据，“温度的数据是摄氏度”说不通。"}, {"text": "单位", "is_correct": true, "explanation": "正确。“单位”是计量温度时用的标准，摄氏度是温度的计量单位。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“温度的”后面不能接“价格”，两者没有搭配关系。"}, {"text": "电话", "is_correct": false, "explanation": "语义：温度与电话无关，“温度的电话是摄氏度”不合逻辑。"}], "explanations": {"数据": "语义：摄氏度是温度的计量标准，不是数据，“温度的数据是摄氏度”说不通。", "单位": "正确。“单位”是计量温度时用的标准，摄氏度是温度的计量单位。", "价格": "搭配：“温度的”后面不能接“价格”，两者没有搭配关系。", "电话": "语义：温度与电话无关，“温度的电话是摄氏度”不合逻辑。"}, "sentence_index": 6, "correct_answer": "单位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请在这张单位后面写上数字。", "explanation": "这里不应使用量词“张”。“张”用于纸张等平面物，“单位”前不加“张”。"}, {"text": "这个包裹的单位是五公斤。", "explanation": "这里应该用〈重量〉。重量说明有多少，单位说明用什么标准计量，不能把重量说成单位。"}, {"text": "这件衣服的单位很合适。", "explanation": "这里应该用〈尺寸〉。“合适”形容的是大小，衣服是否合适要说尺寸，单位是计量标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个数字后面要写上一根单位。", "corrected_sentence": "这个数字后面要写上单位。", "error_description": "错误：“根”用于细长的东西，不能用来修饰“单位”。应去掉量词，说“写上单位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电压的单位了是伏特。", "corrected_sentence": "电压的单位是伏特。", "error_description": "错误：“单位”后多加了“了”。名词“单位”不能带“了”，应说“电压的单位是伏特”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
