INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22488, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22488, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "车、船、飞机让人和东西走来走去。", "primary_collocate": null, "pronunciation": "jiāo tōng", "ipa": "tɕjɑʊ˥ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "这个小镇的交通不方便，一天只有两班车。", "target_word": "交通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们村里没有路，交通靠小船。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的交通很发达，有地铁和火车。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个地方有机场，交通很方便。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪下得很大，交通都停了。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个岛的交通靠船和飞机。", "target_word": "交通", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大城市的交通比小城市方便多了。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为有高铁，两个城市之间的交通方便多了。", "target_word": "交通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，山里的交通断了。", "target_word": "交通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我住的地方交通很好，坐车十分钟就到。", "target_word": "交通", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "交通工具", "label": "复合"}, {"form": "交通网", "label": "复合"}, {"form": "交通灯", "label": "复合"}], "register": "中性", "sense_fingerprint": "交通：车船飞机等运送人和货物的往来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eea9ae5a-a1c2-46b4-ba5e-281e3260ca2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22488, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "正确：“交通”指车船飞机等出行条件，与“不方便”和“一天只有两班车”相呼应。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指冷热阴晴，与班车的班次无关，“天气不方便”也不成立。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”说多少、增减，不能用“不方便”来形容。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”说高低、冷热，不能说“不方便”，也与班次无关。"}], "explanations": {"交通": "正确：“交通”指车船飞机等出行条件，与“不方便”和“一天只有两班车”相呼应。", "天气": "语义：“天气”指冷热阴晴，与班车的班次无关，“天气不方便”也不成立。", "人口": "搭配：“人口”说多少、增减，不能用“不方便”来形容。", "温度": "搭配：“温度”说高低、冷热，不能说“不方便”，也与班次无关。"}, "sentence_index": 0, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的交通很漂亮，穿出去很显眼。", "explanation": "这里应该用〈颜色〉。“交通”指出行条件，不能用来形容衣服的样子。"}, {"text": "这张桌子的交通很结实，能放下很多书。", "explanation": "这里应该用〈质地〉。“交通”指出行条件，不能用来形容桌子的牢固程度。"}, {"text": "这条交通很宽，两边种满了树。", "explanation": "这里应该用〈道路〉。“交通”不能用来形容宽窄，说路面的宽窄要用“道路”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22488, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交通", "is_correct": true, "explanation": "正确：“交通”指出行条件，与“方便”搭配，符合“大城市比小城市方便”的比较。"}, {"text": "物价", "is_correct": false, "explanation": "搭配：“物价”说高低和涨跌，不能用“方便”来比较。"}, {"text": "风景", "is_correct": false, "explanation": "语义：“风景”指景色，与出行是否方便无关。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”指收入，不能说“方便”。"}], "explanations": {"交通": "正确：“交通”指出行条件，与“方便”搭配，符合“大城市比小城市方便”的比较。", "物价": "搭配：“物价”说高低和涨跌，不能用“方便”来比较。", "风景": "语义：“风景”指景色，与出行是否方便无关。", "工资": "搭配：“工资”指收入，不能说“方便”。"}, "sentence_index": 6, "correct_answer": "交通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次的交通很高，每次比赛都能拿第一名。", "explanation": "这里应该用〈成绩〉。“交通”指出行条件，不能用来说成绩的高低。"}, {"text": "这次演讲的交通很精彩，大家都鼓掌。", "explanation": "这里应该用〈内容〉。“交通”指出行条件，不能用来形容演讲的好坏。"}, {"text": "这次交通的景色很美，我拍了很多照片。", "explanation": "这里应该用〈旅游〉。“交通”指出行条件，不能说“交通的景色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22488, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市交通得方便，地铁站离家很近。", "corrected_sentence": "这座城市交通很方便，地铁站离家很近。", "error_description": "用词错误：“交通很方便”中的“很”误写成“得”。“得”只用在动词或形容词后作补语，“交通”是名词，应用“很”修饰“方便”，正确是“交通很方便”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22488, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山里的交通的很不方便，去一趟要走三个小时。", "corrected_sentence": "山里的交通很不方便，去一趟要走三个小时。", "error_description": "多加了“的”：“交通”后面直接接“很不方便”，中间不用“的”；“山里的交通”中的“的”是正确的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01429ee5-a8ef-4b4e-825d-7d6444146557') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
