INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22490, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "这是一张写着汽车或火车几点出发和到达的纸。", "primary_collocate": null, "pronunciation": "shí kè biǎo", "ipa": "ʂɻ̩˧˥ kʰɤ˥˩ piɑʊ̯˨˩˦", "syllable_count": 3, "sentences": [{"text": "我手里有一张公交时刻表。", "target_word": "时刻表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "司机把时刻表贴在车门旁边。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸是去北京的火车时刻表。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在时刻表上画了一个圈。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把汽车时刻表给我看看。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我忘了带时刻表，不知道几点有车。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨把时刻表打湿了。", "target_word": "时刻表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小站的时刻表只有一页。", "target_word": "时刻表", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸在时刻表上找到了回家的车。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站门口可以免费拿时刻表。", "target_word": "时刻表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张时刻表", "label": "量词（张）"}, {"form": "一份时刻表", "label": "量词（份）"}], "register": "中性", "sense_fingerprint": "时刻表：写着车几点出发和到达的一张纸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3299c7cb-711f-45ac-8e59-3053bcf7ff57') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22490, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "时刻表", "is_correct": true, "explanation": "“公交时刻表”指写着公交出发和到达时间的纸，与“一张”搭配。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：“饼干”是食品，不能说“公交饼干”。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：“闹钟”是计时器具，不说“一张闹钟”，也不说“公交闹钟”。"}, {"text": "药膏", "is_correct": false, "explanation": "语义：“药膏”是外用药，与公交无关。"}], "explanations": {"时刻表": "“公交时刻表”指写着公交出发和到达时间的纸，与“一张”搭配。", "饼干": "语义：“饼干”是食品，不能说“公交饼干”。", "闹钟": "搭配：“闹钟”是计时器具，不说“一张闹钟”，也不说“公交闹钟”。", "药膏": "语义：“药膏”是外用药，与公交无关。"}, "sentence_index": 0, "correct_answer": "时刻表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在时刻表上点了一个菜。", "explanation": "这里应该用〈菜单〉。点菜要看菜单，时刻表只记车次的出发和到达时间，不列菜品。"}, {"text": "她在时刻表上记了一笔钱。", "explanation": "这里应该用〈账本〉。记账要用账本，时刻表记录的是车次时间，不记钱款。"}, {"text": "店员在时刻表上写了新价格。", "explanation": "这里应该用〈价目表〉。价目表列商品价格，时刻表列车次的出发和到达时间，不列价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22490, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时刻表", "is_correct": true, "explanation": "“时刻表”是纸张，可以被雨打湿，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”无形，不会被雨打湿。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是有形的东西，不能被雨打湿。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“打湿”只用于有形的物体，不能说打湿“时间”。"}], "explanations": {"时刻表": "“时刻表”是纸张，可以被雨打湿，与句意相符。", "空气": "语义：“空气”无形，不会被雨打湿。", "声音": "语义：“声音”不是有形的东西，不能被雨打湿。", "时间": "搭配：“打湿”只用于有形的物体，不能说打湿“时间”。"}, "sentence_index": 6, "correct_answer": "时刻表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给病人开了一张时刻表。", "explanation": "这里应该用〈药方〉。时刻表列的是交通时间，药方才是医生开的用药单。"}, {"text": "妈妈照着时刻表放了两勺盐。", "explanation": "这里应该用〈食谱〉。食谱写着做菜要放多少调料，时刻表只列车次的出发和到达时间。"}, {"text": "他翻开时刻表找朋友的电话。", "explanation": "这里应该用〈电话簿〉。电话簿记联系人的电话，时刻表只列车次的出发和到达时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我时刻表夹进了笔记本里。", "corrected_sentence": "我把时刻表夹进了笔记本里。", "error_description": "漏词错误：处置式“把”字漏掉，应说“把时刻表夹进”，不能直接说“时刻表夹进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我手里拿着一条时刻表。", "corrected_sentence": "我手里拿着一张时刻表。", "error_description": "量词误用：纸张应用量词“张”，不能用“条”，应说“一张时刻表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4161dc71-e777-4eb8-ac82-3bf498d69e25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
