INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22492, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队用的武器和工具。", "primary_collocate": null, "pronunciation": "jūn xiè", "ipa": "tɕyn˥ ɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "军械是军队使用的武器和工具。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士们每天都要擦拭军械。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批军械需要马上送到边防。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军队的军械越来越先进了。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻时在部队修理过军械。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人必须爱护自己的军械。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "仓库门口有人看守着军械。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂为军队生产各种军械。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "展览上有很多旧时代的军械。", "target_word": "军械", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "军械丢了，部队要认真调查。", "target_word": "军械", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "军械库", "label": "复合"}, {"form": "军械师", "label": "复合"}], "register": "书面", "sense_fingerprint": "军械：军队用的武器和工具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49bba9f8-aed1-4990-9f26-3d99a51e2b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22492, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "军械", "is_correct": true, "explanation": "军械（jūn xiè）指军队用的武器和工具，是正确答案。"}, {"text": "军界", "is_correct": false, "explanation": "jiè（第四声）与 xiè（第四声）声母不同（j 与 x），意思是军队方面的人士或圈子。"}, {"text": "军校", "is_correct": false, "explanation": "xiào 与 xiè 韵母不同，意思是军事院校。"}, {"text": "军鞋", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是军用的鞋。"}], "explanations": {"军械": "军械（jūn xiè）指军队用的武器和工具，是正确答案。", "军界": "jiè（第四声）与 xiè（第四声）声母不同（j 与 x），意思是军队方面的人士或圈子。", "军校": "xiào 与 xiè 韵母不同，意思是军事院校。", "军鞋": "xié（第二声）与 xiè（第四声）声调不同，意思是军用的鞋。"}, "sentence_index": null, "correct_answer": "军械"}, "level_3": {"options": [{"text": "军械", "is_correct": true, "explanation": "军械指军队使用的武器和装备，与句中“武器和工具”的定义一致。"}, {"text": "粮食", "is_correct": false, "explanation": "语义：粮食是食物，不是军队使用的武器和工具。"}, {"text": "军服", "is_correct": false, "explanation": "语义：军服是军人穿的衣服，不属于武器和工具。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“乐器”属于音乐用品，与“武器和工具”这一定义的指称范围不符。"}], "explanations": {"军械": "军械指军队使用的武器和装备，与句中“武器和工具”的定义一致。", "粮食": "语义：粮食是食物，不是军队使用的武器和工具。", "军服": "语义：军服是军人穿的衣服，不属于武器和工具。", "乐器": "搭配：“乐器”属于音乐用品，与“武器和工具”这一定义的指称范围不符。"}, "sentence_index": 0, "correct_answer": "军械"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们连队领到了一只军械。", "explanation": "这里应该用〈批〉。军械是成批的装备，“只”不能用于军械。"}, {"text": "这家饭店的厨房里军械很齐全。", "explanation": "这里应该用〈器具〉。军械指军队用的武器装备，饭店厨房里的用具应说“器具”。"}, {"text": "士兵背着一把军械巡逻。", "explanation": "这里应该用〈武器〉。军械指装备的总称，不指单件武器；背着的是具体武器，应说“武器”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "军械", "is_correct": true, "explanation": "军械是需要看守的武器装备，与“仓库门口有人看守”的语境相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被看守，仓库里也不存放空气，句意不通。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌是文学作品，不需要有人守在仓库门口看守。"}, {"text": "歌剧", "is_correct": false, "explanation": "搭配：“看守”一般不跟“歌剧”搭配，歌剧也不是仓库看守的对象。"}], "explanations": {"军械": "军械是需要看守的武器装备，与“仓库门口有人看守”的语境相符。", "空气": "语义：空气不能被看守，仓库里也不存放空气，句意不通。", "诗歌": "语义：诗歌是文学作品，不需要有人守在仓库门口看守。", "歌剧": "搭配：“看守”一般不跟“歌剧”搭配，歌剧也不是仓库看守的对象。"}, "sentence_index": 6, "correct_answer": "军械"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把军械吃掉了。", "explanation": "搭配不当：“吃”的对象应是食物，军械是武器装备，不能吃。"}, {"text": "这顿饭是用军械做的，味道很好。", "explanation": "军械不是食材，“用……做”的材料应是食物，这里的用法不成立。"}, {"text": "他读完了军械。", "explanation": "搭配不当：“读”的对象应是书籍或文字，军械不能读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些军械们已经修好了。", "corrected_sentence": "这些军械已经修好了。", "error_description": "“们”只能用于人，军械是物，不能加“们”，应说“这些军械”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把一条旧军械运回了仓库。", "corrected_sentence": "他们把一批旧军械运回了仓库。", "error_description": "量词错误：“军械”是成批的装备，应用“批”。“条”用于细长的东西，不能用于军械。正确说法：他们把一批旧军械运回了仓库。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
