INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22496, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "到处都是，很满。", "primary_collocate": null, "pronunciation": "bù mǎn", "ipa": "pu˥˩ man˨˩˦", "syllable_count": 2, "sentences": [{"text": "地图上布满红色的记号。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路面布满积水，车开得很慢。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里布满了小路。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户上布满了雨滴。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的手臂布满伤痕。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨房的地上布满了面粉。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙滩上布满了漂亮的贝壳。", "target_word": "布满", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山坡上布满着绿色的茶树。", "target_word": "布满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子的墙布满了青苔。", "target_word": "布满", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶上布满白雪，看起来很美。", "target_word": "布满", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "布满了", "label": "体标"}, {"form": "布满着", "label": "体标"}], "register": "中性", "sense_fingerprint": "布满：到处都是、很满", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49bba9f8-aed1-4990-9f26-3d99a51e2b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22496, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“记号”，句意不通。"}, {"text": "布满", "is_correct": true, "explanation": "“布满”指红色的记号遍布地图，与句意相合。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与地图无关，句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能喝“记号”。"}], "explanations": {"吃": "搭配：“吃”不能接“记号”，句意不通。", "布满": "“布满”指红色的记号遍布地图，与句意相合。", "唱": "语义：“唱”与地图无关，句意不通。", "喝": "搭配：“喝”的对象是饮料，不能喝“记号”。"}, "sentence_index": 0, "correct_answer": "布满"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里布满了笑声。", "explanation": "这里应该用〈充满〉。笑声、气氛这类抽象的东西要用充满；布满指实物遍布某处。"}, {"text": "屋子里布满了一个人。", "explanation": "这里应该用〈挤满〉。人多而拥挤要用挤满；布满指东西遍布，一个人不能布满。"}, {"text": "舞台上布满了青春。", "explanation": "这里应该用〈洋溢〉。青春、神采向外流露要用洋溢；布满指东西遍布表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22496, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象多为衣物、鞋袜，句中是贝壳遍布沙滩，不能用“穿”。"}, {"text": "布满", "is_correct": true, "explanation": "“布满”指贝壳遍布沙滩，与句意相合。"}, {"text": "熬", "is_correct": false, "explanation": "语义：“熬”是用火长时间煮，与沙滩上的贝壳无关。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”的对象是人能跨坐的交通工具或动物，不能骑贝壳。"}], "explanations": {"穿": "搭配：“穿”的对象多为衣物、鞋袜，句中是贝壳遍布沙滩，不能用“穿”。", "布满": "“布满”指贝壳遍布沙滩，与句意相合。", "熬": "语义：“熬”是用火长时间煮，与沙滩上的贝壳无关。", "骑": "搭配：“骑”的对象是人能跨坐的交通工具或动物，不能骑贝壳。"}, "sentence_index": 6, "correct_answer": "布满"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山谷里布满了歌声。", "explanation": "这里应该用〈回荡〉。歌声在空间里往复传播用回荡；布满指实物遍布某处。"}, {"text": "墙上布满了几幅画。", "explanation": "这里应该用〈挂〉。墙上挂着几幅画；布满指大量东西遍布，几幅画不能说布满。"}, {"text": "桌子上布满了一个苹果。", "explanation": "这里应该用〈放着〉。桌上只有一个苹果用放着；布满指大量东西遍布某处，一个苹果不能布满。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22496, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路边布满在小花。", "corrected_sentence": "路边布满了小花。", "error_description": "“布满”后面不能接“在”，应直接带宾语。错误在于“布满在”；正确说法：路边布满了小花。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22496, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖边很布满了芦苇。", "corrected_sentence": "湖边布满了芦苇。", "error_description": "“很”不能修饰动词“布满”，应去掉“很”。正确说法：湖边布满了芦苇。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
