INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22498, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "单独的一个人，与集体相对。", "primary_collocate": null, "pronunciation": "gè rén", "ipa": "kɤ˥˩ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "这是我个人的看法，不一定对。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "个人的力量很小，大家一起才有用。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事不为个人打算，只为大家着想。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是个人的事，请你不要问。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司和个人都要交税。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在表格上写好你的个人信息。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电脑是我个人的，不是公司的。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画画是他的个人爱好，和工作没有关系。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不由集体决定，应由个人负责。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个人的成绩很好，可是队伍输了。", "target_word": "个人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个人信息", "label": "复合"}, {"form": "个人电脑", "label": "复合"}, {"form": "個人", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词：单独的一个人，与集体相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4db7646-0948-40ca-93a1-22bf840509fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22498, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集体", "is_correct": false, "explanation": "语义：“集体”指一群人组成的团体，与“我”的单独看法不合，句子说不通。"}, {"text": "个人", "is_correct": true, "explanation": "“个人”指单独的一个人，与“我”的看法相符，正好修饰“看法”。"}, {"text": "大众", "is_correct": false, "explanation": "语义：“大众”指广大群众，与“我”指说话人一个人的语境冲突，不能修饰“看法”。"}, {"text": "鄙人", "is_correct": false, "explanation": "语域：“鄙人”是文言式的自谦，与口语化的“我”重复，不合语域。"}], "explanations": {"集体": "语义：“集体”指一群人组成的团体，与“我”的单独看法不合，句子说不通。", "个人": "“个人”指单独的一个人，与“我”的看法相符，正好修饰“看法”。", "大众": "语义：“大众”指广大群众，与“我”指说话人一个人的语境冲突，不能修饰“看法”。", "鄙人": "语域：“鄙人”是文言式的自谦，与口语化的“我”重复，不合语域。"}, "sentence_index": 0, "correct_answer": "个人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天七点半去个人上班。", "explanation": "这里应该用〈单位〉。〈单位〉指工作的机构，是上班的地方；“个人”指单独的一个人，不能作上班的场所。"}, {"text": "我把个人放进了冰箱。", "explanation": "这里应该用〈牛奶〉。“个人”指单独的一个人，不是能放进冰箱的东西。"}, {"text": "他每天骑车去个人读书。", "explanation": "这里应该用〈学校〉。〈学校〉是读书的地方；“个人”指单独的一个人，不能作读书的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22498, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "团体", "is_correct": false, "explanation": "语义：“团体”指一群人组成的组织，“我团体的”说不通，与“我”冲突。"}, {"text": "公家", "is_correct": false, "explanation": "搭配：“公家”指国家或公共机构，不能说“我公家的”。"}, {"text": "个人", "is_correct": true, "explanation": "“个人”指自己单独所有，与“不是公司的”形成对照，正好。"}, {"text": "本座", "is_correct": false, "explanation": "语域：“本座”是戏谑或古语的自称，与口语的“我”重复，不合语域。"}], "explanations": {"团体": "语义：“团体”指一群人组成的组织，“我团体的”说不通，与“我”冲突。", "公家": "搭配：“公家”指国家或公共机构，不能说“我公家的”。", "个人": "“个人”指自己单独所有，与“不是公司的”形成对照，正好。", "本座": "语域：“本座”是戏谑或古语的自称，与口语的“我”重复，不合语域。"}, "sentence_index": 6, "correct_answer": "个人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事要靠个人齐心协力才能做成。", "explanation": "这里应该用〈众人〉。〈齐心协力〉需要多人一起出力，“个人”只指单独一人，不能与之搭配。"}, {"text": "个人一起商量一下吧。", "explanation": "这里应该用〈大家〉。〈一起商量〉需要多人参与，“个人”只指单独一人，说“个人一起商量”不通。"}, {"text": "个人一起唱歌，声音很好听。", "explanation": "这里应该用〈全班同学〉。〈一起唱歌〉指多人同唱，“个人”只指单独一人，不能与〈一起〉搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我个人们的意见，大家可以不同意。", "corrected_sentence": "这是我个人的意见，大家可以不同意。", "error_description": "错误：在“个人”后加了复数词尾“们”，“个人们”不成词。正确：“个人”指单独的一个人，不加“们”，应说“我个人的意见”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校的奖学金按个人们成绩发放。", "corrected_sentence": "学校的奖学金按个人成绩发放。", "error_description": "错误：在“个人”后加了复数词尾“们”，“个人们”不成词。正确：“个人”本身表示单独的人，不加“们”；要表示多人时应说“每个人”或“大家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b030c7fd-9e3d-430e-86a3-703bdd315418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
