INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22500, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22500, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "负责安排、照看人或事物，使其有秩序。", "primary_collocate": null, "pronunciation": "guǎn lǐ", "ipa": "kuan˨˩ li˨˩", "syllable_count": 2, "sentences": [{"text": "他管理着一家小公司。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把家里的钱管理得很好。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校需要有人管理图书馆。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要学会管理自己的时间。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个超市由王经理管理。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让他管理班里的书。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很会管理手下的人。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她管理仓库已经五年了。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区由物业公司管理。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要好好管理自己的钱。", "target_word": "管理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "管理着", "label": "体标"}, {"form": "管理过", "label": "体标"}, {"form": "管理员", "label": "复合"}, {"form": "管理者", "label": "复合"}], "register": "中性", "sense_fingerprint": "管理：动词，负责安排、照看人或事物，使其有秩序", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '06ef7b24-878b-4d84-b099-4f00efa873d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22500, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理", "is_correct": true, "explanation": "“管理着一家小公司”指负责经营、安排公司的事务，符合语境。"}, {"text": "浇", "is_correct": false, "explanation": "语义：“浇”指往植物或地面上泼水，公司不能被浇。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚碰击，不能用来指经营公司。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：“饲养”用于动物，不能用来说饲养一家公司。"}], "explanations": {"管理": "“管理着一家小公司”指负责经营、安排公司的事务，符合语境。", "浇": "语义：“浇”指往植物或地面上泼水，公司不能被浇。", "踢": "语义：“踢”是用脚碰击，不能用来指经营公司。", "饲养": "搭配：“饲养”用于动物，不能用来说饲养一家公司。"}, "sentence_index": 0, "correct_answer": "管理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把坏掉的自行车管理好了。", "explanation": "这里应该用〈修理〉。“管理”指安排、照看人或事务，使其有秩序，不用来修复坏了的东西。"}, {"text": "他每天管理这辆公交车上班。", "explanation": "这里应该用〈驾驶〉。“管理”用于人员和事务，不用来说操纵车辆。"}, {"text": "他很快管理完了这顿午饭。", "explanation": "这里应该用〈吃〉。“管理”指安排和负责事务，不用于吃饭这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22500, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理", "is_correct": true, "explanation": "“很会管理手下的人”说善于安排、带领下属，符合语境。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”指给人或动物送食物，不能用来指安排员工。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”是用刀把物体分开，不能用于人。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是用火加热食物，不能用于人。"}], "explanations": {"管理": "“很会管理手下的人”说善于安排、带领下属，符合语境。", "喂": "语义：“喂”指给人或动物送食物，不能用来指安排员工。", "切": "语义：“切”是用刀把物体分开，不能用于人。", "烤": "语义：“烤”是用火加热食物，不能用于人。"}, "sentence_index": 6, "correct_answer": "管理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天管理生病的弟弟。", "explanation": "这里应该用〈照顾〉。“管理”指安排和负责事务，不用来说照料病人的日常护理。"}, {"text": "我们在音乐会上管理了美妙的歌曲。", "explanation": "这里应该用〈欣赏〉。“管理”不用于听或看艺术作品。"}, {"text": "妈妈在厨房管理菜，香味很浓。", "explanation": "这里应该用〈烧〉。“管理”不用于做菜的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22500, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把家里的账目管理很仔细。", "corrected_sentence": "他把家里的账目管理得很仔细。", "error_description": "“管理”后面要用“得”引出补语，应说“管理得很仔细”，不能直接说“管理很仔细”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22500, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这个仓库管理很有条理。", "corrected_sentence": "他把这个仓库管理得很有条理。", "error_description": "错误：“管理很有条理”。正确：“管理得很有条理”。动词“管理”后面带程度补语时要用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb0216fa-b14b-416d-8fa2-df579761035b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
