INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22502, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "导向就是告诉你要往哪里走。", "primary_collocate": null, "pronunciation": "dǎo xiàng", "ipa": "tɑʊ̯˨˩ ɕjɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "导向就是告诉你要往哪里走。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划有明确的导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习需要一个好的导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话给了我一个新导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有导向，大家不知道做什么。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的导向是让客户满意。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们的导向很清楚。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书给孩子正确的导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的导向能帮人少走弯路。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次会议确定了工作的导向。", "target_word": "导向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "導向", "label": "繁体"}], "register": "中性", "sense_fingerprint": "告诉人该往哪个方向走、做什么的指引", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49bba9f8-aed1-4990-9f26-3d99a51e2b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22502, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导向", "is_correct": true, "explanation": "导向就是指引方向的东西，与“告诉你要往哪里走”的定义一致。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色无法告诉人往哪里走，与定义不符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音一般不指引方向，不能作“告诉你要往哪里走”的主语。"}, {"text": "价格", "is_correct": false, "explanation": "配价：“告诉”需要能指引行动的主语，价格不能告诉人去哪里。"}], "explanations": {"导向": "导向就是指引方向的东西，与“告诉你要往哪里走”的定义一致。", "颜色": "语义：颜色无法告诉人往哪里走，与定义不符。", "声音": "语义：声音一般不指引方向，不能作“告诉你要往哪里走”的主语。", "价格": "配价：“告诉”需要能指引行动的主语，价格不能告诉人去哪里。"}, "sentence_index": 0, "correct_answer": "导向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不知道该往哪个导向走。", "explanation": "这里应该用〈方向〉。“导向”指引导的作用，不指空间的方位，问往哪里走应说“方向”。"}, {"text": "妈妈用导向擦窗户。", "explanation": "这里应该用〈抹布〉。导向是抽象的指引，不是清洁用具，擦窗户要用抹布之类的东西。"}, {"text": "这张桌子的导向很结实。", "explanation": "导向是抽象的指引，不指具体的物品，不能用来形容桌子的结实程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22502, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导向", "is_correct": true, "explanation": "导向指引导的方向，句中“老师给我们的导向”指老师给的指引，与“很清楚”搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：老师不会把年龄“给”学生，年龄也不是可以“很清楚”的指引。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”是可测量的数值，不说“很清楚”，也不是老师能给的东西。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”是感官属性，不是能给人指引的东西，句意不通。"}], "explanations": {"导向": "导向指引导的方向，句中“老师给我们的导向”指老师给的指引，与“很清楚”搭配。", "年龄": "语义：老师不会把年龄“给”学生，年龄也不是可以“很清楚”的指引。", "面积": "搭配：“面积”是可测量的数值，不说“很清楚”，也不是老师能给的东西。", "味道": "语义：“味道”是感官属性，不是能给人指引的东西，句意不通。"}, "sentence_index": 6, "correct_answer": "导向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议确定了一台导向。", "explanation": "这里不能用“台”。导向是抽象的引导，应说“一种导向”，“台”多用于机器设备。"}, {"text": "这次会议的导向是一张大桌子。", "explanation": "导向不指具体的家具或实物，不能说成一张桌子。"}, {"text": "我们要磨快这个导向。", "explanation": "搭配不当：“磨”一般接刀具、工具，导向是抽象的引导，不能磨快。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22502, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板的态度给了我们一只清楚的导向。", "corrected_sentence": "老板的态度给了我们一种清楚的导向。", "error_description": "量词错误：导向是抽象的引导，应说“一种导向”。“只”用于动物或成对的东西，不能用于导向。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22502, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次会议为我们提供了一块清楚的导向。", "corrected_sentence": "这次会议为我们提供了一种清楚的导向。", "error_description": "量词错误：导向是抽象的引导，应说“一种导向”。“块”用于成块的实物，不能用于导向。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '194fc819-bb7c-4295-93fa-168a5ae4d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
