INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情又快又好，不浪费时间和力气。", "primary_collocate": null, "pronunciation": "xiào lǜ", "ipa": "ɕjau˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "他工作效率很高。", "target_word": "效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上学习的效率比晚上高。", "target_word": "效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想提高做事的效率。", "target_word": "效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会太多会影响工作效率。", "target_word": "效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台新机器的效率很高。", "target_word": "效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要想办法提高效率。", "target_word": "效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做事效率很低，总是做不完。", "target_word": "效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用电脑写报告，效率比手写高多了。", "target_word": "效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听着音乐学习，效率反而会变低。", "target_word": "效率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想用新方法提高生产效率。", "target_word": "效率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工作效率", "label": "复合"}, {"form": "学习效率", "label": "复合"}, {"form": "生产效率", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事又快又好、不浪费时间和力气的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，与“他工作”的做事快慢和质量不相关。"}, {"text": "效率", "is_correct": true, "explanation": "指做事又快又好、不浪费时间和力气的程度，正好说明他工作很有效率。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“湿度”指空气的潮湿程度，不能用来说人的工作，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”只描述人的身体高度，不能用来说工作，句意不通。"}], "explanations": {"颜色": "语义：“颜色”指色彩，与“他工作”的做事快慢和质量不相关。", "效率": "指做事又快又好、不浪费时间和力气的程度，正好说明他工作很有效率。", "湿度": "语义：“湿度”指空气的潮湿程度，不能用来说人的工作，句意不通。", "身高": "语义：“身高”只描述人的身体高度，不能用来说工作，句意不通。"}, "sentence_index": 0, "correct_answer": "效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这批饼干的效率很好。", "explanation": "这里应该用〈口感〉。效率指做事快慢和投入产出，食品好不好吃要用口感来说。"}, {"text": "这种药的效率很好，吃了两天就好了。", "explanation": "这里应该用〈效果〉。效率指做事快慢和投入产出，药物等作用的好坏要用效果。"}, {"text": "这辆车的效率很快。", "explanation": "这里应该用〈速度〉。效率侧重做事的投入产出，车的快慢要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "温度", "is_correct": false, "explanation": "语义：“温度”描述冷热，与做事快慢、浪费时间的语境不符。"}, {"text": "海拔", "is_correct": false, "explanation": "搭配：“海拔”只用于地点的高度，不能说“做事海拔很低”。"}, {"text": "效率", "is_correct": true, "explanation": "做事快慢和投入产出的程度，正好说明他做事效率低、总是做不完。"}, {"text": "密度", "is_correct": false, "explanation": "语义：“密度”指单位体积的质量，与做事的情况不相关。"}], "explanations": {"温度": "语义：“温度”描述冷热，与做事快慢、浪费时间的语境不符。", "海拔": "搭配：“海拔”只用于地点的高度，不能说“做事海拔很低”。", "效率": "做事快慢和投入产出的程度，正好说明他做事效率低、总是做不完。", "密度": "语义：“密度”指单位体积的质量，与做事的情况不相关。"}, "sentence_index": 6, "correct_answer": "效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对待工作的效率很认真，从不马虎。", "explanation": "这里应该用〈态度〉。效率指做事快而省力，对待工作的认真程度要用态度。"}, {"text": "两个城市的效率很远，坐车要三个小时。", "explanation": "这里应该用〈距离〉。效率指做事快慢和投入产出，两地的间隔要用距离。"}, {"text": "这盏台灯的效率很亮，桌上的书看得很清楚。", "explanation": "这里应该用〈亮度〉。效率指做事快慢和投入产出，灯光的明暗要用亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台旧机器的一个效率很低。", "corrected_sentence": "这台旧机器的效率很低。", "error_description": "量词错误：“效率”是抽象名词，不能用“一个”修饰，应说“这台旧机器的效率很低”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种方法得效率很高。", "corrected_sentence": "这种方法的效率很高。", "error_description": "“得”错误：“这种方法的效率”中修饰语后应用“的”，“得”只用于动词或形容词之后引出补语，应改为“的”，说“这种方法的效率很高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
