INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时制是说话时表示时间的方式。", "primary_collocate": null, "pronunciation": "shí zhì", "ipa": "ʂʅ˧˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "说话时用什么时制，要看事情是什么时候发生的。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这种语言里，过去和现在的时制不一样。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用错了时制，听起来像是明天的事。", "target_word": "时制", "complexity_tier": "T3", "furigana": "tā yòng cuò le shí zhì, tīng qǐ lái xiàng shì míng tiān de shì.", "sentence_source": "generated"}, {"text": "学会用时制，才能把时间说清楚。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话的时制是过去，不是现在。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子学说话时，慢慢会用不同的时制。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：这句话用了什么时制？", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每种语言表示时制的方法都不同。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用错时制，别人会不知道事情什么时候发生。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在练习英语的现在时制。", "target_word": "时制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "时制变化", "label": "复合"}], "register": "书面", "sense_fingerprint": "说话时表示时间的方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8713ac1f-a53c-4b6b-b983-39b9e43e1163') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22520, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指说话时表示时间的方式，是听到的词。"}, {"text": "食指", "is_correct": false, "explanation": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指」"}, {"text": "石柱", "is_correct": false, "explanation": "「zhù 与 zhì 韵母不同（u 与 i），意思是石头做的柱子」"}, {"text": "十字", "is_correct": false, "explanation": "「zì 与 zhì 声母不同（z 与 zh），意思是十字形」"}], "explanations": {"时制": "时制指说话时表示时间的方式，是听到的词。", "食指": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是食指」", "石柱": "「zhù 与 zhì 韵母不同（u 与 i），意思是石头做的柱子」", "十字": "「zì 与 zhì 声母不同（z 与 zh），意思是十字形」"}, "sentence_index": null, "correct_answer": "时制"}, "level_3": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指说话时表示时间的方式，与“用什么……，要看事情是什么时候发生的”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：说话时不能用“颜色”来表示时间的方式。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：说话时用“乐器”与表示时间的方式无关。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“用什么体重”搭配不当，“体重”不能作为说话的方式。"}], "explanations": {"时制": "时制指说话时表示时间的方式，与“用什么……，要看事情是什么时候发生的”相符。", "颜色": "语义：说话时不能用“颜色”来表示时间的方式。", "乐器": "语义：说话时用“乐器”与表示时间的方式无关。", "体重": "搭配：“用什么体重”搭配不当，“体重”不能作为说话的方式。"}, "sentence_index": 0, "correct_answer": "时制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要珍惜时制，别浪费每一天。", "explanation": "这里应该用〈时间〉。时间可以珍惜，时制只是说话时表示时间的方式，不能珍惜。"}, {"text": "我们要抓住时制，不要错过。", "explanation": "这里应该用〈时机〉。时机指合适的机会，时制不能被抓住。"}, {"text": "我每天晚上有一个固定的时制用来背单词。", "explanation": "这里应该用〈时段〉。时段指一段固定的时间，时制是语法概念，不能指一段时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46355076-0f16-4370-8783-43b20948a35c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22520, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指说话时表示时间的方式，是听到的词。"}, {"text": "时事", "is_correct": false, "explanation": "「shì 与 zhì 声母不同（sh 与 zh），意思是时事新闻」"}, {"text": "市制", "is_correct": false, "explanation": "「shì（第四声）与 shí（第二声）声调不同，意思是旧式度量制度」"}, {"text": "十指", "is_correct": false, "explanation": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是十根手指」"}], "explanations": {"时制": "时制指说话时表示时间的方式，是听到的词。", "时事": "「shì 与 zhì 声母不同（sh 与 zh），意思是时事新闻」", "市制": "「shì（第四声）与 shí（第二声）声调不同，意思是旧式度量制度」", "十指": "「zhǐ（第三声）与 zhì（第四声）声调不同，意思是十根手指」"}, "sentence_index": null, "correct_answer": "时制"}, "level_3": {"options": [{"text": "时制", "is_correct": true, "explanation": "时制指说话时表示时间的方式，与“这句话用了什么……”的问法相符。"}, {"text": "尺码", "is_correct": false, "explanation": "语义：“尺码”指衣物的大小，不能用来说明句子的时间表达。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”说的是物体的轻重，与句子的语法无关。"}, {"text": "手术", "is_correct": false, "explanation": "搭配：“用了什么手术”搭配不当，手术是医疗行为，不能用在句子表达上。"}], "explanations": {"时制": "时制指说话时表示时间的方式，与“这句话用了什么……”的问法相符。", "尺码": "语义：“尺码”指衣物的大小，不能用来说明句子的时间表达。", "重量": "语义：“重量”说的是物体的轻重，与句子的语法无关。", "手术": "搭配：“用了什么手术”搭配不当，手术是医疗行为，不能用在句子表达上。"}, "sentence_index": 6, "correct_answer": "时制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "美好的时制一去不复返。", "explanation": "这里应该用〈时光〉。时光指一段过去的时间，时制是表示时间方式的语法概念，不能一去不复返。"}, {"text": "挂在墙上的时制很准。", "explanation": "这里应该用〈时钟〉。时钟是计时的器具，时制不是计时器具。"}, {"text": "在这个时制，我想起了你。", "explanation": "这里应该用〈时刻〉。时刻指某一个时间点，时制不指时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46355076-0f16-4370-8783-43b20948a35c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.va