INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他已经学会着时制的用法。", "corrected_sentence": "他已经学会了时制的用法。", "error_description": "体标错误：“学会”表示已经掌握，应用“了”，不能用“着”。应说“学会了时制的用法”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46355076-0f16-4370-8783-43b20948a35c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学外语时，我们要弄清楚每位时制的用法。", "corrected_sentence": "学外语时，我们要弄清楚每种时制的用法。", "error_description": "量词错误：“位”用于人，“时制”是抽象的语法范畴，应用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46355076-0f16-4370-8783-43b20948a35c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
