INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商务就是买卖东西的事情。", "primary_collocate": null, "pronunciation": "shāng wù", "ipa": "ʂɑŋ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "他常年在外面忙商务。", "target_word": "商务", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我爸爸从事商务工作，常年在外地跟客户打交道。", "target_word": "商务", "complexity_tier": "T3", "furigana": "wǒ bàba cóngshì shāngwù gōngzuò, chángnián zài wàidì gēn kèhù dǎ jiāodao.", "sentence_source": "generated"}, {"text": "这次出国是为了商务，不是玩。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们因为商务常常一起吃饭。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很懂商务，会跟人谈价钱。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚学会一点商务知识。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这几天商务很多，没有时间回家。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学习商务，以后自己开店。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他精通商务，把公司经营得很好，赚了很多钱。", "target_word": "商务", "complexity_tier": "T3", "furigana": "tā jīngtōng shāngwù, bǎ gōngsī jīngyíng de hěn hǎo, zhuànle hěn duō qián.", "sentence_source": "generated"}, {"text": "这位先生来这里办商务。", "target_word": "商务", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "商务舱", "label": "复合"}, {"form": "商务英语", "label": "复合"}, {"form": "商務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "买卖东西的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaa78384-b965-4a67-9066-08a23a91de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：商务，shāng wù，指买卖东西的事情。"}, {"text": "上午", "is_correct": false, "explanation": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是上午。"}, {"text": "尚武", "is_correct": false, "explanation": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是崇尚武力。"}, {"text": "晌午", "is_correct": false, "explanation": "shǎng wu 与 shāng wù 声调不同，意思是中午，多用于口语。"}], "explanations": {"商务": "正确：商务，shāng wù，指买卖东西的事情。", "上午": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是上午。", "尚武": "shàng wǔ 与 shāng wù 两个音节的声调都不同，意思是崇尚武力。", "晌午": "shǎng wu 与 shāng wù 声调不同，意思是中午，多用于口语。"}, "sentence_index": null, "correct_answer": "商务"}, "level_3": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：“忙商务”指忙于买卖东西的事情，符合句意。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“忙”通常接事务，“忙感情”不自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以忙碌的事务，“忙天气”不通。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是事务，句中不能说忙海洋。"}], "explanations": {"商务": "正确：“忙商务”指忙于买卖东西的事情，符合句意。", "感情": "搭配：“忙”通常接事务，“忙感情”不自然。", "天气": "语义：天气不是可以忙碌的事务，“忙天气”不通。", "海洋": "语义：海洋不是事务，句中不能说忙海洋。"}, "sentence_index": 0, "correct_answer": "商务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的商务很好听。", "explanation": "这里应该用〈歌〉。商务指买卖东西的事情，不能用来形容歌曲好听。"}, {"text": "这幅画的商务很美。", "explanation": "这里应该用〈颜色〉。商务指买卖东西的事情，不指画面的色彩。"}, {"text": "那片草地的商务很香。", "explanation": "这里应该用〈花〉。商务指买卖东西的事情，不指花的香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商务", "is_correct": true, "explanation": "正确：“商务很多”指要处理的买卖事情多，所以没时间回家。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能说“很多”，也不会让人没时间回家。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是要处理的事情，句子说不通。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮只有一个，不能说“很多”，句子说不通。"}], "explanations": {"商务": "正确：“商务很多”指要处理的买卖事情多，所以没时间回家。", "天空": "语义：天空不能说“很多”，也不会让人没时间回家。", "海洋": "语义：海洋不是要处理的事情，句子说不通。", "月亮": "语义：月亮只有一个，不能说“很多”，句子说不通。"}, "sentence_index": 6, "correct_answer": "商务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商务哭了一下午。", "explanation": "这里应该用〈孩子〉。商务指买卖东西的事情，不能做“哭”的主语。"}, {"text": "商务在院子里跑。", "explanation": "这里应该用〈小狗〉。商务指买卖东西的事情，不能做“跑”的主语。"}, {"text": "他写的商务很美。", "explanation": "这里应该用〈诗〉。商务指买卖东西的事情，不指写出来供人欣赏的诗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常年在外地商务，很少回家。", "corrected_sentence": "他常年在外地做商务，很少回家。", "error_description": "宾语错误：“商务”作名词，前面要加动词“做”，应说“做商务”，不能直接说“在外地商务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22536, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他下个月去上海商务。", "corrected_sentence": "他下个月去上海谈商务。", "error_description": "缺少动词：“商务”是名词，不能直接作谓语，前面要加动词“谈”，应说“去上海谈商务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
