INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让时间或距离变得更长。", "primary_collocate": null, "pronunciation": "yán cháng", "ipa": "jɛn˧˥ ʈʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "老师把考试时间延长了十分钟。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在延长这条公路。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校延长了暑假。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了等客人，我们把晚饭的时间延长了一会儿。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆想延长开门时间，让学生多看书。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理同意延长我的试用期。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想延长这次旅行，多住三天。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水太宽，桥得再延长五十米。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把合同延长一年，好吗？", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "活动很受欢迎，所以主办方延长了展览时间。", "target_word": "延长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延长了", "label": "完成体"}, {"form": "延长过", "label": "经历体"}, {"form": "延长线", "label": "复合词"}], "register": "中性", "sense_fingerprint": "延长：让时间或距离变得更长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e41cf2-2347-44e6-8502-a9cbc2576a49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。延长 yán cháng：让时间或距离变得更长。"}, {"text": "羊肠", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（ang/an），羊肠指羊的肠子，常用于“羊肠小道”，不是延长。"}, {"text": "扬长", "is_correct": false, "explanation": "yáng 与 yán 韵母不同（ang/an），扬长意思是扬起，多用于“扬长而去”，不是延长。"}, {"text": "檐廊", "is_correct": false, "explanation": "láng 与 cháng 声母不同（l/ch），檐廊指房檐下的走廊，不是延长。"}], "explanations": {"延长": "正确。延长 yán cháng：让时间或距离变得更长。", "羊肠": "yáng 与 yán 韵母不同（ang/an），羊肠指羊的肠子，常用于“羊肠小道”，不是延长。", "扬长": "yáng 与 yán 韵母不同（ang/an），扬长意思是扬起，多用于“扬长而去”，不是延长。", "檐廊": "láng 与 cháng 声母不同（l/ch），檐廊指房檐下的走廊，不是延长。"}, "sentence_index": null, "correct_answer": "延长"}, "level_3": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。“把考试时间延长了十分钟”指让考试时间变长。"}, {"text": "收取", "is_correct": false, "explanation": "搭配：“收取”用于费用，不能说“收取时间”。"}, {"text": "摆脱", "is_correct": false, "explanation": "语义：“摆脱”指脱离某种束缚，时间不能被摆脱，句子说不通。"}, {"text": "剩下", "is_correct": false, "explanation": "语义：“剩下”指余下，不能表示让考试时间变长，“把考试时间剩下了十分钟”说不通。"}], "explanations": {"延长": "正确。“把考试时间延长了十分钟”指让考试时间变长。", "收取": "搭配：“收取”用于费用，不能说“收取时间”。", "摆脱": "语义：“摆脱”指脱离某种束缚，时间不能被摆脱，句子说不通。", "剩下": "语义：“剩下”指余下，不能表示让考试时间变长，“把考试时间剩下了十分钟”说不通。"}, "sentence_index": 0, "correct_answer": "延长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会议的效率延长了一倍。", "explanation": "这里应该用〈提高〉。延长指时间或距离的增加，效率的提升要用提高。"}, {"text": "学校延长了招生规模。", "explanation": "这里应该用〈扩大〉。延长只用于时间或距离，招生规模等范围的增大要用扩大。"}, {"text": "老师延长了我们的安全意识。", "explanation": "这里应该用〈加强〉。延长只用于时间或距离，安全意识等抽象能力的增强要用加强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延长", "is_correct": true, "explanation": "正确。“他想延长这次旅行，多住三天”表示让旅行时间变长。"}, {"text": "缩短", "is_correct": false, "explanation": "语义：“缩短旅行”与后文“多住三天”的意思相反。"}, {"text": "取消", "is_correct": false, "explanation": "语义：“取消旅行”就不会多住三天，与后文矛盾。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”多用于行李、房间，不说“收拾旅行”。"}], "explanations": {"延长": "正确。“他想延长这次旅行，多住三天”表示让旅行时间变长。", "缩短": "语义：“缩短旅行”与后文“多住三天”的意思相反。", "取消": "语义：“取消旅行”就不会多住三天，与后文矛盾。", "收拾": "搭配：“收拾”多用于行李、房间，不说“收拾旅行”。"}, "sentence_index": 6, "correct_answer": "延长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工厂的生产成本延长了三成。", "explanation": "这里应该用〈增加〉。延长只用于时间或距离，成本等数量的增加要用增加。"}, {"text": "寒流让房间的气温延长了五度。", "explanation": "这里应该用〈降低〉。气温的下降要用降低，延长只用于时间或距离。"}, {"text": "他的努力延长了成绩。", "explanation": "这里应该用〈提升〉。成绩的提高要用提升，延长只用于时间或距离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把晚会的时间延长十点。", "corrected_sentence": "我们把晚会的时间延长到十点。", "error_description": "错误：“十点”是时间点，不能直接作延长的时长补足语。表示延长后的终点要用“延长到……”，应为“延长到十点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22538, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们把这条公路延长了一条。", "corrected_sentence": "工人们把这条公路延长了一公里。", "error_description": "错误：表示延长距离的数量词应为“一公里”。“一条”是公路的量词，不能用来计量延长的长度。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
