INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22542, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情突然发生，让人来不及想。", "primary_collocate": null, "pronunciation": "tū rú qí lái", "ipa": "tʰu˥ ɻu˧˥ tɕʰi˧˥ laɪ˧˥", "syllable_count": 4, "sentences": [{"text": "突如其来的声音，让我吓了一跳。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他突如其来的一句话，让大家都安静了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛中突如其来的受伤，让他不能再跑了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突如其来的好消息，让她高兴得哭了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于这件突如其来的事，我一点准备也没有。", "target_word": "突如其来", "complexity_tier": "T3", "furigana": "duìyú zhè jiàn tū rú qí lái de shì, wǒ yìdiǎn zhǔnbèi yě méiyǒu.", "sentence_source": "generated"}, {"text": "突如其来的大风吹走了桌上的纸。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对突如其来的问题，他还没想好怎么回答。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突如其来的失败，让球队的队员很难过。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一件突如其来的事，让我们取消了旅行。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突如其来的一幕，让所有人都愣住了。", "target_word": "突如其来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "突如其來", "label": "繁体"}], "register": "书面", "sense_fingerprint": "突如其来：事情来得太快，让人来不及思考", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaa78384-b965-4a67-9066-08a23a91de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "突如其来", "is_correct": true, "explanation": "正确：突如其来说明声音出乎意料地突然出现，与「吓了一跳」相符。"}, {"text": "轻柔", "is_correct": false, "explanation": "语义：「轻柔」指声音柔和，与「吓了一跳」的惊吓反应相悖。"}, {"text": "舒缓", "is_correct": false, "explanation": "语义：「舒缓」指节奏慢、令人放松，与「吓了一跳」的突然感矛盾。"}, {"text": "精美", "is_correct": false, "explanation": "搭配：「精美」多修饰物品或工艺，不能用来修饰声音。"}], "explanations": {"突如其来": "正确：突如其来说明声音出乎意料地突然出现，与「吓了一跳」相符。", "轻柔": "语义：「轻柔」指声音柔和，与「吓了一跳」的惊吓反应相悖。", "舒缓": "语义：「舒缓」指节奏慢、令人放松，与「吓了一跳」的突然感矛盾。", "精美": "搭配：「精美」多修饰物品或工艺，不能用来修饰声音。"}, "sentence_index": 0, "correct_answer": "突如其来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他突如其来地一句一句把那件事讲完了。", "explanation": "这里应该用〈慢慢〉。突如其来指事情一下子发生，与「一句一句」逐步讲述相矛盾；逐步进行应说〈慢慢〉。"}, {"text": "我们提前一周就约定了见面时间，他却突如其来地到了。", "explanation": "这里应该用〈准时〉。突如其来指事情毫无预告地发生，与「提前一周就约定」相矛盾；按约定时间到达应说〈准时〉。"}, {"text": "我突如其来地很喜欢这座城市。", "explanation": "突如其来描述事情突然发生，不能修饰表示长期心理状态的「喜欢」；表示一直如此应用〈一直〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "突如其来", "is_correct": true, "explanation": "正确：突如其来说明问题来得突然，他来不及准备，符合「还没想好」的语境。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：「清脆」多形容声音，不能用来修饰「问题」。"}, {"text": "浓烈", "is_correct": false, "explanation": "搭配：「浓烈」多形容气味或感情，不能用来修饰「问题」。"}, {"text": "清澈见底", "is_correct": false, "explanation": "搭配：「清澈见底」形容水等透明，不能修饰「问题」。"}], "explanations": {"突如其来": "正确：突如其来说明问题来得突然，他来不及准备，符合「还没想好」的语境。", "清脆": "搭配：「清脆」多形容声音，不能用来修饰「问题」。", "浓烈": "搭配：「浓烈」多形容气味或感情，不能用来修饰「问题」。", "清澈见底": "搭配：「清澈见底」形容水等透明，不能修饰「问题」。"}, "sentence_index": 6, "correct_answer": "突如其来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都突如其来地去跑步。", "explanation": "突如其来指一次性出乎意料地发生，不能用于「每天都」这样反复的动作；表示反复应用〈经常〉。"}, {"text": "这篇文章是他用了一年时间突如其来地写完的。", "explanation": "这里应该用〈长期〉。突如其来指事情猝然发生，不能形容用了一年的漫长过程；这种持续多时的过程应说〈长期〉。"}, {"text": "他先查了很多资料，然后突如其来地写出了报告。", "explanation": "这里应该用〈认真〉。突如其来指事情毫无准备地发生，与「先查了很多资料」的准备过程相矛盾；经过准备的行动应说〈认真〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那封突如其来地信，让我一整天都心神不定。", "corrected_sentence": "那封突如其来的信，让我一整天都心神不定。", "error_description": "错误：「突如其来地信」；正确：「突如其来的信」。突如其来修饰名词时要用「的」，「地」只用于动词前作状语，不能用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一阵突如其来风，把窗户猛地吹开了。", "corrected_sentence": "一阵突如其来的风，把窗户猛地吹开了。", "error_description": "错误：「突如其来风」；正确：「突如其来的风」。突如其来修饰名词时，中间要加「的」，漏掉「的」不成词组。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
