INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22544, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话题就是大家在一起说话时，说的主要内容。", "primary_collocate": null, "pronunciation": "huà tí", "ipa": "xwa˥˩ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "吃饭时，大家的话题总是离不开孩子。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友聚会上，我们聊的话题很轻松。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一进门，话题就变成了他的新工作。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个话题大家都有兴趣，说了一个晚上。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶最爱的话题是她小时候的事。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的话题从音乐转到了旅行。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机成了年轻人聊天的常见话题。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王很会找话题，所以大家喜欢和他说话。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的话题越来越多，时间过得很快。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天的话题是怎么学好汉语。", "target_word": "话题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个话题", "label": "量词"}, {"form": "热门话题", "label": "复合"}, {"form": "話題", "label": "繁体"}], "register": "中性", "sense_fingerprint": "话题：大家聊天时说的主要内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eaa78384-b965-4a67-9066-08a23a91de72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22544, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "话题", "is_correct": true, "explanation": "正确：「话题」指大家谈论的内容，大家吃饭时总在谈孩子，符合句意。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：「饭菜」是吃的东西，不能成为大家总是离不开的谈论对象。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：「座位」指坐的位置，不能与「离不开孩子」搭配。"}, {"text": "字体", "is_correct": false, "explanation": "搭配：「字体」是书写的样式，不能指大家谈论的内容。"}], "explanations": {"话题": "正确：「话题」指大家谈论的内容，大家吃饭时总在谈孩子，符合句意。", "饭菜": "语义：「饭菜」是吃的东西，不能成为大家总是离不开的谈论对象。", "座位": "搭配：「座位」指坐的位置，不能与「离不开孩子」搭配。", "字体": "搭配：「字体」是书写的样式，不能指大家谈论的内容。"}, "sentence_index": 0, "correct_answer": "话题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边吃饭，一边打听这个话题的地址。", "explanation": "话题是抽象的谈论内容，没有地址；询问位置应指〈地点〉，这里与话题的语义不合。"}, {"text": "这个话题的颜色很鲜艳，大家都愿意看。", "explanation": "话题是抽象的谈论内容，没有颜色；描述颜色应指〈物品〉，这里与话题的语义不合。"}, {"text": "他把话题放进了书包里。", "explanation": "话题是抽象的谈论内容，不能当作〈物品〉放进书包，与「放进」的具体动作矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22544, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话题", "is_correct": true, "explanation": "正确：「话题」指聊天时说的内容，手机成为年轻人常谈的内容，符合句意。"}, {"text": "动作", "is_correct": false, "explanation": "语义：「动作」指身体的动作，不是聊天时说的内容。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：「饮料」指饮用的东西，不能作为聊天的内容。"}, {"text": "招牌", "is_correct": false, "explanation": "搭配：「招牌」指店铺的标志，不能与「聊天的常见」搭配。"}], "explanations": {"话题": "正确：「话题」指聊天时说的内容，手机成为年轻人常谈的内容，符合句意。", "动作": "语义：「动作」指身体的动作，不是聊天时说的内容。", "饮料": "语义：「饮料」指饮用的东西，不能作为聊天的内容。", "招牌": "搭配：「招牌」指店铺的标志，不能与「聊天的常见」搭配。"}, "sentence_index": 6, "correct_answer": "话题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "话题明天要去学校上课。", "explanation": "话题是谈论的内容，不能作「去」的主语，这里的主语应是人，应用〈我们〉。"}, {"text": "这个话题的价格很便宜。", "explanation": "话题是谈论的内容，不是〈商品〉，没有价格，与「便宜」的语义不合。"}, {"text": "他用话题打了我一拳。", "explanation": "话题是抽象的谈论内容，不能当作〈物体〉用来打人，打人的工具应是具体物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22544, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都喜欢聊这张话题。", "corrected_sentence": "我们都喜欢聊这个话题。", "error_description": "错误：「这张话题」；正确：「这个话题」。话题用量词「个」，不用「张」，「张」多用于纸、桌子等平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22544, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家一说起这些话题们，就停不下来。", "corrected_sentence": "大家一说起这些话题，就停不下来。", "error_description": "错误：「话题们」；正确：「话题」。「们」一般只加在指人的名词或代词后，话题不指人，不能加「们」；表示多个时用「这些」等数量词即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04401943-6f25-420e-9520-2c47ff21b8fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
