INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22546, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西拉长或变大。", "primary_collocate": null, "pronunciation": "yán zhǎn", "ipa": "jɛn˧˥ ʈʂan˨˩˦", "syllable_count": 2, "sentences": [{"text": "工人把铁片延展成了长条。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金属很软，容易延展。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把面团慢慢延展开。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种布料可以向四面延展。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这块金子延展成薄片。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅把铜块延展得很薄。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根铜丝加热后更容易延展。", "target_word": "延展", "complexity_tier": "T3", "furigana": "zhè gēn tóng sī jiā rè hòu gèng róng yì yán zhǎn", "sentence_source": "generated"}, {"text": "你要把面皮延展到盘子那么大。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铝能延展成很细的丝。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把薄膜轻轻延展开，盖在盆上。", "target_word": "延展", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延展了", "label": "体标（了）"}, {"form": "延展着", "label": "体标（着）"}, {"form": "延展过", "label": "体标（过）"}, {"form": "延展性", "label": "复合"}], "register": "书面", "sense_fingerprint": "把金属、面团等物体拉长、压薄或展开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f51b7060-190e-43be-9474-2cfe868f2248') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22546, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延展", "is_correct": true, "explanation": "正确。“把铁片延展成了长条”指通过拉、压使铁片展开变长，与句意一致。"}, {"text": "切碎", "is_correct": false, "explanation": "语义：“切碎”会得到碎块，不能切成一根长条，与句意不合。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能用来加工铁片，不说把铁片煮成长条。"}, {"text": "烘烤", "is_correct": false, "explanation": "搭配：“烘烤”多用于食品，不说烘烤铁片使其成为长条。"}], "explanations": {"延展": "正确。“把铁片延展成了长条”指通过拉、压使铁片展开变长，与句意一致。", "切碎": "语义：“切碎”会得到碎块，不能切成一根长条，与句意不合。", "煮": "搭配：“煮”用于食物，不能用来加工铁片，不说把铁片煮成长条。", "烘烤": "搭配：“烘烤”多用于食品，不说烘烤铁片使其成为长条。"}, "sentence_index": 0, "correct_answer": "延展"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把蛋糕延展成了三份。", "explanation": "这里应该用〈分〉。把东西分成若干份要用分；延展指拉长、压薄或展开，不表示分割。"}, {"text": "这家店的营业额延展了三成。", "explanation": "这里应该用〈增加〉。营业额、数量的增长要用增加，延展不用于数额的变化。"}, {"text": "她把布料延展成了三层。", "explanation": "这里应该用〈折叠〉。把布料叠起来形成层次要用折叠，延展指把物体拉长、压薄或展开，不用于叠合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22546, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延展", "is_correct": true, "explanation": "正确。“这根铜丝加热后更容易延展”指加热后金属变软，便于拉长、展开，与句意一致。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”是液体变成固体，与“加热后更容易”的常识相反，句子意思矛盾。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：加热不会使铜丝结冰，“结冰”与“加热后”的语境相矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”需要人作施事、歌曲作对象，铜丝不能作施事，不能说铜丝更容易唱。"}], "explanations": {"延展": "正确。“这根铜丝加热后更容易延展”指加热后金属变软，便于拉长、展开，与句意一致。", "凝固": "语义：“凝固”是液体变成固体，与“加热后更容易”的常识相反，句子意思矛盾。", "结冰": "语义：加热不会使铜丝结冰，“结冰”与“加热后”的语境相矛盾。", "唱": "配价：“唱”需要人作施事、歌曲作对象，铜丝不能作施事，不能说铜丝更容易唱。"}, "sentence_index": 6, "correct_answer": "延展"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的烹饪水平延展得很快。", "explanation": "这里应该用〈提高〉。水平、能力的上升要用提高，延展指物体被拉长、压薄或展开。"}, {"text": "他在晚会上延展了一首歌。", "explanation": "这里应该用〈唱〉。唱歌要用唱；延展指把金属、面团等物体拉长、压薄或展开，不能用于歌曲。"}, {"text": "她把面团用力延展成了碎块。", "explanation": "这里应该用〈切碎〉。把面团或物体切成小块要用切碎，延展指拉长或展开，不表示分割成碎块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22546, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把钢条延展给了细丝。", "corrected_sentence": "工人把钢条延展成了细丝。", "error_description": "错误：“延展给了细丝”，“给”不能表示变成的结果，应说“延展成了细丝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22546, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块铝箔延展很薄。", "corrected_sentence": "这块铝箔延展得很薄。", "error_description": "错误：“延展很薄”，正确：“延展得很薄”。“延展”后接表示程度的补语，要用“得”连接，漏掉“得”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb8b5ac8-0f38-4132-9264-c2063c12f1d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
