INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22548, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爸爸、妈妈和孩子住在一起，就是家庭。", "primary_collocate": null, "pronunciation": "jiā tíng", "ipa": "tɕja˥ tʰiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我的家庭有四个人。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他来自一个幸福的家庭。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家庭很小，只有爸爸和孩子。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在一个普通的家庭。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个家庭都有自己的故事。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家庭的收入不高。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的家庭会让孩子快乐。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他结婚后有了自己的家庭。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸为了家庭，每天工作很久。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家庭有三个孩子，很热闹。", "target_word": "家庭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "户", "label": "量词"}, {"form": "大家庭", "label": "复合"}], "register": "中性", "sense_fingerprint": "由家人组成、住在一起的生活单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69273c12-942b-4785-8ed5-3d4f334825ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22548, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "家庭", "is_correct": true, "explanation": "正确：「家庭」是家人组成的生活单位，「有四个人」符合常识。"}, {"text": "国家", "is_correct": false, "explanation": "语义：「国家」指一个国家的全部人口，不可能只有四个人，与句意不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「体温」是身体的温度，不能用来数人。"}, {"text": "门牌", "is_correct": false, "explanation": "搭配：「门牌」是门上的标牌，不能用来说有几个人。"}], "explanations": {"家庭": "正确：「家庭」是家人组成的生活单位，「有四个人」符合常识。", "国家": "语义：「国家」指一个国家的全部人口，不可能只有四个人，与句意不符。", "体温": "搭配：「体温」是身体的温度，不能用来数人。", "门牌": "搭配：「门牌」是门上的标牌，不能用来说有几个人。"}, "sentence_index": 0, "correct_answer": "家庭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个家庭被大风刮倒了，大家只好搬走。", "explanation": "这里应该用〈房子〉。家庭指家人组成的集体，不会被大风刮倒，被刮倒的是房子。"}, {"text": "妈妈每天都做家庭。", "explanation": "这里应该用〈家务〉。家庭是家人组成的单位，不能用「做」来表示做家里的活。"}, {"text": "他有一座幸福的家庭。", "explanation": "这里应该用〈个〉。家庭用「个」或「户」计量，「座」用于建筑、山等，不能用来计量家庭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "家庭", "is_correct": true, "explanation": "正确：「好的家庭会让孩子快乐」，家庭的氛围影响孩子的情绪，符合常识。"}, {"text": "公式", "is_correct": false, "explanation": "语义：「公式」是数学或科学中的表达式，不会让孩子快乐，与句意不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：「好的体温」不能与「让孩子快乐」搭配，体温指身体的温度。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「身高」指人的高矮，不能说「好的身高会让孩子快乐」。"}], "explanations": {"家庭": "正确：「好的家庭会让孩子快乐」，家庭的氛围影响孩子的情绪，符合常识。", "公式": "语义：「公式」是数学或科学中的表达式，不会让孩子快乐，与句意不符。", "体温": "搭配：「好的体温」不能与「让孩子快乐」搭配，体温指身体的温度。", "身高": "搭配：「身高」指人的高矮，不能说「好的身高会让孩子快乐」。"}, "sentence_index": 6, "correct_answer": "家庭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张沙发是一个很舒服的家庭。", "explanation": "这里应该用〈家具〉。家庭指家人组成的集体，沙发属于家具，不能说成家庭。"}, {"text": "我们家最近买了一台新冰箱，是最好的家庭。", "explanation": "这里应该用〈家电〉。家庭不指电器，冰箱属于家电。"}, {"text": "这座老房子的家庭里种着很多花。", "explanation": "这里应该用〈庭院〉。家庭指人组成的集体，不是可以种花的场所，应说庭院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些家庭们都很幸福。", "corrected_sentence": "这些家庭都很幸福。", "error_description": "错误：「家庭」后面不能加「们」表示复数。应去掉「们」，说「这些家庭都很幸福」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两座家庭一起吃了晚饭。", "corrected_sentence": "两个家庭一起吃了晚饭。", "error_description": "错误：量词「座」用错。「座」用于建筑、山等，不能计量家庭；应改为「个」，说「两个家庭」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '481e0cff-a7eb-4973-a68d-56a78f76da40') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
