INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西上有一点小小的不好，像一个小点点。", "primary_collocate": null, "pronunciation": "xiá cī", "ipa": "ɕjä˧˥ tsʰɨ˥", "syllable_count": 2, "sentences": [{"text": "这件衣服有一点瑕疵，便宜卖。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块玉上有一个小瑕疵。", "target_word": "瑕疵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "杯子表面有个小黑点，是瑕疵。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他仔细检查桌面，没有发现瑕疵。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些苹果有瑕疵，所以不贵。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片上的瑕疵可以用软件去掉。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把有瑕疵的产品放到一边。", "target_word": "瑕疵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这面镜子很干净，一点瑕疵也没有。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买瓷碗时，我会看碗边有没有瑕疵。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙上有几处小瑕疵，需要重新刷漆。", "target_word": "瑕疵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处瑕疵", "label": "量词"}, {"form": "瑕疵品", "label": "复合"}], "register": "书面", "sense_fingerprint": "瑕疵：物品表面上的小斑点、小毛病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e41cf2-2347-44e6-8502-a9cbc2576a49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "瑕疵", "is_correct": true, "explanation": "正确：“有一点瑕疵”指衣服上的小毛病，与“便宜卖”的原因相符。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：“便宜卖”说的是商品，学历不能卖。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是商品的属性，也没有“便宜”之说。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身体特征，衣服上不会有身高。"}], "explanations": {"瑕疵": "正确：“有一点瑕疵”指衣服上的小毛病，与“便宜卖”的原因相符。", "学历": "搭配：“便宜卖”说的是商品，学历不能卖。", "心情": "语义：心情不是商品的属性，也没有“便宜”之说。", "身高": "体貌：身高是人的身体特征，衣服上不会有身高。"}, "sentence_index": 0, "correct_answer": "瑕疵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的瑕疵很鲜。", "explanation": "这里应该用〈味道〉。味道指食物的滋味，可以说“很鲜”；瑕疵是东西上的小缺点，不能用来形容食物的滋味。"}, {"text": "屏幕的瑕疵太高，刺眼睛。", "explanation": "这里应该用〈亮度〉。亮度指光线的明暗，可以说“太高”；瑕疵是东西上的小缺点，不能用来形容光线的明暗。"}, {"text": "这箱苹果的瑕疵是十公斤。", "explanation": "这里应该用〈重量〉。重量指物体的轻重，可以说“是十公斤”；瑕疵是小缺点，不能用来计量重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "瑕疵", "is_correct": true, "explanation": "正确：“有瑕疵的产品”指有小缺陷的产品，句中只有这个词能用。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：产品没有年龄，“有年龄的产品”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“有……的产品”说产品的性质，工资不是产品的属性。"}, {"text": "籍贯", "is_correct": false, "explanation": "语义：籍贯是人的出生地，产品不具备籍贯。"}], "explanations": {"瑕疵": "正确：“有瑕疵的产品”指有小缺陷的产品，句中只有这个词能用。", "年龄": "语义：产品没有年龄，“有年龄的产品”说不通。", "工资": "搭配：“有……的产品”说产品的性质，工资不是产品的属性。", "籍贯": "语义：籍贯是人的出生地，产品不具备籍贯。"}, "sentence_index": 6, "correct_answer": "瑕疵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座桥上昨天发生了一起瑕疵，幸好没有人受伤。", "explanation": "这里应该用〈事故〉。“发生”搭配事故；瑕疵是物品上的小缺陷，不能“发生”。"}, {"text": "他跑步的瑕疵很快，一下子就跑远了。", "explanation": "这里应该用〈速度〉。速度指快慢的程度，可以说“很快”；瑕疵是东西上的小缺陷，不能用来形容跑步的快慢。"}, {"text": "两人之间发生了一场瑕疵，谁也不肯让步。", "explanation": "这里应该用〈争吵〉。“发生”可以搭配争吵；瑕疵不能指两人之间的冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块布有一下瑕疵，价格便宜。", "corrected_sentence": "这块布有一点瑕疵，价格便宜。", "error_description": "量词错误：“下”是动量词，多用于动作次数，不能用来计量名词“瑕疵”，应说“一点瑕疵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只杯子有一张小瑕疵，还能用。", "corrected_sentence": "这只杯子有一个小瑕疵，还能用。", "error_description": "量词错误：“瑕疵”应用量词“个”或“处”，说“一个小瑕疵”，不能用“张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22552, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确。“独立”与“依存”意思相反，指不靠他人而存在。"}, {"text": "讨论", "is_correct": false, "explanation": "无关：“讨论”指交换意见，与依赖关系没有对立关系。"}, {"text": "烧饭", "is_correct": false, "explanation": "无关：“烧饭”指做饭，与依赖关系没有对立关系。"}, {"text": "观看", "is_correct": false, "explanation": "无关：“观看”指看，与依赖关系没有对立关系。"}], "correct_answer": "独立", "explanations": {"独立": "正确。“独立”与“依存”意思相反，指不靠他人而存在。", "讨论": "无关：“讨论”指交换意见，与依赖关系没有对立关系。", "烧饭": "无关：“烧饭”指做饭，与依赖关系没有对立关系。", "观看": "无关：“观看”指看，与依赖关系没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22552, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "独立", "is_correct": true, "explanation": "正确。“独立”与“依存”意思相反，指不靠他人而存在。"}, {"text": "收集", "is_correct": false, "explanation": "无关：“收集”指聚集、搜罗，与依赖关系没有对立关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无关：“打扫”指清除脏物，与依赖关系没有对立关系。"}, {"text": "画画", "is_correct": false, "explanation": "无关：“画画”指绘制图画，与依赖关系没有对立关系。"}], "correct_answer": "独立", "explanations": {"独立": "正确。“独立”与“依存”意思相反，指不靠他人而存在。", "收集": "无关：“收集”指聚集、搜罗，与依赖关系没有对立关系。", "打扫": "无关：“打扫”指清除脏物，与依赖关系没有对立关系。", "画画": "无关：“画画”指绘制图画，与依赖关系没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22552, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人或事物离不开另一个，需要靠它才能存在。", "primary_collocate": null, "pronunciation": "yī cún", "ipa": "i˥ tsʰuən˧˥", "syllable_count": 2, "sentences": [{"text": "孩子在小时候依存于父母。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人晚年依存于子女的照顾。", "target_word": "依存", "complexity_tier": "T3", "furigana": "yī cún", "sentence_source": "generated"}, {"text": "这种花只能依存于大树生长。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的经济依存于出口贸易。", "target_word": "依存", "complexity_tier": "T3", "furigana": "yī cún", "sentence_source": "generated"}, {"text": "小镇的经济依存于这家工厂。", "target_word": "依存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座小城依存于附近的煤矿。", "target_word": "依存", "complexity_tier": "T3", "furigana": "yī cún", "sentence_source": "generated"}, {"text": "幼苗依存于大树的庇护，才能慢慢长大。", "target_word": "依存", "complexity_tier": "T3", "furigana": "yī cún", "sentence_source": "generated"}, {"text": "这个村子依存于一条小河，没有河就没有水。", "target_word": "依存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗依存于主人，独自在家时总会很不安。", "target_word": "依存", "complexity_tier": "T3", "furigana": "yī cún", "sentence_source": "generated"}, {"text": "藤蔓依存于老树才能向上生长。", "target_word": "依存", "complexity_tier": "T3", "furigana": "yī cún", "sentence_source": "generated"}], "morphological_forms": [{"form": "依存着", "label": "体标"}, {"form": "相互依存", "label": "复合"}, {"form": "依存关系", "label": "复合"}], "register": "书面", "sense_fingerprint": "依存：一方离不开另一方，靠对方才能生存", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e41cf2-2347-44e6-8502-a9cbc2576a49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22552, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "依存", "is_correct": true, "explanation": "正确。依存（yī cún）：一方离不开另一方，需要靠它才能存在。"}, {"text": "一群", "is_correct": false, "explanation": "q 与 c 声母不同（qún / cún），意思是一群，不是依存。"}, {"text": "一寸", "is_correct": false, "explanation": "cùn 与 cún 声调不同，意思是一寸长度，与“依存”不同。"}, {"text": "遗存", "is_correct": false, "explanation": "yí 与 yī 声调不同（yí cún），意思是遗留下来的东西，与“依存”不同。"}, {"text": "一村", "is_correct": false, "explanation": "cūn 与 cún 声调不同，指一个村子，与“依存”不同。"}], "explanations": {"依存": "正确。依存（yī cún）：一方离不开另一方，需要靠它才能存在。", "一群": "q 与 c 声母不同（qún / cún），意思是一群，不是依存。", "一寸": "cùn 与 cún 声调不同，意思是一寸长度，与“依存”不同。", "遗存": "yí 与 yī 声调不同（yí cún），意思是遗留下来的东西，与“依存”不同。", "一村": "cūn 与 cún 声调不同，指一个村子，与“依存”不同。"}, "sentence_index": null, "correct_answer": "依存"}, "level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "正确。“依存于父母”指孩子在生活上离不开父母，需要靠父母才能生存。"}, {"text": "讲述", "is_correct": false, "explanation": "搭配：“讲述”的对象是故事或内容，不能说“讲述于父母”。"}, {"text": "投资", "is_correct": false, "explanation": "语义：“投资”指投入资金，与孩子对父母的生存依靠无关，句子不通。"}, {"text": "怀念", "is_correct": false, "explanation": "配价：“怀念”直接带宾语，不带“于”，与“孩子在小时候……于父母”的结构不符。"}], "explanations": {"依存": "正确。“依存于父母”指孩子在生活上离不开父母，需要靠父母才能生存。", "讲述": "搭配：“讲述”的对象是故事或内容，不能说“讲述于父母”。", "投资": "语义：“投资”指投入资金，与孩子对父母的生存依靠无关，句子不通。", "怀念": "配价：“怀念”直接带宾语，不带“于”，与“孩子在小时候……于父母”的结构不符。"}, "sentence_index": 0, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他依存于墙角，闭着眼睛睡着了。", "explanation": "这里应该用〈靠〉（靠在墙角）。依存表示一方离不开另一方、需靠它才能存在，不表示身体倚靠。"}, {"text": "他的心事全都依存于那本日记上。", "explanation": "这里应该用〈寄托〉（寄托在日记上）。依存表示需靠它才能存在，不表示把心事托付给某物。"}, {"text": "这份计划依存于规定进行，不能随意改动。", "explanation": "这里应该用〈依照〉（依照规定进行）。依存表示需靠它才能存在，不表示遵照规定行事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "依存", "is_correct": true, "explanation": "正确。“幼苗依存于大树的庇护”指幼苗靠大树的庇护才能生存，符合定义。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”指仔细看，不能表示幼苗对大树庇护的依靠，句子不通。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热做饭，与幼苗和大树的庇护无关，句子不通。"}, {"text": "赞美", "is_correct": false, "explanation": "配价：“赞美”直接带宾语，不带“于”，说“幼苗赞美于大树的庇护”不通。"}], "explanations": {"依存": "正确。“幼苗依存于大树的庇护”指幼苗靠大树的庇护才能生存，符合定义。", "观察": "语义：“观察”指仔细看，不能表示幼苗对大树庇护的依靠，句子不通。", "煮": "语义：“煮”指用水加热做饭，与幼苗和大树的庇护无关，句子不通。", "赞美": "配价：“赞美”直接带宾语，不带“于”，说“幼苗赞美于大树的庇护”不通。"}, "sentence_index": 6, "correct_answer": "依存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们俩依存得很快，三分钟就吃完了饭。", "explanation": "这里应该用〈吃〉（吃得很快）。依存表示一方离不开另一方、需靠它才能存在，不表示进食的快慢。"}, {"text": "这件事依存于你来办，我很放心。", "explanation": "这里应该用〈托付〉（托付给你办）。依存表示离不开，不表示把事情交给别人办理。"}, {"text": "他依存于一把尺子，把桌子量得很准。", "explanation": "这里应该用〈借助〉（借助尺子量）。依存表示离不开、需靠它才能存在，不表示借助工具完成动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "刚出生的婴儿依存母亲的照顾。", "corrected_sentence": "刚出生的婴儿依存于母亲的照顾。", "error_description": "漏掉“于”：依存表示一方离不开另一方时，通常带“于”，应说“依存于母亲的照顾”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "幼苗依存老树才能慢慢长大。", "corrected_sentence": "幼苗依存于老树才能慢慢长大。", "error_description": "漏掉“于”：依存后接表示依靠的对象时通常带“于”，应说“依存于老树”，不说“依存老树”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
