INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22554, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "非法损害别人的权利、利益或领土。", "primary_collocate": null, "pronunciation": "qīn fàn", "ipa": "tɕʰin˥ fan˥˩", "syllable_count": 2, "sentences": [{"text": "别人的房间你不能随便进，这是侵犯隐私。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偷看别人的日记，就是侵犯别人的隐私。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家网站侵犯了很多用户的隐私。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律不允许任何人侵犯别人的权利。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别的国家的飞机不能随便侵犯我国的领空。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有同意就用别人的照片，侵犯了他的肖像权。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他抄了别人的书，侵犯了作者的版权。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要侵犯别人的自由。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队侵犯了邻国的边界。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能为了赚钱，侵犯孩子的利益。", "target_word": "侵犯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "动词，非法损害别人的权利、利益或领土", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28481438-1c53-4cd2-8bbb-0605e7c56396') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是地方，如博物馆、工厂，不能说“参观隐私”。"}, {"text": "侵犯", "is_correct": true, "explanation": "侵犯指非法损害他人的权利，“侵犯隐私”即损害别人的私人生活。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是房间、地面等具体场所，不能说“打扫隐私”。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是表演、影视等，不能与“隐私”搭配。"}], "explanations": {"参观": "搭配：“参观”的对象是地方，如博物馆、工厂，不能说“参观隐私”。", "侵犯": "侵犯指非法损害他人的权利，“侵犯隐私”即损害别人的私人生活。", "打扫": "搭配：“打扫”的对象是房间、地面等具体场所，不能说“打扫隐私”。", "观看": "搭配：“观看”的对象是表演、影视等，不能与“隐私”搭配。"}, "sentence_index": 0, "correct_answer": "侵犯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他多次闯红灯，侵犯了交通规则。", "explanation": "这里应该用〈违反〉。侵犯针对的是他人的权利和利益，不用于规则，应说“违反交通规则”。"}, {"text": "他说话太直接，侵犯了老师的面子。", "explanation": "这里应该用〈冒犯〉。说话得罪人应说“冒犯”，“侵犯”针对权利和利益，不用于面子。"}, {"text": "这种药会侵犯身体健康。", "explanation": "这里应该用〈损害〉。侵犯针对权利和利益，不用于身体健康，应说“损害健康”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：“保护”与“抄书”的行为相反，抄了别人的书不能说是保护作者的版权。"}, {"text": "侵犯", "is_correct": true, "explanation": "侵犯指损害他人的权利，“侵犯版权”即未经许可使用他人的作品。"}, {"text": "尊重", "is_correct": false, "explanation": "语义：“尊重”与“抄书”冲突，抄袭他人作品不能说是尊重版权。"}, {"text": "收藏", "is_correct": false, "explanation": "搭配：“收藏”的对象是物品或作品，不能与“版权”搭配。"}], "explanations": {"保护": "语义：“保护”与“抄书”的行为相反，抄了别人的书不能说是保护作者的版权。", "侵犯": "侵犯指损害他人的权利，“侵犯版权”即未经许可使用他人的作品。", "尊重": "语义：“尊重”与“抄书”冲突，抄袭他人作品不能说是尊重版权。", "收藏": "搭配：“收藏”的对象是物品或作品，不能与“版权”搭配。"}, "sentence_index": 6, "correct_answer": "侵犯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌侵犯了我的心情。", "explanation": "这里应该用〈影响〉。侵犯的对象是权利和利益，不能用于情绪，应说“这首歌影响了我的心情”。"}, {"text": "他一直大声说话，侵犯了我的耳朵。", "explanation": "这里应该用〈伤害〉。“侵犯”针对权利和利益，不用于身体器官，应说“伤害了我的耳朵”。"}, {"text": "他在超市侵犯了三瓶饮料。", "explanation": "这里应该用〈购买〉。在超市拿商品是正常交易，并不损害他人的权利，应说“他在超市购买了三瓶饮料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司没侵犯了员工的权益。", "corrected_sentence": "这家公司没侵犯员工的权益。", "error_description": "错误形式：“没侵犯了”；正确形式：“没侵犯”。否定句中“没”与动词“侵犯”搭配，动词后不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不有侵犯我的权利。", "corrected_sentence": "他没有侵犯我的权利。", "error_description": "错误形式：“不有侵犯”；正确形式：“没有侵犯”。“有”的否定形式是“没有”，不能说“不有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9378ac0a-55b1-4c6f-a355-5f5a5d8fb601') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
