INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "说话或做事时，周围的情况和背景。", "primary_collocate": null, "pronunciation": "yǔ jìng", "ipa": "y˨˩ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个词要放在语境里学。", "target_word": "语境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同一句话，在不同的语境里，意思可能不同。", "target_word": "语境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有语境，我听不懂这句话。", "target_word": "语境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，要根据语境选词。", "target_word": "语境", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "看了前后的语境，我才明白他的意思。", "target_word": "语境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个语境里，“老”不是说年纪大。", "target_word": "语境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子在真实的语境里学说话，进步很快。", "target_word": "语境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书的例句，给每个生词都提供了语境。", "target_word": "语境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脱离语境，这句话听起来很奇怪。", "target_word": "语境", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "翻译的时候，一定要想一想原文的语境。", "target_word": "语境", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "说话或做事时周围的情况和背景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22556, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语境", "is_correct": true, "explanation": "指说话或做事时周围的情况和背景，符合“放在……里学”的句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是家用电器，不能作为学习的环境或背景。"}, {"text": "口袋", "is_correct": false, "explanation": "语义：“口袋”是衣物的一部分，不能指学习时周围的情况。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：“抽屉”是家具的一部分，不能作为学习时周围的情况和背景。"}], "explanations": {"语境": "指说话或做事时周围的情况和背景，符合“放在……里学”的句意。", "冰箱": "语义：“冰箱”是家用电器，不能作为学习的环境或背景。", "口袋": "语义：“口袋”是衣物的一部分，不能指学习时周围的情况。", "抽屉": "语义：“抽屉”是家具的一部分，不能作为学习时周围的情况和背景。"}, "sentence_index": 0, "correct_answer": "语境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的语境很温柔。", "explanation": "这里误把“语境”当成〈氛围〉的意思。语境指说话或做事时周围的情况和背景；形容歌曲的感觉要说〈氛围〉。"}, {"text": "这个房间的语境很大。", "explanation": "这里误把“语境”当成〈空间〉。语境指说话或做事时周围的情况，不指房间的大小；形容房间大要说“很大”。"}, {"text": "今天路上的交通语境很糟糕。", "explanation": "这里应该用〈情况〉。语境只指说话或做事周围的情况和背景，交通状况要说“情况”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "语境", "is_correct": true, "explanation": "指说话或做事时周围的真实情况，符合“孩子在真实的……里学说话”的句意。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书籍，不能指孩子说话时周围的真实情况。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是物品，不指孩子学说话时周围的情况。"}, {"text": "词典", "is_correct": false, "explanation": "搭配：“真实的”不修饰“词典”，词典也不是生活中的真实情况。"}], "explanations": {"语境": "指说话或做事时周围的真实情况，符合“孩子在真实的……里学说话”的句意。", "课本": "语义：“课本”是书籍，不能指孩子说话时周围的真实情况。", "玩具": "语义：“玩具”是物品，不指孩子学说话时周围的情况。", "词典": "搭配：“真实的”不修饰“词典”，词典也不是生活中的真实情况。"}, "sentence_index": 6, "correct_answer": "语境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的语境很烫。", "explanation": "这里应该用〈温度〉。语境指说话或做事时周围的情况，不指食物的温度；形容汤的温度要说“很烫”。"}, {"text": "这位老师的语境很认真。", "explanation": "这里误把“语境”当成〈态度〉的意思。语境指说话或做事时周围的情况，不能描述人的态度；形容老师的做事态度要说“态度认真”。"}, {"text": "这个公园的语境很漂亮。", "explanation": "这里应该用〈环境〉。语境指说话或做事时的情况；描述公园的风景要说“环境”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "同学们要语境理解词义。", "corrected_sentence": "同学们要根据语境理解词义。", "error_description": "错误：介词“根据”漏掉了，“语境”直接放在动词前，句子不通。正确：应说“根据语境理解词义”，“根据语境”作状语，表示依据。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里有一座特殊的语境。", "corrected_sentence": "这里有一种特殊的语境。", "error_description": "错误：量词“座”用错了。正确：语境是抽象名词，应用量词“种”；“座”用于山、房屋等大型固定的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "忽视", "is_correct": true, "explanation": "正确。“忽视”与“注重”意思相反，指不予重视。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”指休息入眠，与重视或忽视没有关系。"}, {"text": "游泳", "is_correct": false, "explanation": "无关：“游泳”指在水中活动，与重视或忽视没有关系。"}, {"text": "烧饭", "is_correct": false, "explanation": "无关：“烧饭”指做饭，与重视或忽视没有关系。"}], "correct_answer": "忽视", "explanations": {"忽视": "正确。“忽视”与“注重”意思相反，指不予重视。", "睡觉": "无关：“睡觉”指休息入眠，与重视或忽视没有关系。", "游泳": "无关：“游泳”指在水中活动，与重视或忽视没有关系。", "烧饭": "无关：“烧饭”指做饭，与重视或忽视没有关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
