INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把心思放在重要的事情上。", "primary_collocate": null, "pronunciation": "zhù zhòng", "ipa": "ʈʂu˥˩ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学外语要注重听和说。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "写文章时，他注重细节。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们应该注重身体健康。", "target_word": "注重", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她做事注重效率，从不拖拉。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次比赛，教练更注重团队合作。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话很注重方式，不会让人难过。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子学习时，要注重方法，不要只靠时间。", "target_word": "注重", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事注重每一个小细节，从不马虎。", "target_word": "注重", "complexity_tier": "T3", "furigana": "zhù zhòng", "sentence_source": "generated"}, {"text": "工作时，我们要注重安全，别着急。", "target_word": "注重", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板注重员工的想法，所以大家都愿意说话。", "target_word": "注重", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "注重了", "label": "体标"}, {"form": "注重过", "label": "体标"}], "register": "中性", "sense_fingerprint": "注重：把心思和精力放在重要的方面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49e41cf2-2347-44e6-8502-a9cbc2576a49') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "注重", "is_correct": true, "explanation": "正确。“注重听和说”指把心思放在听和说的训练上，符合“把心思放在重要的事情上”的意思。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”与“要……”的积极要求相反，句子语义不通。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：“拖延”表示推迟，与“把心思放在重要的事情上”相反。"}, {"text": "违反", "is_correct": false, "explanation": "搭配：“违反”带的是规定或规则，不能说“违反听和说”。"}], "explanations": {"注重": "正确。“注重听和说”指把心思放在听和说的训练上，符合“把心思放在重要的事情上”的意思。", "忘记": "语义：“忘记”与“要……”的积极要求相反，句子语义不通。", "拖延": "语义：“拖延”表示推迟，与“把心思放在重要的事情上”相反。", "违反": "搭配：“违反”带的是规定或规则，不能说“违反听和说”。"}, "sentence_index": 0, "correct_answer": "注重"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在路上突然注重一辆车，一直盯着看。", "explanation": "这里应该用〈注意〉（注意到一辆车）。注重表示长期看重，不能描述路上突然留意到某物。"}, {"text": "学生在外面要注重陌生人，别跟他们走。", "explanation": "这里应该用〈警惕〉。警惕指提高戒备、防备危险；“注重陌生人”不表示这个意思。"}, {"text": "过马路要注重车辆，别分心。", "explanation": "这里应该用〈留神〉。留神指小心留意眼前的情况；注重表示长期看重的事，不适用于过马路时的即时提醒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "注重", "is_correct": true, "explanation": "正确。“注重方法”与“不要只靠时间”形成对比，符合“把心思放在重要的事情上”的定义。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示讥笑，与“要”所表达的积极要求相反，句子语义不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象多是物体或身体部位，不能说“咬方法”。"}, {"text": "鼓掌", "is_correct": false, "explanation": "搭配：“鼓掌”是动作，不能与“方法”搭配，说“鼓掌方法”不通。"}], "explanations": {"注重": "正确。“注重方法”与“不要只靠时间”形成对比，符合“把心思放在重要的事情上”的定义。", "嘲笑": "语义：“嘲笑”表示讥笑，与“要”所表达的积极要求相反，句子语义不通。", "咬": "搭配：“咬”的对象多是物体或身体部位，不能说“咬方法”。", "鼓掌": "搭配：“鼓掌”是动作，不能与“方法”搭配，说“鼓掌方法”不通。"}, "sentence_index": 6, "correct_answer": "注重"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他注重碗里的油污，洗了很久才洗干净。", "explanation": "这里应该用〈清除〉（清除油污）。注重表示看重某事，不能表示去掉油污。"}, {"text": "我在窗前注重一朵白云，看了很久。", "explanation": "这里应该用〈欣赏〉（欣赏一朵白云）。注重表示看重某事，不能表示观赏景物。"}, {"text": "她注重着窗外的雪，忘了吃饭。", "explanation": "这里应该用〈凝望〉。注重表示心理上的看重，不能表示目光持续地望向窗外。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学习外语应该注重了口语。", "corrected_sentence": "学习外语应该注重口语。", "error_description": "“了”表示已完成，与“应该”表示的应然语气不符，应去掉“了”，说“应该注重口语”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前从来没注重了细节。", "corrected_sentence": "他以前从来没注重过细节。", "error_description": "体标错误：“从来没”否定过去经历，应与“过”搭配，不能用“了”，应说“从来没注重过细节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe86ea35-00e5-4cb6-b3e0-3f80d80fa69e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22560, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "宽松", "is_correct": true, "explanation": "宽松：对要求不苛刻，与“严格要求”相反，是反义词。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮：形容光线或颜色，与“严格”没有反义关系。"}, {"text": "迅速", "is_correct": false, "explanation": "迅速：形容速度快，与“严格”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂：形容事情或结构繁多，与“严格”没有反义关系。"}], "correct_answer": "宽松", "explanations": {"宽松": "宽松：对要求不苛刻，与“严格要求”相反，是反义词。", "明亮": "明亮：形容光线或颜色，与“严格”没有反义关系。", "迅速": "迅速：形容速度快，与“严格”没有反义关系。", "复杂": "复杂：形容事情或结构繁多，与“严格”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22560, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22560, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事或说话时，对自己或他人要求一定要做到，不能随便。", "primary_collocate": null, "pronunciation": "yán gé", "ipa": "jɛn˧˥ kɤ˧˥", "syllable_count": 2, "sentences": [{"text": "王老师对学生很严格。", "target_word": "严格", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对自己要求很严格。", "target_word": "严格", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司的规定非常严格。", "target_word": "严格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校严格要求学生按时到校。", "target_word": "严格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈对我吃糖的次数管得很严格。", "target_word": "严格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生严格控制他每天吃盐的量。", "target_word": "严格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "运动员的训练非常严格，每天六点就起床。", "target_word": "严格", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，老师的要求很严格，不能看手机。", "target_word": "严格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个严格的人，做事从来不马虎。", "target_word": "严格", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们严格按照说明书把机器装好了。", "target_word": "严格", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嚴格", "label": "繁体"}, {"form": "严格地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "对自己或他人要求一定要做到、不随便", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54dc7929-d038-45aa-8c18-bc8b7ecc58a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22560, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "严格", "is_correct": true, "explanation": "对学生要求很高、不随便，符合句意。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或外观，不形容老师对学生的态度。"}, {"text": "沉重", "is_correct": false, "explanation": "语义：“沉重”形容心情或负担，不能用来形容老师对学生的态度。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”形容地面或道路，不能用来形容人。"}], "explanations": {"严格": "对学生要求很高、不随便，符合句意。", "整齐": "搭配：“整齐”形容排列或外观，不形容老师对学生的态度。", "沉重": "语义：“沉重”形容心情或负担，不能用来形容老师对学生的态度。", "平坦": "语义：“平坦”形容地面或道路，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "严格"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张桌子很严格。", "explanation": "这里误用“严格”形容桌子。“严格”只用于对人或规定的要求，形容桌子结实要说〈结实〉。"}, {"text": "这个周末的天气很严格。", "explanation": "“严格”用于对人或规定的要求，不用来形容天气；天气寒冷要说〈严寒〉。"}, {"text": "他严格地高兴起来了。", "explanation": "“严格”修饰的是要求或做法，不能修饰感受；这里应说〈真的〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22560, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "严格", "is_correct": true, "explanation": "要求高、不随便，与“每天六点就起床”的强度相符。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：“清淡”形容味道或颜色，不能用来形容训练。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，与训练的强度不合，句意不通。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能用来形容训练。"}], "explanations": {"严格": "要求高、不随便，与“每天六点就起床”的强度相符。", "清淡": "搭配：“清淡”形容味道或颜色，不能用来形容训练。", "柔软": "语义：“柔软”形容质地，与训练的强度不合，句意不通。", "鲜艳": "搭配：“鲜艳”形容颜色，不能用来形容训练。"}, "sentence_index": 6, "correct_answer": "严格"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "病情很严格。", "explanation": "这里应该用〈严重〉。严重指程度厉害，病情要说“严重”；“严格”只用于对要求的把握。"}, {"text": "他严格地喜欢上了这首歌。", "explanation": "“严格”用于做事或要求，不能修饰感情；表示喜欢的程度要说〈非常〉。"}, {"text": "这盏灯的亮度很严格。", "explanation": "“严格”用于对要求的把握，不能描述亮度；形容亮度要说〈强〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22560, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对待工作很非常严格。", "corrected_sentence": "他对待工作非常严格。", "error_description": "错误：程度副词“很”与“非常”连用，重复表示程度。正确：只用“非常”修饰“严格”，说“非常严格”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22560, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条规定执行地很严格。", "corrected_sentence": "这条规定执行得很严格。", "error_description": "错误：“地”用错了，动词“执行”后带补语“很严格”，补语前要用“得”。正确：应说“执行得很严格”；“地”只用于动词前作状语，如“严格地执行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1338d89-9119-48bf-b0a7-9b63312caa18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
