INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "情境就是一个人在做事情时，周围的样子和情况。", "primary_collocate": null, "pronunciation": "qíng jìng", "ipa": "tɕʰiŋ˧˥ tɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在安静的情境里，孩子更容易学习。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师为学生创设了一个下雪天的情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个相似的情境让他想起了小时候的事。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请大家说说自己做作业时的情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的情境太紧张，他一句话也说不出来。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你描述一下当时的情境。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这样的情境下，谁都会害怕。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在游戏情境中学会了说英语。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在轻松的情境里工作。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人在陌生的情境里，常常会变得拘谨。", "target_word": "情境", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "通用", "sense_fingerprint": "人做事时周围的样子和情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2900ff34-7b63-430a-b418-659efc01403e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：“安静”可以修饰环境或声音，不能修饰颜色，“安静的颜色”不通。"}, {"text": "气味", "is_correct": false, "explanation": "搭配：“安静”不能修饰气味，“安静的气味”不成立。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气指人的性情，不是孩子学习所处的场所，“在安静的脾气里”文意不通。"}, {"text": "情境", "is_correct": true, "explanation": "情境指人做事时周围的样子和情况，这里指孩子学习时安静的周围情况，符合语境。"}], "explanations": {"颜色": "搭配：“安静”可以修饰环境或声音，不能修饰颜色，“安静的颜色”不通。", "气味": "搭配：“安静”不能修饰气味，“安静的气味”不成立。", "脾气": "语义：脾气指人的性情，不是孩子学习所处的场所，“在安静的脾气里”文意不通。", "情境": "情境指人做事时周围的样子和情况，这里指孩子学习时安静的周围情况，符合语境。"}, "sentence_index": 0, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要保护好地球的情境，不能乱扔垃圾。", "explanation": "这里应该用〈环境〉。保护的是自然界的环境；情境指人做事时周围的情况，不用于说大自然。"}, {"text": "他今天的情境很好，一直在笑。", "explanation": "这里应该用〈心情〉。说人的内心感受要用心情；情境指外部周围的情况，不指人的情绪。"}, {"text": "他在公司的情境很高，大家都很尊敬他。", "explanation": "这里应该用〈地位〉。说在公司的身份高低要用地位；情境指周围的样子和情况，不用于说人的社会地位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口味", "is_correct": false, "explanation": "搭配：“口味”指食物或饮食的偏好，不能用“在…下”说明让人害怕的情况。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材描述人的体型，不能说明让人害怕的周围情况，“在这样的身材下”不通。"}, {"text": "头发", "is_correct": false, "explanation": "搭配：头发是身体部位，不能作为“在…下”的情况，“在这样的头发下”不成立。"}, {"text": "情境", "is_correct": true, "explanation": "情境指人做事时周围的样子和情况，这里指让人害怕的周围情况，符合语境。"}], "explanations": {"口味": "搭配：“口味”指食物或饮食的偏好，不能用“在…下”说明让人害怕的情况。", "身材": "体貌：身材描述人的体型，不能说明让人害怕的周围情况，“在这样的身材下”不通。", "头发": "搭配：头发是身体部位，不能作为“在…下”的情况，“在这样的头发下”不成立。", "情境": "情境指人做事时周围的样子和情况，这里指让人害怕的周围情况，符合语境。"}, "sentence_index": 6, "correct_answer": "情境"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的情境很晴朗，适合去郊游。", "explanation": "这里应该用〈天气〉。晴朗形容天气；情境指人做事时周围的样子和情况，不用于说天气。"}, {"text": "这个孩子的情境很开朗，喜欢和大家一起玩。", "explanation": "这里应该用〈性格〉。开朗形容的是性格；情境指周围的样子和情况，不用于形容人的性格。"}, {"text": "这个包的情境很结实。", "explanation": "这里应该用〈材料〉。说物品结不结实要看它的材料；情境指人做事时周围的样子和情况，不用于形容物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在游戏里创造了一件有趣的情境。", "corrected_sentence": "我们在游戏里创造了一种有趣的情境。", "error_description": "量词错误：“情境”应用量词“种”，不能用“件”（件多用于事情、物品）。正确说法是“一种有趣的情境”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个让人放松情境。", "corrected_sentence": "这是一个让人放松的情境。", "error_description": "“的”缺失：“让人放松”修饰“情境”，中间要加“的”，应说“让人放松的情境”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d1283e2-8344-4496-8c3c-161395dbbc81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
