INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人做的事情。", "primary_collocate": null, "pronunciation": "xíng wéi", "ipa": "ɕiŋ˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "孩子的坏行为，要马上告诉他不对。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师夸他帮助同学的行为很好。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在公共场所大声说话是不好的行为。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为让大家很生气。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事的奇怪行为引起了我的注意。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要为自己的行为负责。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "偷东西是违法的行为。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他这种行为太不礼貌了。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心理学家正在研究人的行为。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母的行为会影响孩子。", "target_word": "行为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "行为举止", "label": "复合"}], "register": "中性", "sense_fingerprint": "人做出的事情，指表现出来的做法或举动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22564, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行为", "is_correct": true, "explanation": "行为 xíngwéi 指人做的事情或表现出来的举止，是正确答案。"}, {"text": "腥味", "is_correct": false, "explanation": "腥味 xīngwèi 与 行为 xíngwéi 两个音节的声调都不同（xīng 第一声，wèi 第四声），意思是腥的气味。"}, {"text": "形位", "is_correct": false, "explanation": "形位 xíngwèi 与 行为 xíngwéi 只有第二音节声调不同（wèi 第四声），是语言学术语，意思不同。"}, {"text": "行尾", "is_correct": false, "explanation": "行尾 xíngwěi 与 行为 xíngwéi 只有第二音节声调不同（wěi 第三声），意思是一行的末尾。"}], "explanations": {"行为": "行为 xíngwéi 指人做的事情或表现出来的举止，是正确答案。", "腥味": "腥味 xīngwèi 与 行为 xíngwéi 两个音节的声调都不同（xīng 第一声，wèi 第四声），意思是腥的气味。", "形位": "形位 xíngwèi 与 行为 xíngwéi 只有第二音节声调不同（wèi 第四声），是语言学术语，意思不同。", "行尾": "行尾 xíngwěi 与 行为 xíngwéi 只有第二音节声调不同（wěi 第三声），意思是一行的末尾。"}, "sentence_index": null, "correct_answer": "行为"}, "level_3": {"options": [{"text": "行为", "is_correct": true, "explanation": "行为指人做的事情，与“孩子的坏行为，要马上告诉他不对”的句意相符，是正确答案。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是孩子做的事，无法“告诉他不对”，与纠正过错的句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“坏”不能修饰体重，“坏体重”不是常见说法，且与纠正过错的句意不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“坏”不用来形容颜色，句子要表达的是孩子的过错，“坏颜色”不通。"}], "explanations": {"行为": "行为指人做的事情，与“孩子的坏行为，要马上告诉他不对”的句意相符，是正确答案。", "天气": "语义：天气是自然现象，不是孩子做的事，无法“告诉他不对”，与纠正过错的句意不符。", "体重": "搭配：“坏”不能修饰体重，“坏体重”不是常见说法，且与纠正过错的句意不符。", "颜色": "搭配：“坏”不用来形容颜色，句子要表达的是孩子的过错，“坏颜色”不通。"}, "sentence_index": 0, "correct_answer": "行为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们应该立刻采取行为来解决这个问题。", "explanation": "这里应该用〈行动〉。采取行动指具体去做某件事，“行为”多指人的品德或举止，不说“采取行为”。"}, {"text": "这种行为的颜色很鲜艳，老远就能看见。", "explanation": "这里应该用〈衣服〉。“行为”是抽象的做法，没有颜色，应换成有颜色的具体事物。"}, {"text": "他把这个行为装进了箱子里。", "explanation": "这里应该用〈东西〉之类指具体物件的词。“行为”指人做的事，是抽象的，不能像“东西”一样装进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行为", "is_correct": true, "explanation": "行为指人做的事情，与“偷东西是违法的行为”的句意相符，是正确答案。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节指一年中的时段，不是可以违法的对象，“违法的季节”不通。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“违法”修饰的是行为，不能修饰身高，“违法的身高”不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象的时段，不能被说成违法，句子说的是偷窃这种做法。"}], "explanations": {"行为": "行为指人做的事情，与“偷东西是违法的行为”的句意相符，是正确答案。", "季节": "语义：季节指一年中的时段，不是可以违法的对象，“违法的季节”不通。", "身高": "搭配：“违法”修饰的是行为，不能修饰身高，“违法的身高”不通。", "时间": "语义：时间是抽象的时段，不能被说成违法，句子说的是偷窃这种做法。"}, "sentence_index": 6, "correct_answer": "行为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的行为扛起了一袋大米。", "explanation": "这里应该用〈双臂〉。扛东西要靠身体的部位，“行为”是抽象的做法，不能扛起东西。"}, {"text": "他说了一句很有意思的行为。", "explanation": "“行为”指做的事或举止，说出的话要用“话”，不能用“行为”指言语。"}, {"text": "他挥手的行为很快，大家都没看清。", "explanation": "这里应该用〈动作〉。描述身体动作的快慢用“动作”，“行为”指人的做法或品德。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只行为很不好。", "corrected_sentence": "这种行为很不好。", "error_description": "量词错误：“行为”的量词应是“种”，“只”多用于动物或单个物体，应说“这种行为”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些行为们都很奇怪。", "corrected_sentence": "这些行为都很奇怪。", "error_description": "词缀错误：“们”只用于指人的复数，“行为”是抽象名词，不能加“们”，应说“这些行为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
