INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22566, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指动物、植物、山水等本来就有、不是人造的东西。", "primary_collocate": null, "pronunciation": "zì rán", "ipa": "tsɻ̩˥˩ ɻan˧˥", "syllable_count": 2, "sentences": [{"text": "我喜欢走进自然，看山和水。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们带孩子去亲近自然。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们应该保护自然。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在自然里，动物和植物一起生活。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷热爱自然，常常去山里走走。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍的是美丽的自然。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想回到自然，过安静的生活。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书让孩子认识自然。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自然给了我们空气和水。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要破坏自然，它是我们的家。", "target_word": "自然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大自然", "label": "复合"}, {"form": "自然界", "label": "复合"}], "register": "中性", "sense_fingerprint": "山水、动植物等不是人造的自然界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '893d22fe-4f1c-4df4-bc7b-16eb250f9a8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22566, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然", "is_correct": true, "explanation": "正确：“走进自然”指进入山水动植物的环境，与“看山和水”相合。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房里看不到山水，与“看山和水”不合。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“走进”后接地点，一般不说“走进电脑”。"}, {"text": "博物馆", "is_correct": false, "explanation": "语义：博物馆不是“看山和水”的地方，与“走进自然”的意思不合。"}], "explanations": {"自然": "正确：“走进自然”指进入山水动植物的环境，与“看山和水”相合。", "厨房": "语义：厨房里看不到山水，与“看山和水”不合。", "电脑": "搭配：“走进”后接地点，一般不说“走进电脑”。", "博物馆": "语义：博物馆不是“看山和水”的地方，与“走进自然”的意思不合。"}, "sentence_index": 0, "correct_answer": "自然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的自然很好。", "explanation": "这里应该用〈性能〉。自然指山水动植物等本来就有的东西，不能用来指机器的性能，这里应说“性能很好”。"}, {"text": "这家餐厅的自然很干净。", "explanation": "这里应该用〈环境〉。“环境”指周围条件，“自然”专指山水动植物等，不能说“餐厅的自然”。"}, {"text": "我们在自然里开了一家公司。", "explanation": "这里应该用〈城市〉。公司开在城市里，不说“在自然里开公司”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22566, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然", "is_correct": true, "explanation": "正确：“回到自然”指回到山水田园之中，与“过安静的生活”相合。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂噪音大，不能说“回到工厂，过安静的生活”。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场很喧闹，与“安静的生活”相反。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：“回到”后接地点，不说“回到字典”。"}], "explanations": {"自然": "正确：“回到自然”指回到山水田园之中，与“过安静的生活”相合。", "工厂": "语义：工厂噪音大，不能说“回到工厂，过安静的生活”。", "游乐场": "语义：游乐场很喧闹，与“安静的生活”相反。", "字典": "搭配：“回到”后接地点，不说“回到字典”。"}, "sentence_index": 6, "correct_answer": "自然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的自然很便宜。", "explanation": "这里应该用〈价格〉。自然指山水动植物等，不能用来指衣服的价格，这里应说“价格很便宜”。"}, {"text": "我们要把自然放进冰箱。", "explanation": "这里应该用〈食物〉。自然指山水动植物等，不能放进冰箱。"}, {"text": "这家公司的自然很大，有上千名员工。", "explanation": "这里应该用〈规模〉。“自然”指山水动植物，不能用来指公司的规模。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22566, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "自然们给了我们新鲜的空气和干净的河水。", "corrected_sentence": "自然给了我们新鲜的空气和干净的河水。", "error_description": "错误：“自然们”。正确：“自然”。“们”只用于指人的名词，“自然”不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22566, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他喜欢在自然上散步。", "corrected_sentence": "他喜欢在自然中散步。", "error_description": "“在……中”表示范围，应说“在自然中散步”，“上”表示接触的表面，不能用于这里的范围。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8af75b2c-0408-4d56-8e08-952c971b706f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
