INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22568, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让事情继续下去，不停止。", "primary_collocate": null, "pronunciation": "wéi xì", "ipa": "weɪ˧˥ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "感情需要双方一起维系。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作只能勉强维系一家人的生计。", "target_word": "维系", "complexity_tier": "T3", "furigana": "zhè fèn gōng zuò zhǐ néng miǎn qiǎng wéi xì yì jiā rén de shēng jì", "sentence_source": "generated"}, {"text": "他们靠书信维系着友谊。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经常见面才能维系朋友的感情。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家小店靠老客人维系了多年。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每月一次的电话维系着母子的关系。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有信任，婚姻很难维系下去。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用钱维系这段关系，但没有成功。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家人的爱维系着这个家。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她努力维系公司的正常运转。", "target_word": "维系", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "维系着", "label": "持续体"}, {"form": "维系了", "label": "完成体"}, {"form": "维系过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "使感情、关系、生活等持续不断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9733c-8de7-4445-b4c8-56f8fe774a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "破坏", "is_correct": false, "explanation": "语义：「需要双方一起」的语境要求持续经营，破坏与之相反。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：打扫用于场所和物品，不用于感情。"}, {"text": "维系", "is_correct": true, "explanation": "维系：让感情持续下去，与「需要双方一起」相合。"}, {"text": "抵达", "is_correct": false, "explanation": "配价：抵达需要一个处所作宾语，这里没有，意思也不通。"}], "explanations": {"破坏": "语义：「需要双方一起」的语境要求持续经营，破坏与之相反。", "打扫": "搭配：打扫用于场所和物品，不用于感情。", "维系": "维系：让感情持续下去，与「需要双方一起」相合。", "抵达": "配价：抵达需要一个处所作宾语，这里没有，意思也不通。"}, "sentence_index": 0, "correct_answer": "维系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他维系了坏掉的电脑。", "explanation": "这里应该用〈修理〉。维系指让关系、生活等持续，不用于把机器修好。"}, {"text": "大家维系了这个问题。", "explanation": "这里应该用〈讨论〉。维系指使事情持续，不指对问题发表看法。"}, {"text": "他维系了一只杯子。", "explanation": "这里应该用〈洗〉。维系指让关系、感情、生活等持续，不用于清洗器物；洗杯子要用〈洗〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "继承", "is_correct": false, "explanation": "搭配：继承的对象是财产、传统等，不说继承婚姻。"}, {"text": "生产", "is_correct": false, "explanation": "语义：生产指制造物品，婚姻不能被生产出来，语境不通。"}, {"text": "维系", "is_correct": true, "explanation": "维系：使婚姻持续，与「很难……下去」相合。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：粉碎指打成碎片，与「很难……下去」的持续语义相反。"}], "explanations": {"继承": "搭配：继承的对象是财产、传统等，不说继承婚姻。", "生产": "语义：生产指制造物品，婚姻不能被生产出来，语境不通。", "维系": "维系：使婚姻持续，与「很难……下去」相合。", "粉碎": "语义：粉碎指打成碎片，与「很难……下去」的持续语义相反。"}, "sentence_index": 6, "correct_answer": "维系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视台维系了新闻。", "explanation": "这里应该用〈播放〉。维系指使事情持续，不指把新闻放送出去。"}, {"text": "他维系了一台新机器。", "explanation": "这里应该用〈发明〉。维系指保持持续，不指创造新事物。"}, {"text": "妈妈维系了一桌好菜。", "explanation": "这里应该用〈做〉。维系指使关系、生活等持续，不指做饭；做菜要用〈做〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22568, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位老人靠一些老照片维系了着回忆。", "corrected_sentence": "这位老人靠一些老照片维系着回忆。", "error_description": "「维系」带「着」表示持续，「了」与「着」不能同时出现。应为「维系着回忆」，去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22568, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段友谊全靠双方的努力维系上去。", "corrected_sentence": "这段友谊全靠双方的努力维系下去。", "error_description": "「上去」表示向上的趋向，不能表示关系或事情的持续；「维系」表示持续，应使用「下去」。应为「维系下去」，只需把「上」改为「下」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
