INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22570, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "照着做，不违反。", "primary_collocate": null, "pronunciation": "zūn xún", "ipa": "tsuən˥ ɕyn˧˥", "syllable_count": 2, "sentences": [{"text": "我们应该遵循学校的规定。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做实验时，要遵循老师给的步骤。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车的人必须遵循交通规则。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直遵循着父母的教导。", "target_word": "遵循", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的员工都要遵循这个原则。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写文章要遵循一定的格式。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏有规则，大家都要遵循。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们遵循科学的方法做研究。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她遵循医生的建议，每天早睡。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "植物的生长遵循自然的规律。", "target_word": "遵循", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "遵循了", "label": "体标（了）"}, {"form": "遵循过", "label": "体标（过）"}, {"form": "遵循着", "label": "体标（着）"}], "register": "书面", "sense_fingerprint": "按照规定、原则或建议去做而不违反", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d72c37e-001c-46ce-9b8e-ae187f9ffc54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遵循", "is_correct": true, "explanation": "遵循：照着规定做，与“应该”搭配，符合句意。"}, {"text": "违反", "is_correct": false, "explanation": "语义：“违反”指不照规定做，与“应该”的要求正好相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：规定本身不是用来嘲笑的，“应该嘲笑”读起来不合常理。"}, {"text": "摸", "is_correct": false, "explanation": "搭配：“摸”指用手触碰实物，不能说摸规定。"}], "explanations": {"遵循": "遵循：照着规定做，与“应该”搭配，符合句意。", "违反": "语义：“违反”指不照规定做，与“应该”的要求正好相反。", "嘲笑": "语义：规定本身不是用来嘲笑的，“应该嘲笑”读起来不合常理。", "摸": "搭配：“摸”指用手触碰实物，不能说摸规定。"}, "sentence_index": 0, "correct_answer": "遵循"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子很懂事，总是遵循老师。", "explanation": "这里应该用〈听从〉。遵循用于规定、原则、规律，指照着标准去做，不能直接以人作对象。"}, {"text": "战场上，士兵必须遵循上级。", "explanation": "这里应该用〈服从〉。遵循针对的是规定和原则，不用来指向上级这样的人。"}, {"text": "她总是遵循丈夫，从不反驳。", "explanation": "这里应该用〈顺从〉。遵循是按规定或原则去做，不能用来表示对某个人的顺从。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遵循", "is_correct": true, "explanation": "遵循：与“有规则”呼应，表示照规则去做。"}, {"text": "打破", "is_correct": false, "explanation": "语义：打破规则与“大家都要”的要求相反，句意不通。"}, {"text": "搬走", "is_correct": false, "explanation": "搭配：“搬走”针对具体的东西，不能用来说规则。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：忽略规则与“游戏有规则”相矛盾，也不符合“大家都要”。"}], "explanations": {"遵循": "遵循：与“有规则”呼应，表示照规则去做。", "打破": "语义：打破规则与“大家都要”的要求相反，句意不通。", "搬走": "搭配：“搬走”针对具体的东西，不能用来说规则。", "忽略": "语义：忽略规则与“游戏有规则”相矛盾，也不符合“大家都要”。"}, "sentence_index": 6, "correct_answer": "遵循"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新兵遵循着队伍前进，不敢掉队。", "explanation": "这里应该用〈跟随〉。遵循指照着规定或原则去做，不指身体跟在队伍后面走。"}, {"text": "小船遵循河流漂下去。", "explanation": "这里应该用〈顺着〉。遵循表示按规定、规律去做，不能用来指沿着河流移动。"}, {"text": "他遵循脚步声走过去。", "explanation": "这里应该用〈跟着〉。遵循不用于跟随声音或动作，这样说不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们已经遵循过着这个规则。", "corrected_sentence": "我们已经遵循过这个规则。", "error_description": "错误：“遵循过着”，“过”和“着”不能同时用在同一个动词后面。正确：“遵循过这个规则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一直遵循着了公司的制度。", "corrected_sentence": "我们一直遵循公司的制度。", "error_description": "错误：“遵循着了”，“着”与“了”不能同时用在同一个动词后面。正确：“遵循公司的制度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
