INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个东西不一样的地方。", "primary_collocate": null, "pronunciation": "chā yì", "ipa": "ʈʂʰa˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "两个城市的气候有很大差异。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种手机的价格差异不大。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方和北方的饮食差异很明显。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们俩的看法存在差异。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现了两张照片之间的差异。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文化差异有时会带来误会。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎的性格也有差异。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请找出这两个句子的差异。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年龄差异没有影响他们的友谊。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个词的意思有细微的差异。", "target_word": "差异", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文化差异", "label": "复合"}, {"form": "差异性", "label": "复合"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "事物之间不相同的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ca9733c-8de7-4445-b4c8-56f8fe774a2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "寿命", "is_correct": false, "explanation": "语义：气候没有寿命，这里说不通。"}, {"text": "体量", "is_correct": false, "explanation": "搭配：体量多用于建筑或物体，不说气候的体量。"}, {"text": "差异", "is_correct": true, "explanation": "差异：两者不一样的地方，与「有很大」相合。"}, {"text": "歧见", "is_correct": false, "explanation": "语义：歧见指看法不同，与气候无关，这里说不通。"}], "explanations": {"寿命": "语义：气候没有寿命，这里说不通。", "体量": "搭配：体量多用于建筑或物体，不说气候的体量。", "差异": "差异：两者不一样的地方，与「有很大」相合。", "歧见": "语义：歧见指看法不同，与气候无关，这里说不通。"}, "sentence_index": 0, "correct_answer": "差异"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两地的差异很远。", "explanation": "这里应该用〈距离〉。差异指不一样的地方，不能用来说空间的远近。"}, {"text": "他花了很长差异准备。", "explanation": "这里应该用〈时间〉。差异不表示时间的长短。"}, {"text": "我们学校来了一个差异。", "explanation": "这里应该用〈学生〉。差异指两个东西不一样的地方，不指人；说来了一个人要用〈学生〉这类表示人的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度，不是性格的特点，这里说不通。"}, {"text": "差异", "is_correct": true, "explanation": "差异：两者不一样的地方，与「性格也有」相合。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高指人体的高度，性格没有身高。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只指人的体形，不能用来说性格。"}], "explanations": {"体温": "语义：体温是人体的温度，不是性格的特点，这里说不通。", "差异": "差异：两者不一样的地方，与「性格也有」相合。", "身高": "语义：身高指人体的高度，性格没有身高。", "身材": "体貌：身材只指人的体形，不能用来说性格。"}, "sentence_index": 6, "correct_answer": "差异"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着差异去上学。", "explanation": "这里应该用〈自行车〉。差异是抽象名词，不指交通工具；骑着去上学要用〈自行车〉。"}, {"text": "他的差异有一米八。", "explanation": "这里应该用〈身高〉。差异不表示身体的高度。"}, {"text": "他们在差异见面。", "explanation": "这里应该用〈公园〉。差异是抽象名词，不指地点；见面的地方要用〈公园〉等具体场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种产品之间有一条差异。", "corrected_sentence": "这两种产品之间有一点差异。", "error_description": "“差异”前面的量词应用“点”，“条”用于细长的东西，不能用来量“差异”，应为「一点差异」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这对双胞胎的长相有一条差异。", "corrected_sentence": "这对双胞胎的长相有一点差异。", "error_description": "“差异”前面的量词应用“点”。“条”用于细长的东西，不能用来量“差异”，应为「一点差异」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5f58ffc-6f24-4903-b4bc-ac6c3798cf06') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
