INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22576, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指两个人或两个团体中，不是自己这一边的那个。", "primary_collocate": null, "pronunciation": "lìng yì fāng", "ipa": "liŋ˥˩ i˥˩ faŋ˥", "syllable_count": 3, "sentences": [{"text": "吵架的时候，另一方一直不说话。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛中，一方进攻，另一方防守。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我同意了，可是另一方还没有回答。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两家公司谈了很久，另一方还是不让步。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友之间，不能只想自己，也要想另一方。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说完以后，另一方马上给了回答。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很生气，但是另一方根本不知道原因。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打电话时，要听听另一方怎么说。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两个人谈恋爱，一方太忙，另一方会孤单。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我已经道歉了，另一方也应该原谅我。", "target_word": "另一方", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：两个人或团体中，不是自己这一边的那个人或团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73399449-2470-45bf-a42c-72fe9fbc4333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22576, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "另一方", "is_correct": true, "explanation": "与吵架中的自己一方相对，指争执中不是自己这一方的人，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是吵架的一方，也不会说话，这里讲的是人之间的争执。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“吵架”的主语应是人，“桌子”与“吵架”这一语境不搭配。"}, {"text": "教室", "is_correct": false, "explanation": "语义：“教室”是场所，不是争执中的一方，不能与“吵架的时候”搭配。"}], "explanations": {"另一方": "与吵架中的自己一方相对，指争执中不是自己这一方的人，符合句意。", "天气": "语义：“天气”不是吵架的一方，也不会说话，这里讲的是人之间的争执。", "桌子": "搭配：“吵架”的主语应是人，“桌子”与“吵架”这一语境不搭配。", "教室": "语义：“教室”是场所，不是争执中的一方，不能与“吵架的时候”搭配。"}, "sentence_index": 0, "correct_answer": "另一方"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们三个人一起去，另一方是小李。", "explanation": "这里应该用〈其他人〉。“另一方”只指两人或两团体中不是自己一边的那个，三个人一起时不能这样用。"}, {"text": "我的另一方都来了。", "explanation": "这里应该用〈朋友〉。“另一方”指与自己对立的一方，不用来称呼朋友。"}, {"text": "教室里坐着几个另一方。", "explanation": "这里应该用〈同学〉。“另一方”指对立的一方，不能用“几个”来计数，也不用来指一般的同学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22576, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "另一方", "is_correct": true, "explanation": "与“她”相对，指争执中不是她这一方的人，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”是物件，不会“不知道原因”，也不是争执中的一方。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是物品，不是人，不能与“根本不知道原因”搭配。"}, {"text": "红茶", "is_correct": false, "explanation": "语义：红茶是饮品，不是人，不能“不知道原因”，句意不通。"}], "explanations": {"另一方": "与“她”相对，指争执中不是她这一方的人，符合句意。", "窗户": "语义：“窗户”是物件，不会“不知道原因”，也不是争执中的一方。", "手机": "语义：“手机”是物品，不是人，不能与“根本不知道原因”搭配。", "红茶": "语义：红茶是饮品，不是人，不能“不知道原因”，句意不通。"}, "sentence_index": 6, "correct_answer": "另一方"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这双鞋，一只丢了，另一方还在。", "explanation": "这里应该用〈另一只〉。“另一方”指两个人或团体中不是自己一边的那个，不用来指东西。"}, {"text": "我有两个计划，另一方更好。", "explanation": "这里应该用〈另一个〉。“另一方”只指两人或两团体中不是自己一边的那个，不用来指计划。"}, {"text": "这盒饼干，我吃了一块，另一方还剩很多。", "explanation": "这里应该用〈其余的〉。“另一方”指人或团体，不指同一盒东西剩下的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "比赛结束后，另一方的走过来握手。", "corrected_sentence": "比赛结束后，另一方走过来握手。", "error_description": "“另一方”后直接接动词短语时不能加“的”，应说“另一方走过来握手”，不说“另一方的走过来握手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次谈判，一方提出了条件，这个另一方却拒绝了。", "corrected_sentence": "这次谈判，一方提出了条件，另一方却拒绝了。", "error_description": "“另一方”本身已指称另一边，前面不能再加“这个”，应说“另一方却拒绝了”，不说“这个另一方却拒绝了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43be901f-0c08-4621-971a-59b9e3cb02f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22578, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "反义：「抽象」指不具体、难以明白，「具体」指可以感知、落到实处，二者是反义词。"}, {"text": "香甜", "is_correct": false, "explanation": "「香甜」形容味道好，与「抽象」没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "「陡峭」形容地势或坡面，与「抽象」没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "「整齐」形容排列有序，与「抽象」没有反义关系。"}], "correct_answer": "具体", "explanations": {"具体": "反义：「抽象」指不具体、难以明白，「具体」指可以感知、落到实处，二者是反义词。", "香甜": "「香甜」形容味道好，与「抽象」没有反义关系。", "陡峭": "「陡峭」形容地势或坡面，与「抽象」没有反义关系。", "整齐": "「整齐」形容排列有序，与「抽象」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22578, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "具体", "is_correct": true, "explanation": "反义：「抽象」指不具体、难以明白，「具体」指可以感知、落到实处，二者是反义词。"}, {"text": "干燥", "is_correct": false, "explanation": "「干燥」形容含水少，与「抽象」没有反义关系。"}, {"text": "响亮", "is_correct": false, "explanation": "「响亮」形容声音大而清楚，与「抽象」没有反义关系。"}, {"text": "温暖", "is_correct": false, "explanation": "「温暖」形容温度或感受，与「抽象」没有反义关系。"}], "correct_answer": "具体", "explanations": {"具体": "反义：「抽象」指不具体、难以明白，「具体」指可以感知、落到实处，二者是反义词。", "干燥": "「干燥」形容含水少，与「抽象」没有反义关系。", "响亮": "「响亮」形容声音大而清楚，与「抽象」没有反义关系。", "温暖": "「温暖」形容温度或感受，与「抽象」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22578, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是很难让人明白、不具体的东西。", "primary_collocate": null, "pronunciation": "chōu xiàng", "ipa": "ʈʂʰou˥ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的解释太抽象，我一点也不懂。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲得很抽象，没人看得懂。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话有点抽象，请举个例子。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题太抽象了，不好回答。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很抽象，大家都听不明白。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "抽象的说明让学生觉得很难。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首诗写得很抽象，我读了三遍还是不懂。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友听不懂这么抽象的话。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书写得太抽象，我不知道怎么用。", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词很抽象，你能画出来吗？", "target_word": "抽象", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽象化", "label": "复合"}, {"form": "抽象思维", "label": "复合"}], "register": "中性", "sense_fingerprint": "说法或东西不具体、让人难以明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dd79aa37-f94d-4d21-b269-7476dce0f4e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22578, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "正确：「太抽象」说明解释不具体，与后句“我一点也不懂”的因果相合。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：「清楚」与后句“我一点也不懂”相矛盾，句意不通。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：「甜」形容味道，不能用来形容解释。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」形容人或物的体形，用来修饰解释句意不通。"}], "explanations": {"抽象": "正确：「太抽象」说明解释不具体，与后句“我一点也不懂”的因果相合。", "清楚": "语义：「清楚」与后句“我一点也不懂”相矛盾，句意不通。", "甜": "搭配：「甜」形容味道，不能用来形容解释。", "瘦": "体貌：「瘦」形容人或物的体形，用来修饰解释句意不通。"}, "sentence_index": 0, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的做法很抽象，要切十几样配料，每样都要称重。", "explanation": "这里应该用〈繁琐〉。抽象指难以让人明白、不具体，句中讲的是配料多、步骤繁，形容做法麻烦要说繁琐。"}, {"text": "这张地图画得很抽象，每条小路都标得清清楚楚。", "explanation": "这里应该用〈详细〉。抽象指难以让人明白、不具体，句中每条小路都标得清清楚楚，形容内容细致周全要说详细。"}, {"text": "这个问题的答案很抽象，只有三个字：是或否。", "explanation": "这里应该用〈简洁〉。抽象指难以让人明白、不具体，句中说答案只有“是或否”三个字，形容答案短而清楚要说简洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22578, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象", "is_correct": true, "explanation": "正确：「写得很抽象」说明诗的写法不具体，与“读了三遍还是不懂”相呼应。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：「矮小」形容人或物的个子，不能用来形容诗的写法。"}, {"text": "冰凉", "is_correct": false, "explanation": "语义：「冰凉」描述温度和触感，不能用来形容诗的风格。"}, {"text": "高耸", "is_correct": false, "explanation": "搭配：「高耸」形容建筑或山峰等挺立的高度，不能修饰诗的写法。"}], "explanations": {"抽象": "正确：「写得很抽象」说明诗的写法不具体，与“读了三遍还是不懂”相呼应。", "矮小": "体貌：「矮小」形容人或物的个子，不能用来形容诗的写法。", "冰凉": "语义：「冰凉」描述温度和触感，不能用来形容诗的风格。", "高耸": "搭配：「高耸」形容建筑或山峰等挺立的高度，不能修饰诗的写法。"}, "sentence_index": 6, "correct_answer": "抽象"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这段话很抽象，小学生一听就懂。", "explanation": "这里应该用〈通俗〉。抽象指很难让人明白，句中说小学生一听就懂，形容文字浅显易懂要说通俗。"}, {"text": "这张图纸标注得很抽象，每根螺丝的位置都写明了。", "explanation": "这里应该用〈精确〉。抽象指难以让人明白、不具体，句中每根螺丝的位置都写明了，内容具体清楚，形容标注的细致程度要说精确。"}, {"text": "这张表格做得很抽象，三个月的收入一目了然。", "explanation": "这里应该用〈清楚〉。抽象指难以让人明白，句中说收入一目了然，形容表格把数据展示得明白要说清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22578, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个说法没抽象，大家一听就懂。", "corrected_sentence": "这个说法不抽象，大家一听就懂。", "error_description": "错误形式是“没抽象”，正确形式是“不抽象”。形容词作谓语时用“不”否定，“没”用于否定动作的发生或“有”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22578, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师讲了一个抽象地比喻，同学们都笑了。", "corrected_sentence": "老师讲了一个抽象的比喻，同学们都笑了。", "error_description": "错误形式是“抽象地比喻”，正确形式是“抽象的比喻”。“地”用来修饰动词或形容词，修饰名词要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e8b41bb-0cdb-430e-9c85-967ea242069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
