INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22580, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指前面提到的两项中先提到的那一项，与“后者”相对。", "primary_collocate": null, "pronunciation": "qián zhě", "ipa": "tɕʰjɛn˧˥ ʈʂɤ˨˩˦", "syllable_count": 2, "sentences": [{"text": "红茶和绿茶，我更喜欢前者。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁和开车，前者更便宜。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习和玩，前者重要，后者也不能少。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果和香蕉，前者比后者贵。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大哥和二哥，前者是医生。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听音乐和看书，前者让我放松。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海，我去过前者。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱和健康，前者没有后者重要。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步和游泳，前者更累。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车和走路，我选前者。", "target_word": "前者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "后者", "label": "对应词"}], "register": "书面", "sense_fingerprint": "指前面提到的两件事物中的第一个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd86e809-6729-4ead-bf47-ae2786703fa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前者", "is_correct": true, "explanation": "“前者”指前面提到的两项中的第一项，这里是红茶，句意成立。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指人，不能指红茶或绿茶，“我更喜欢大家”说不通。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人本身，“我更喜欢自己”与红茶、绿茶的比较不符。"}, {"text": "人家", "is_correct": false, "explanation": "语域：“人家”口语色彩较重，与书面语的“前者”不合，而且指别人，不指饮品。"}], "explanations": {"前者": "“前者”指前面提到的两项中的第一项，这里是红茶，句意成立。", "大家": "语义：“大家”指人，不能指红茶或绿茶，“我更喜欢大家”说不通。", "自己": "语义：“自己”指说话人本身，“我更喜欢自己”与红茶、绿茶的比较不符。", "人家": "语域：“人家”口语色彩较重，与书面语的“前者”不合，而且指别人，不指饮品。"}, "sentence_index": 0, "correct_answer": "前者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "红茶、绿茶和乌龙茶，我最喜欢前者。", "explanation": "这里应该用〈第一个〉。前者只用于两项相对的情况，三项及以上要说“第一个”等。"}, {"text": "我只有一个手机，前者坏了。", "explanation": "这里应该用〈那个〉。前者必须指向前文提到的两项中的一项，这里只有一个手机。"}, {"text": "这所房子的前者是一位医生。", "explanation": "这里应该用〈前任〉。前者指两项中先提到的那一项，不指先前的房主或职位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0e3af15-64fd-4fd5-8ce3-c95c0443fb9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
